// CMT Level I 기본 정리서 마인드맵 (원본 PDF의 가지와 메모를 그대로 옮김)
// n: 요점에 붙은 메모 [종류, 내용], b: 교재 주차 번호
window.MM = [{"n":1,"t":"기술적 분석의 기초와 다우 이론","c":[{"t":"Ⅰ 기술적 분석의 개념과 기본 전제","c":[{"t":"1. 기술적 분석의 정의","c":[{"t":"(1) 기본 정의","c":[{"t":"① 기술적 분석의 정의","n":[["설명","기술적 분석(Technical Analysis)이란 시장에서 실제로 발생한 가격(Price), 거래량(Volume), 미결제약정(Open Interest), 시장 심리 데이터 등을 연구하여 미래 가격의 방향성과 확률을 판단하는 방법론이다."],["이번 주 학습목표","① 기술적 분석의 정의·기본 전제·장단점을 설명할 수 있다.\n② 기술적 분석 발전사의 주요 인물과 업적을 연결할 수 있다.\n③ 다우 이론의 6대 기본원칙(Tenets)과 추세의 3단계를 정확히 구분할 수 있다.\n④ 1차 추세와 2차 조정을 구별하는 기준, 그리고 다우 이론의 비판점을 설명할 수 있다."]]},{"t":"② 참여자 행동 흔적 해석","n":[["설명","CMT 커리큘럼에서는 기술적 분석을 \"시장 참여자들의 행동이 만들어낸 흔적(가격·거래량)을 체계적으로 해석하는 학문\"으로 본다. 즉 '무엇이 가치 있는가'보다 '참여자들이 실제로 무엇을 하고 있는가'에 초점을 둔다."]]},{"t":"③ 가격이 가장 종합적 정보","n":[["설명","가격은 수요와 공급의 결과이고, 수요와 공급은 합리적 요인(실적·금리)과 비합리적 요인(공포·탐욕·군중심리)이 모두 반영된 결과이므로, 가격 자체가 가장 종합적인 정보라는 관점을 취한다."]]}]},{"t":"(2) 기본적 분석과의 비교","c":[{"t":"① 기본적 분석: 왜(Why)","n":[["설명","기본적 분석은 \"왜(Why) 움직이는가\"를 묻는다. 기업의 재무제표, 이익, 경제지표 등을 통해 내재가치(Intrinsic Value)를 추정하고 가격이 가치보다 낮으면 매수한다."]]},{"t":"② 기술적 분석: 무엇·언제","n":[["설명","기술적 분석은 \"무엇이(What) 그리고 언제(When) 일어나는가\"를 묻는다. 가치 판단보다 타이밍(Timing), 추세(Trend), 위험관리(Risk)에 강점이 있다."]]},{"t":"③ 두 분석은 보완 관계","n":[["설명","두 방법은 대립 관계가 아니라 보완 관계이다. 실무에서는 기본적 분석으로 '무엇을' 살지 고르고 기술적 분석으로 '언제' 살지 정하는 방식(Fundamental + Technical)이 흔하다."],["표","구분 | 기본적 분석 | 기술적 분석\n핵심 질문 | 왜 움직이는가(Why) | 무엇이·언제 일어나는가(What/When)\n주요 자료 | 재무제표, 경제지표, 산업 분석 | 가격, 거래량, 미결제약정, 심리지표\n강점 | 장기 가치 판단 | 타이밍, 추세 판단, 손절 기준 제시\n약점 | 타이밍 제시 곤란, 가격이 가치에 수렴하는 시간 불확실 | 해석의 주관성, 휩소(whipsaw) 발생\n적용 기간 | 중·장기 중심 | 초단기(스캘핑)~장기 모두 가능"]]}]}]},{"t":"2. 기술적 분석의 3대 기본 전제","c":[{"t":"(1) 시장은 모든 것을 반영한다","c":[{"t":"① 모든 요인은 가격에 반영","n":[["설명","가격에 영향을 줄 수 있는 모든 요인(펀더멘털, 정치, 심리 등)은 이미 가격에 반영되어 있다는 전제이다."]]},{"t":"② 원인 몰라도 가격만 연구","n":[["설명","따라서 기술적 분석가는 가격 변동의 '원인'을 반드시 알아야 할 필요가 없으며, 가격 자체를 연구하는 것으로 충분하다고 본다."]]},{"t":"③ 다우 '평균 반영' 원칙과 연결","n":[["설명","다우 이론의 \"평균은 모든 것을 반영한다(The Averages Discount Everything)\"는 원칙과 직접 연결된다."]]}]},{"t":"(2) 가격은 추세를 이루며 움직인다","c":[{"t":"① 추세는 반전 신호까지 지속","n":[["설명","가격은 무작위로 움직이는 것이 아니라 일정 방향성(추세)을 형성하며, 한번 형성된 추세는 반전 신호가 나타날 때까지 지속될 가능성이 높다."]]},{"t":"② 관성의 법칙과 유사","n":[["설명","이는 뉴턴의 관성의 법칙과 유사하게 설명된다. 추세를 조기에 식별하고 추세 방향으로 거래하는 것이 기술적 분석의 핵심 목적이다."]]},{"t":"③ 추세는 당신의 친구","n":[["설명","기술적 분석의 명언 \"추세는 당신의 친구다(The trend is your friend)\"가 이 전제를 표현한다."]]}]},{"t":"(3) 역사는 반복된다 (History Repeats)","c":[{"t":"① 인간 심리 불변→패턴 반복","n":[["설명","인간의 심리(공포·탐욕·희망)는 시대가 변해도 크게 바뀌지 않으므로, 과거에 나타났던 가격 패턴은 미래에도 비슷한모습으로 반복된다는 전제이다."]]},{"t":"② 차트 패턴 100년 유효","n":[["설명","차트 패턴(헤드앤숄더, 삼각형 등)이 100년 이상 유효하게 사용되는 이유가 여기에 있다."]]},{"t":"③ 똑같지 않고 비슷하게 반복","n":[["설명","단, '똑같이' 반복되는 것이 아니라 '비슷하게(rhyme)' 반복된다는 점, 그리고 확률적 우위(edge)일 뿐 확실성이 아니라는 점에 유의해야 한다."],["시험 포인트","기술적 분석의 3대 전제 = ① 시장은 모든 것을 반영한다 ② 가격은 추세를 이룬다 ③ 역사는 반복된다.\n\"가격 변동의 원인을 알아야 한다\"는 기술적 분석의 전제가 아니다(오답 선지로 자주 등장)."]]}]}]},{"t":"3. 기술적 분석의 장점과 한계","c":[{"t":"(1) 장점","c":[{"t":"① 유연성: 모든 시장 적용","n":[["설명","유연성(Flexibility): 주식, 채권, 선물, 외환, 암호자산 등 가격과 거래량 데이터가 있는 모든 시장에 적용할 수 있다."]]},{"t":"② 다양한 시간 단위 적용","n":[["설명","다양한 시간 단위(Time Frame): 1분 차트부터 월간 차트까지 동일한 원리를 적용할 수 있어 스캘퍼와 장기 투자자 모두 활용한다."]]},{"t":"③ 명확한 손절 기준 제시","n":[["설명","명확한 위험관리 기준: 지지선 이탈, 추세선 붕괴 등 '틀렸음'을 판단하는 가격(무효화 지점, Invalidation)을 제시하여 손절 설정이 쉽다."]]},{"t":"④ 시장 심리의 계량화","n":[["설명","시장 심리의 계량화: 거래량, 시장폭, 심리지표를 통해 군중의 행동을 관찰할 수 있다."]]}]},{"t":"(2) 한계와 비판","c":[{"t":"① 주관성: 해석이 제각각","n":[["설명","주관성: 같은 차트를 두고 분석가마다 다른 해석을 내릴 수 있다. 이 때문에 CMT는 용어와 정의의 표준화를 중시한다."]]},{"t":"② 자기실현적 예언 논쟁","n":[["설명","자기실현적 예언(Self-fulfilling Prophecy) 논쟁: 많은 사람이 같은 신호를 보고 행동하기 때문에 맞는 것처럼 보인다는 비판이다. 반론으로, 모든 분석가가 같은 방식으로 해석하지 않으므로 완전한 자기실현은 어렵다는 주장이 있다."]]},{"t":"③ EMH 약형 효율성의 도전","n":[["설명","효율적 시장 가설(EMH)의 도전: 약형 효율성(Weak-form)이 성립한다면 과거 가격으로 초과수익을 얻을 수 없다는 비판이다(제2주차에서 상세히 다룸)."]]},{"t":"④ 후행성(Lag)","n":[["설명","후행성(Lag): 추세 추종 도구는 확인에 시간이 걸려 초기 움직임을 놓칠 수 있다."],["쉬운 예","맛집 고르기에 비유해 보자. 기본적 분석은 주방의 재료·위생·셰프 경력을 보고 '맛있을 이유'를 따지는 방법이고, 기술적 분석은 가게 앞 줄이 길어지는지 줄어드는지를 보고 판단하는 방법이다. 줄이 길어지는 이유를 몰라도, 줄의 변화 자체가 사람들의 실제 행동을 보여 준다."],["실전 사례","스캘퍼의 실전 노트 — 실적이 시장 예상보다 좋게 나왔는데도 주가가 장 시작과 함께 밀리는 경우가 흔하다. 좋은 실적에 대한 기대가 이미 가격에 들어가 있었기 때문이다('소문에 사고 뉴스에 팔아라'). 이유를 해석하기 전에 가격의 반응이 정답이라는 것이 '시장은 모든 것을 반영한다'는 전제의 실전 의미이다."]]}]}]}]},{"t":"Ⅱ 기술적 분석의 역사","c":[{"t":"1. 초기 역사","c":[{"t":"(1) 동양의 기원: 일본 쌀 시장과 캔들차트","c":[{"t":"① 도지마 쌀 거래소 선물거래","n":[["설명","18세기 일본 오사카의 도지마(Dojima) 쌀 거래소에서 세계 최초 수준의 조직화된 선물거래가 이루어졌다."]]},{"t":"② 혼마 무네히사, 캔들 시조","n":[["설명","혼마 무네히사(Munehisa Homma)는 쌀 가격과 시장 심리의 관계를 연구하여 거액의 부를 쌓은 전설적 거래자로, 캔들차트(Candlestick) 분석의 시조로 알려져 있다."]]},{"t":"③ 니슨이 서양에 캔들 소개","n":[["설명","캔들차트는 1991년 스티브 니슨(Steve Nison)의 저서 『Japanese Candlestick Charting Techniques』를 통해 서양에 본격적으로 소개되었다."]]}]},{"t":"(2) 서양의 초기 발전","c":[{"t":"① 드 라 베가 『혼돈 속의 혼돈』","n":[["설명","17세기 암스테르담 거래소의 조셉 드 라 베가(Joseph de la Vega)는 『혼돈 속의 혼돈(Confusion de Confusiones, 1688)』에서 시장 참여자의 심리와 투기 행동을 묘사하였다."]]},{"t":"② 티커 테이프 리딩","n":[["설명","19세기 후반 미국에서는 티커 테이프(Ticker Tape)를 읽는 '테이프 리딩'이 성행하였고, 이는 초기 형태의 가격·거래량 분석이었다."]]},{"t":"③ P&F, 기록 방식에서 발전","n":[["설명","포인트앤피겨(Point & Figure) 차트는 19세기 후반 '기록 방식(Book method)'에서 발전한 것으로 알려져 있으며, 시간 대신 가격 변화만 기록한다."]]}]}]},{"t":"2. 근대 기술적 분석의 주요 인물","c":[{"t":"(1) 다우 이론 계열","c":[{"t":"① 찰스 다우: DJIA 발표","n":[["설명","찰스 다우(Charles H. Dow, 1851~1902): 다우존스사와 월스트리트저널 공동 창업자이다. 1884년 최초의 주가평균을 만들었고, 1896년 다우존스 산업평균(DJIA)을 발표하였다. 이론을 책으로 정리하지 않고 WSJ 사설로 남겼다."]]},{"t":"② 해밀턴: 주식시장 바로미터","n":[["설명","윌리엄 해밀턴(William P. Hamilton): 다우의 후임 WSJ 편집자로 『주식시장 바로미터(The Stock Market Barometer, 1922)』를 통해 다우의 생각을 체계화하였다. 1929년 \"조류의 전환(A Turn in the Tide)\" 사설로 대 폭락을 경고한 것으로 유명하다."]]},{"t":"③ 레아: 『다우 이론』 체계화","n":[["설명","로버트 레아(Robert Rhea): 1932년 『다우 이론(The Dow Theory)』을 출간하여 다우와 해밀턴의 글을 가설(Hypotheses)과 정리(Theorems) 형태로 정리하였다. 오늘날 우리가 아는 '다우 이론'의 체계는 레아가 완성하였다."]]}]},{"t":"(2) 차트 패턴과 추세 분석 계열","c":[{"t":"① 샤바커: 차트 패턴 집대성","n":[["설명","리처드 샤바커(Richard W. Schabacker): 1930년대 차트 패턴 연구를 집대성한 선구자로, 강세장·약세장 종료 판별 기준('샤바커의 규칙')으로도 알려져 있다."]]},{"t":"② 에드워즈·매기의 고전","n":[["설명","에드워즈와 매기(Robert D. Edwards & John Magee): 샤바커의 연구를 발전시켜 1948년 『주가 추세의 기술적 분석(Technical Analysis of Stock Trends)』을 출간하였다. 차트 패턴 분석의 고전이다."]]},{"t":"③ 엘리엇 파동이론","n":[["설명","랄프 넬슨 엘리엇(R. N. Elliott): 1930년대 시장이 5개의 충격파와 3개의 조정파로 움직인다는 파동이론을 제시하였다."]]},{"t":"④ 갠: 가격·시간 기하학","n":[["설명","W. D. 갠(W. D. Gann): 가격과 시간의 기하학적 관계(갠 앵글 등)를 연구하였다."]]}]},{"t":"(3) 현대의 발전","c":[{"t":"① 70년대 계량 지표 폭발","n":[["설명","1970년대 이후 컴퓨터 보급으로 이동평균, RSI(1978년 J. 웰스 와일더), MACD(제럴드 아펠), 스토캐스틱(조지 레인) 등 계량 지표가 폭발적으로 개발되었다."]]},{"t":"② 1973년 MTA→CMT 협회","n":[["설명","1973년 시장기술분석가협회(MTA)가 설립되었고, 이것이 오늘날의 CMT 협회(CMT Association)이다. CMT 자격은 기술적 분석 분야의 대표적 국제 자격이다."]]},{"t":"③ 증거 기반 분석으로 발전","n":[["설명","최근에는 행동재무학, 통계·시스템 트레이딩, 머신러닝 등이 결합되며 기술적 분석이 '증거 기반 (Evidence-based)' 방향으로 발전하고 있다."],["표","인물 | 핵심 업적 | 키워드\n혼마 무네히사 | 일본 쌀 시장 거래, 캔들 분석의 시조 | Dojima, 심리\n찰스 다우 | 최초의 주가평균, WSJ 사설 | 다우 이론의 창시자\n윌리엄 해밀턴 | 『The Stock Market Barometer』 | \"A Turn in the Tide\"(1929)\n로버트 레아 | 『The Dow Theory』(1932) | 가설·정리로 체계화\n샤바커 | 차트 패턴 연구 집대성 | 강세장·약세장 종료 규칙\n에드워즈 &매기 | 『Technical Analysis of Stock Trends』(1948) | 차트 패턴의 고전\n스티브 니슨 | 캔들차트 서양 소개(1991) | Japanese Candlestick"],["쉬운 예","연대순 암기 고리: 17세기 베가(암스테르담) → 18세기 혼마(오사카) → 1884·1896 다우 → 1922 해밀턴\n→ 1932 레아 → 1948 에드워즈·매기 → 1973 MTA → 1978 RSI(와일더) → 1991 니슨. 앞 글자만 따서 '베·혼·다·해·레·에·M·R·니'로 외운다."],["문제 연습","『The Dow Theory』(1932)의 저자와, 1929년 'A Turn in the Tide' 사설의 필자를 각각 쓰시오.\n\n풀이 저자는 로버트 레아, 사설 필자는 윌리엄 해밀턴이다. 찰스 다우는 이론을 책으로 남기지 않고 WSJ 사설로만 남겼 다는 점이 단골 함정이다."]]}]}]}]},{"t":"Ⅲ 다우 이론의 기본 구조","c":[{"t":"1. 다우의 이상적 시장 모형","c":[{"t":"(1) 4국면 모형","c":[{"t":"① 매집 국면(Accumulation )","n":[["설명","매집 국면(Accumulation): 하락 후 바닥권. 가격이 펀더멘털 대비 매우 저렴해지면서 정보에 밝은 투자자(스마트머니)가 조용히 매수한다. 가격은 바닥(floor)을 형성한다."]]},{"t":"② 상승 국면(Markup)","n":[["설명","상승 국면(Markup/Uptrend): 바닥이 확인되면서 점점 더 많은 참여자가 매수에 동참하고 가격이 상승한다."]]},{"t":"③ 분배 국면(Distribution )","n":[["설명","분배 국면(Distribution): 뉴스와 대중이 열광하는 고점권. 스마트머니는 이익을 실현하며 물량을 뒤늦게 진입한 대중에게 넘긴다. 가격은 천장(ceiling)을 형성한다."]]},{"t":"④ 하락 국면(Markdown)","n":[["설명","하락 국면(Markdown/Downtrend): 신용(마진)으로 매수한 참여자가 반대매매·손절에 몰리며 가격이 하락한다."]]}]},{"t":"(2) 모형의 의미","c":[{"t":"① 종목·시장 공통 순환","n":[["설명","이 순환은 개별 종목, 원자재, 시장 전체에서 공통적으로 관찰된다. 예컨대 2007~2009년 시장 사이클이 대표적이다."]]},{"t":"② 정보 우위자→대중 물량 이동","n":[["설명","가격의 움직임은 결국 '누가 사고 누가 파는가'의 이동, 즉 정보 우위자에서 대중으로의 물량 이동으로 설명된다."]]}]}]},{"t":"2. 레아가 정리한 다우 이론의 3가지 가설","c":[{"t":"(1) 가설의 내용","c":[{"t":"① 가설1: 1차 추세 조작 불가","n":[["설명","가설 1 - 조작(Manipulation): 일간 움직임(minor)과 2차 반응은 조작이 가능하지만, 1차 추세(Primary Trend)는조작될 수 없다. 즉 1차 추세는 침해될 수 없다(inviolate)."]]},{"t":"② 가설2: 평균은 모두 반영","n":[["설명","가설 2 - 평균은 모든 것을 반영한다(The Averages Discount Everything): 평균 지수는 알려진 모든 정보와 예측 가능한 사건까지 반영한다."]]},{"t":"③ 가설3: 이론은 완벽하지 않음","n":[["설명","가설 3 - 다우 이론은 완벽하지 않다(The Theory Is Not Infallible): 다우 이론은 투자를 돕는 도구이지 절대적 체계가 아니며, 연구와 판단이 필요하다."]]}]},{"t":"(2) 가설의 시대적 배경","c":[{"t":"① 19세기 말 시세조종 만연","n":[["설명","다우가 활동하던 19세기 말은 내부자 거래와 시세조종이 흔했고 규제가 약했다. 다우는 이러한 조작이 단기 움직임에만 영향을 줄 뿐, 한발 물러서 보면 1차 추세는 유지된다고 보았다."]]},{"t":"② 평균 사용으로 노이즈 상쇄","n":[["설명","개별 종목 대신 여러 종목의 '평균'을 사용한 것도 한 종목의 특수 요인(노이즈)을 상쇄하고 경제 전체의 흐름을 보기위함이었다."],["쉬운 예","4국면은 농사와 같다. 아무도 관심 없는 겨울에 씨를 뿌리고(매집), 싹이 자라는 것을 보고 이웃들도 따라 심고(상승), 모두가 풍년을 말할 때 수확물을 시장에 내다 팔고(분배), 물량이 넘쳐 값이 떨어진다(하락). 스마트머니는 항상 한 국면 먼저 움직인다."],["실전 사례","2020년 코로나 급락 이후를 4국면으로 해석해 보자. 2020년 3월 비관이 극에 달한 바닥권(매집) → 이후 대중이 다시 참여한 상승 → 2021년 밈 주식·SPAC 열풍이라는 과열(분배) → 2022년 약세장. 교과서의 모형이 실제 시장에서 어떻게 보이는지 확인하는 연습으로 활용한다(해석은 학습용 예시이다)."]]}]}]}]},{"t":"Ⅳ 다우 이론의 6대 기본원칙 (Six Tenets)","c":[{"t":"1. 원칙 1: 시장은 세 가지 움직임을 가진다","c":[{"t":"(1) 세 가지 추세","c":[{"t":"① 1차 추세: 조류(1년 이상)","n":[["설명","1차 추세(Primary Trend): 가장 큰 흐름으로 보통 1년 이상, 수년간 지속된다. 바다의 '조류(Tide)'에 비유된다. 강세장(Bull Market)과 약세장(Bear Market)을 결정한다."]]},{"t":"② 2차 반응: 파도(3주~3개월)","n":[["설명","2차 추세·2차 반응(Secondary Trend/Reaction): 1차 추세에 반대되는 조정 움직임으로 보통 3주~3개월 지속되며, 직전 1차 추세 상승폭의 1/3~2/3를 되돌린다(50% 되돌림이 가장 흔함). '파도(Wave)'에 비유된다."]]},{"t":"③ 소추세: 잔물결(3주 미만)","n":[["설명","소추세(Minor Trend): 3주 미만(보통 수일~수주)의 짧은 움직임으로 '잔물결(Ripple)'에 비유된다. 조작이 가능하고 의미가 가장 작다. 단기(Short-term) 추세라고도 부른다."],["표","추세 | 기간 | 비유 | 되돌림/의미\n1차(Primary) | 1년 이상(수년) | 조류(Tide) | 강세장·약세장 결정, 조작 불가\n2차(Secondary) | 3주~3개월 | 파도(Wave) | 1차 추세의 1/3~2/3 되돌림\n소(Minor) | 3주 미만 | 잔물결(Ripple) | 노이즈, 조작 가능"]]}]},{"t":"(2) 1차 추세의 3단계 (Phases)","c":[{"t":"① 강세장 3단계","n":[["설명","강세장의 3단계: 매집(Accumulation) → 대중 참여(Public Participation) → 과열·분배(Excess/Distribution). 마지막 단계에서는 투기가 만연하고 뉴스가 최고조로 낙관적이다."]]},{"t":"② 약세장 3단계","n":[["설명","약세장의 3단계: 분배(Distribution) → 공황(Panic) → 절망·무관심(Despair/Discouraged Selling). 마지막 단계에서는 우량주도 헐값에 팔리고 아무도 시장에 관심을 갖지 않는다."]]},{"t":"③ 대중의 무관심=강세 초기","n":[["설명","실전 예: 2009년 강세장 초입에는 대부분의 투자자가 2008년 손실로 시장을 외면하였다. 대중의 무관심은 새로운 강세장의 초기 단서가 될 수 있다."],["표","항목 | 강세장의 종료 무렵 | 약세장의 종료 무렵\n거래량 | 급증(도취·과열) | 감소(무관심)\n종목 움직임 | 인기 대형주만 상승, 나머지는 붕괴 | 대부분 종목이 투매 후 안정\n원자재 가격 | 상승 | 하락\n금리 | 높은 수준 | 하락한 수준\n대중의 화제 | 주식이 인기 대화 주제 | 주식 이야기를 기피\n뉴스 | 낙관 일색 | 비관 일색"]]}]},{"t":"(3) 샤바커의 1차 추세 종료 판별 규칙","c":[{"t":"① 강세장 말기 징후","n":[["설명","강세장 말기에는 거래량 급증, 소수 대형 인기주만의 상승(시장폭 축소), 높은 금리, 낙관적 뉴스가 겹친다. 대중이 주식을 가장 많이 이야기할 때가 위험 신호이다."]]},{"t":"② 약세장 말기 징후","n":[["설명","약세장 말기에는 거래량 감소, 원자재 가격 하락, 금리 하락, 비관 일색의 뉴스가 나타난다. 잡지 표지가 \"주식의 종말\"을 말할 때가 오히려 바닥 부근인 경우가 많다."]]}]},{"t":"(4) 2차 반응과 1차 추세 전환의 구별","c":[{"t":"① 규모: 직전 저점 하향 돌파","n":[["설명","규모: 이전 조정들보다 뚜렷하게 크고, 직전 저점을 하향 돌파하면 1차 추세 전환을 의심한다(추세선 이탈)."]]},{"t":"② 속도: 하락 속도 급격화","n":[["설명","속도: 이전 조정보다 하락 속도가 급격해지면(예: 일주일에 5% 하락하던 것이 하루에 5% 하락) 경계 신호이다."]]},{"t":"③ 기간: 3개월 초과 시 전환","n":[["설명","기간: 2차 반응은 대개 3주~3개월이다. 3개월을 넘기면 1차 추세 전환 가능성이 커진다."]]},{"t":"④ 거래량: 조정 시 증가 경계","n":[["설명","거래량: 2차 반응은 보통 거래량이 적다. 조정 시 거래량이 상승 구간의 평균 거래량과 같거나 크고, 이전 조정보다 크다면 추세 전환 가능성이 높다."]]}]}]},{"t":"2. 원칙 2: 평균은 모든 것을 반영한다","c":[{"t":"(1) 두 가지 해석","c":[{"t":"① 개별 가격의 뉴스 반영","n":[["설명","개별 가격 반영: 주식시장은 새로운 뉴스를 신속하게 가격에 반영한다. 예컨대 실적 발표 직후 적정가치가 재평가되며 가격이 즉시 점프한다."]]},{"t":"② 평균 지수의 정보 반영","n":[["설명","평균 지수 반영: 평균(지수)은 경제 심리의 변화를 포함한 모든 정보를 반영한다. 지수의 모습은 '현재 알려진 모든 지식'을 요약한다."]]}]},{"t":"(2) 의미와 사례","c":[{"t":"① EMH와 유사, 반영 과정 차이","n":[["설명","이는 효율적 시장 가설(EMH)과 유사한 측면이 있으나, 기술적 분석가는 '반영되는 과정'이 즉시·완벽하지 않으므로 추세가 생긴다고 본다."]]},{"t":"② 브렉시트 후 FTSE 회복","n":[["설명","2016년 브렉시트 투표 직후 FTSE는 급락했지만 수일 만에 회복하며 기존 추세를 이어갔다. 이는 1차 추세가 뉴스 충격에도 침해되지 않는다는 다우의 관점을 보여준다."]]}]}]},{"t":"3. 원칙 3: 평균은 서로 확인해야 한다","c":[{"t":"(1) 확인(Confirmation) 의 원리","c":[{"t":"① 산업과 철도(운송)의 관계","n":[["설명","다우 시대에는 산업(Industrials)이 상품을 생산하고 철도(Rails, 현재의 운송 Transports)가 이를 운반하였다. 산업이 확장하려면 운송도 확장해야 하므로 두 평균이 같은 방향을 가리켜야 경제 전체의 확장이 확인된다."]]},{"t":"② 두 평균 동시 고점·저점 돌파","n":[["설명","상승 추세는 두 평균이 모두 직전 고점을 돌파(higher peaks)할 때, 하락 추세는 두 평균이 모두 직전 저점을 하향 돌파(lower troughs)할 때 확인된다."]]},{"t":"③ 레아: 다른 평균 확인 필수","n":[["설명","레아(1932): \"한 평균의 움직임만으로 내린 결론은 다른 평균의 확인이 없으면 거의 확실히 오해를 낳는다.\""]]}]},{"t":"(2) 비확인(Non-confirma tion)과 현대적 응용","c":[{"t":"① 비확인=추세 약화 경고","n":[["설명","한 평균만 신고점을 만들고 다른 평균이 따라오지 못하면 '비확인(다이버전스)'으로 추세 약화의 경고로 본다."]]},{"t":"② 시간차 클수록 신뢰도 하락","n":[["설명","확인은 동시에 일어날 필요는 없지만 시간 차이가 클수록 신뢰도가 떨어진다."]]},{"t":"③ S&P500 vs 러셀2000 응용","n":[["설명","오늘날에는 S&P 500과 러셀 2000(대형주 vs 소형주), 산업과 운송 지수 등의 조합으로 응용한다."]]}]}]},{"t":"4. 원칙 4: 추세는 거래량으로 확인된다","c":[{"t":"(1) 원리","c":[{"t":"① 거래량은 추세 방향으로 증가","n":[["설명","거래량은 추세 방향으로 증가해야 한다. 상승 추세에서는 상승 시 거래량 증가·조정 시 거래량 감소, 하락 추세에서는 하락 시 거래량 증가·반등 시 거래량 감소가 정상이다."]]},{"t":"② 강한 거래량=진짜 견해","n":[["설명","강한 거래량을 동반한 가격 움직임이 '진짜 시장의 견해'이며, 적은 거래량의 움직임은 소수 참여자에 의한 것일 수 있다."]]}]},{"t":"(2) 주의점","c":[{"t":"① 거래량은 보조 지표","n":[["설명","다우 이론에서 거래량은 보조적(secondary) 지표이다. 실제 매매 신호는 가격(종가)으로만 결정하고 거래량은 확인용도로 사용한다."]]},{"t":"② 가격↑·거래량↓=에너지 약화","n":[["설명","가격은 상승하는데 거래량이 계속 감소하면 추세의 에너지가 약해지는 경고로 본다."]]}]}]},{"t":"5. 원칙 5: 종가만 사용한다","c":[{"t":"(1) 내용","c":[{"t":"① 장중 고저 무시, 종가만 사용","n":[["설명","다우 이론은 장중 고가·저가를 무시하고 종가(Closing Price)만을 사용한다."]]},{"t":"② 종가=합의된 가격","n":[["설명","이유: 장중 움직임은 조작·일시적 감정·단기 트레이더의 영향을 많이 받지만, 종가는 하루 동안의 공방이 정리된 합의 가격이기 때문이다."]]}]},{"t":"(2) 현대적 의미","c":[{"t":"① U자형 거래량 패턴","n":[["설명","대형 기관은 유동성이 풍부한 장 마감 무렵에 주문을 집중하는 경향이 있어 거래량이 장 초반과 마감에 많고 장 중간에 적은 'U자형' 패턴이 나타난다."]]},{"t":"② 스캘핑: 봉 마감 기준 확인","n":[["설명","스캘핑 적용: 장중 고점을 잠깐 돌파했다가 다시 밀린 '윗꼬리 돌파'는 종가 기준으로는 돌파가 아니다. 종가(또는 봉 마감) 기준 확인은 가짜 돌파를 걸러내는 원리와 같다."]]}]}]},{"t":"6. 원칙 6: 추세는 반전 신호까지 지속된다","c":[{"t":"(1) 내용","c":[{"t":"① 추세는 관성을 가짐","n":[["설명","추세는 시장 잡음(noise)에도 불구하고 관성을 가지고 지속된다. 반대 방향 움직임은 당연히 발생하며 그 자체로 추세 전환을 의미하지 않는다."]]},{"t":"② 기존 추세에 의심의 이익","n":[["설명","추세 전환이 확실하지 않으면 기존 추세에 '의심의 이익(benefit of the doubt)'을 주어야 한다."]]}]},{"t":"(2) 반전 신호의 정의 (고점·저점 구조)","c":[{"t":"① 상승 추세 반전 조건","n":[["설명","상승 추세의 반전: 고점과 저점이 계속 높아지다가(Higher High, Higher Low), 반등이 직전 고점을 넘지 못하고(Lower High) 이후 직전 저점을 하향 이탈할 때 하락 반전이 확인된다."]]},{"t":"② 하락 추세 반전 조건","n":[["설명","하락 추세의 반전: 저점이 더 이상 낮아지지 않고(Higher Low) 이후 직전 반등 고점을 상향 돌파할 때 상승 반전이 확인된다."]]},{"t":"③ 성급한 전환 단정=휩소","n":[["설명","가장 흔한 실수는 추세 전환을 너무 일찍 단정하는 것이다. 확인 없이 대응하면 휩소(whipsaw)를 겪는다."],["시험 포인트","다우 이론 6대 원칙: ① 세 가지 움직임 ② 평균은 모든 것을 반영 ③ 평균 상호 확인 ④ 거래량 확인 ⑤ 종가만 사용 ⑥ 명확한 반전 신호 전까지 추세 지속.\n거래량은 '확인'의 보조 수단이며 신호 자체는 가격(종가)으로 판단한다.\n2차 반응: 3주~3개월, 1/3~2/3 되돌림. 1차 추세: 1년 이상."],["쉬운 예","다우의 '해변 말뚝' 비유: 밀물인지 썰물인지 알려면 모래사장에 말뚝을 박고 파도가 닿는 지점을 표시한다. 파도(2차 추세)가 칠 때마다 더 높이 올라오면 밀물(1차 상승 추세), 점점 덜 올라오면 썰물이다. 잔물결(소추세)은 무시한다."],["문제 연습","1차 상승 추세에서 지수가 100에서 160까지 오른 뒤 2차 반응이 시작되었다. 다우 이론상 정상적인 2차 반응의 되돌림 범위와 가장 흔한 되돌림 수준은?\n\n풀이 상승폭 60의 1/3 = 20, 2/3 = 40이므로 되돌림 범위는 140~120이다. 가장 흔한 50% 되돌림은 160 - 30 = 130이다."]]}]}]}]},{"t":"Ⅴ 다우 이론의 평가와 현대적 활용","c":[{"t":"1. 다우 이론에 대한 비판","c":[{"t":"(1) 주요 비판","c":[{"t":"① 신호 후행성(20~25% 놓침)","n":[["설명","신호의 후행성(Lag): 두 평균의 확인을 기다리므로 추세의 초기 상당 부분(흔히 20~25%)을 놓친다. 대신 성급한 진입으로 인한 반복 손실을 줄이는 효과가 있다."]]},{"t":"② 추세 정의의 모호성","n":[["설명","추세 정의의 모호성: 1차·2차 추세의 크기를 수치로 엄밀히 정의하지 않아 주관적 판단이 개입된다."]]},{"t":"③ 산업구조 변화","n":[["설명","산업구조 변화: 오늘날 경제는 서비스·기술 비중이 높아 '산업-운송' 관계가 다우 시대만큼 긴밀하지 않다."]]},{"t":"④ 매매 시스템보다 바로미터","n":[["설명","다우 이론은 매매 시스템이라기보다 시장의 1차 추세를 판단하는 '바로미터'의 성격이 강하다."]]}]},{"t":"(2) 비판에 대한 반론","c":[{"t":"① 후행성은 추세추종 공통","n":[["설명","후행성은 모든 추세 추종 기법의 공통 특성이며, 대신 높은 신뢰도를 얻는다(위험 감소)."]]},{"t":"② 스윙 차트로 객관적 정의","n":[["설명","스윙 차트(예: 20%·5%·1% 스윙)처럼 현대적 도구를 쓰면 1차·2차·소추세를 객관적으로 정의할 수 있다."]]}]}]},{"t":"2. 현대 트레이딩에서의 다우 이론","c":[{"t":"(1) 추세 추종 원칙의 기초","c":[{"t":"① 추세 방향 매수 규칙","n":[["설명","퀀트 검증에서도 \"확인된 상승 추세 안에서만 매수 신호를 받는다\" 규칙이 성과를 개선하는 경우가 많다. 이는 '추세 방향으로 거래하라'는 다우의 원칙과 같다."]]},{"t":"② 2차 되돌림=매수 기회","n":[["설명","2차 추세(되돌림)는 1차 추세 방향의 매수 기회로 활용된다. 예컨대 상승 추세 속 과매도 오실레이터 신호로 진입하는 평균회귀 전략이다."]]}]},{"t":"(2) 스캘핑 관점의 적용","c":[{"t":"① 다중 시간 단위 적용","n":[["설명","다중 시간 단위(Multiple Time Frame): 일봉=1차, 15분봉=2차, 1분봉=소추세처럼 시간 단위별로 추세를 나누어 볼 수 있다."]]},{"t":"② 시장 구조: BOS·CHOCH","n":[["설명","시장 구조(Market Structure): 흔히 쓰이는 BOS(Break of Structure)·CHOCH(Change of Character) 개념은 결국 다우 이론의 고점·저점 구조(HH/HL, LH/LL) 해석을 단기 차트에 적용한 것이다."]]},{"t":"③ 섹터 ETF로 상호 확인","n":[["설명","확인의 원리: 소형주 급등 시 해당 종목만이 아니라 섹터 ETF나 러셀 2000의 방향을 함께 보는 것은 '평균 상호 확인'원리의 현대적 응용이다."],["쉬운 예","다우 이론의 후행성은 '기차가 역에 들어온 것을 확인하고 타는 것'과 같다. 출발 직후 구간은 놓치지만, 엉뚱한 기차에 오를 위험은 크게 줄어든다."],["실전 사례","스캘퍼의 다중 시간 적용 — 일봉이 고점·저점을 높이는 상승 구조(1차)이고, 15분봉이 50% 근처까지 눌린 뒤(2차), 1분봉에서 직전 스윙 고점을 돌파(소추세의 BOS)할 때 진입한다. 손절은 1분봉 마지막 스윙 저점 아래에 둔다. 세 시간 단위가 같은 방향을 가리킬 때만 거래하는 것이 '평균 상호 확인' 원리의 실전판이다."],["주차 핵심 요약","기술적 분석 = 가격·거래량으로 참여자 행동을 해석하는 학문, 3대 전제(반영·추세·반복).\n다우(창시) → 해밀턴(바로미터) → 레아(1932 체계화). 에드워즈 & 매기(1948 패턴의 고전).\n다우 이론: 3가설(조작 불가·평균 반영·완벽하지 않음) + 6원칙. 비판: 후행성·모호성."]]}]}]}]}],"b":1},{"n":2,"t":"시장 효율성, 행동재무학, 투자자 심리","c":[{"t":"Ⅰ 효율적 시장 가설 (EMH)","c":[{"t":"1. EMH의 기본 개념","c":[{"t":"(1) 정의와 전제","c":[{"t":"① 주가는 모든 정보 반영(파마)","n":[["설명","EMH는 \"주가는 이용 가능한 모든 정보를 완전하고 신속하게 반영한다\"는 가설이다. 유진 파마(Eugene Fama)가 1970년 체계화하였다."],["이번 주 학습목표","① 효율적 시장 가설(EMH)의 세 가지 형태와 기술적 분석에 대한 함의를 설명할 수 있다.\n② 랜덤워크·마팅게일, 일물일가 법칙, 잡음 거래자의 개념을 이해한다.\n③ 전망이론과 주요 인지·감정 편향을 구별할 수 있다.\n④ 적응적 시장 가설(AMH)과 역발상(Contrary Opinion), 심리지표의 해석법을 익힌다."]]},{"t":"② 현재 가격=최선의 가치 추정","n":[["설명","가격은 새로운 정보가 나올 때에만 변하며, 현재 가격은 기업 가치(미래 배당 흐름의 현재가치)에 대한 최선의 추정치이다."]]},{"t":"③ 위험조정 초과수익은 0","n":[["설명","위험을 조정한 초과수익(Risk-adjusted excess return)은 장기적으로 0에 수렴한다. 즉 이익을 낼 수는 있으나 '시장을 이길 수는' 없다는 주장이다."]]},{"t":"④ 핵심 가정: 합리적 투자자","n":[["설명","핵심 가정: 모든 투자자가 정보를 합리적으로(Rational) 처리한다는 것이다. 행동재무학은 바로 이 가정을 공격한다."]]}]},{"t":"(2) 다우 이론과의 관계","c":[{"t":"① 다우 원칙과 뿌리 같음","n":[["설명","\"평균은 모든 것을 반영한다\"는 다우의 원칙과 뿌리가 같지만, EMH는 이를 극단까지 밀어붙여 '예측 불가능성'의 결론에 도달한다."]]},{"t":"② 반영 과정 지연→추세 형성","n":[["설명","기술적 분석가는 정보가 가격에 반영되는 '과정'이 즉각적이지 않고 과잉반응·과소반응을 동반하므로 추세가 형성된다고 본다."]]}]}]},{"t":"2. EMH의 세 가지 형태","c":[{"t":"(1) 약형 효율성 (Weak-Form)","c":[{"t":"① 과거 가격·거래량 반영","n":[["설명","현재 가격은 과거의 모든 가격·거래량 정보를 반영한다. 따라서 과거 가격을 분석해도 미래 가격을 예측할 수 없다."]]},{"t":"② 기술적 분석 직접 공격","n":[["설명","기술적 분석을 직접 공격하는 형태이다. 약형이 성립하면 기술적 분석으로 초과수익을 얻을 수 없다."]]},{"t":"③ 검증 용이, 모멘텀 반론","n":[["설명","검증이 비교적 쉽다(과거 가격 기반 규칙의 성과 검증). 시장 이상현상(모멘텀 등)이 반론 근거로 제시된다."]]}]},{"t":"(2) 준강형 효율성 (Semi-Strong Form)","c":[{"t":"① 모든 공개 정보 반영","n":[["설명","현재 가격은 모든 '공개된' 정보(과거 가격 + 재무제표·뉴스·공시 등)를 반영한다. 따라서 기술적 분석뿐 아니라 기본적 분석으로도 초과수익을 얻을 수 없다."]]},{"t":"② 싼 주식도 비싼 주식도 없음","n":[["설명","\"싼 주식도 비싼 주식도 없다\"는 함의를 갖는다. 가장 널리 받아들여지고 가장 많은 관심을 받는 형태이다."]]},{"t":"③ 뉴스 후 과잉반응 설명 곤란","n":[["설명","뉴스 발표 직후 가격이 과잉반응하고 되돌리는 현상(오버슈팅 후 균형 탐색)은 준강형으로 설명하기 어렵다."]]}]},{"t":"(3) 강형 효율성 (Strong Form)","c":[{"t":"① 비공개 정보까지 반영","n":[["설명","현재 가격은 공개 정보뿐 아니라 비공개 정보(내부자 정보)까지 모두 반영한다."]]},{"t":"② 내부자 거래로 반증","n":[["설명","내부자 거래로 초과수익이 가능하다는 증거가 많아 일반적으로 성립하지 않는다고 본다."],["표","형태 | 반영하는 정보 | 무력화되는 분석 | 일반적 평가\n약형(Weak) | 과거 가격·거래량 | 기술적 분석 | 성립 가능성이 높다고 주장되나 이상현상 존재\n준강형(Semi-strong) | 모든 공개 정보 | 기술적 + 기본적 분석 | 가장 많은 관심·논쟁\n강형(Strong) | 공개 + 비공개 정보 | 내부정보 포함 모든 분석 | 거의 성립하지 않음"],["시험 포인트","포함 관계: 강형 ⊃ 준강형 ⊃ 약형. 강형이 성립하면 준강형·약형도 성립한다.\n기술적 분석을 부정하는 최소 조건은 '약형' 효율성이다."]]}]}]},{"t":"3. 랜덤워크와 마팅게일","c":[{"t":"(1) 랜덤워크 (Random Walk)","c":[{"t":"① 가격 변화는 서로 독립","n":[["설명","다음 가격 변화는 이전 가격 변화와 독립적이며, 동전 던지기처럼 고정된 확률을 갖는다는 모형이다."]]},{"t":"② 추세+무작위 잡음 모형","n":[["설명","주가 = 일정한 성장 요인(추세) + 그 주변의 무작위 잡음으로 표현하기도 한다. 성장 요인을 제거하면 예측 가능성이 완전히 사라진다는 주장이다."]]},{"t":"③ 동전 던지기의 독립성","n":[["설명","동전을 연속으로 던질 때 앞면이 4번 연속 나올 확률은 0.5^4=6.25%이지만, 이미 4번 나온 뒤 5번째가 앞면일 확률은 여전히 50%이다(독립성)."]]}]},{"t":"(2) 마팅게일 (Martingale )","c":[{"t":"① 마팅게일=공정한 게임","n":[["설명","확률론에서 마팅게일은 \"현재까지의 모든 정보가 주어졌을 때 미래 값의 기대값이 현재 값과 같은\" 과정이다. 즉 '공정한 게임(Fair Game)'이다."]]},{"t":"② EMH의 수학적 표현","n":[["설명","EMH의 수학적 표현으로 쓰이며, 과거 정보로 기대수익을 개선할 수 없다는 의미이다."]]},{"t":"③ 도박 마팅게일 베팅과 구분","n":[["설명","도박에서 말하는 마팅게일 베팅(잃을 때마다 베팅액을 두 배로 늘리는 전략)과 개념을 구분해야 한다. 후자는 파산위험이 매우 큰 자금관리 방식이다."]]}]}]},{"t":"4. EMH에 대한 반론","c":[{"t":"(1) 세 가지 공격 경로","c":[{"t":"① 논리적 반론: 차익거래 한계","n":[["설명","논리적(이론적) 반론: 차익거래가 항상 가능하지 않다(차익거래의 한계, 비용·위험 존재)."]]},{"t":"② 심리학적 반론: 행동재무학","n":[["설명","심리학적 반론: 인간의 의사결정 실험은 합리성 가정을 반박한다(행동재무학)."]]},{"t":"③ 실증적 반론: 이상현상","n":[["설명","실증적 반론: 금융 데이터에서 예측 가능성(모멘텀, 평균회귀, 계절성 등 이상현상, Anomalies)이 발견된다."]]}]},{"t":"(2) 대표적 사례","c":[{"t":"① 1987 블랙먼데이 22% 폭락","n":[["설명","1987년 10월 블랙먼데이: 뚜렷한 펀더멘털 뉴스 없이 다우 지수가 하루에 22% 이상 폭락하였다. 정보 없이 가격이 급변한 것은 EMH로 설명하기 어렵다."]]},{"t":"② 2010 플래시 크래시","n":[["설명","2010년 플래시 크래시(Flash Crash): 수분 만에 급락 후 회복하였다."]]},{"t":"③ 쉴러의 과잉 변동성","n":[["설명","과도한 변동성: 로버트 쉴러(Robert Shiller)는 주가 변동성이 배당 변동으로 정당화되는 수준보다 훨씬 크다는 '과잉 변동성(Excess Volatility)'을 제시하였다."],["쉬운 예","경제학 농담: 교수와 학생이 길을 걷다 100달러 지폐를 발견한다. 학생이 주우려 하자 교수가 말한다. \"진짜라면 누가 벌써 주웠겠지.\" — 이것이 EMH의 사고방식이다. 기술적 분석가는 \"누군가 줍기까지 시간이 걸린다\"고 반박한다."],["문제 연습","공정한 동전을 던졌더니 앞면이 4번 연속 나왔다. (가) 5번째도 앞면일 확률, (나) 처음 던지기 전에 '5번 연속 앞면'이 나올 확률은?\n\n풀이 (가) 독립 사건이므로 50%. (나) 0.5^5 = 3.125%. 두 값을 혼동하는 것이 도박사의 오류이다."]]}]}]}]},{"t":"Ⅱ 행동재무학의 선구적 개념","c":[{"t":"1. 모멘텀 전략과 평균회귀 전략","c":[{"t":"(1) 모멘텀 (Momentum)","c":[{"t":"① 단기(3~12개월) 추세 지속","n":[["설명","단기적(대략 3~12개월)으로 오른 종목은 계속 오르고 내린 종목은 계속 내리는 경향이다."]]},{"t":"② 원인: 과소반응·군집행동","n":[["설명","원인: 정보에 대한 과소반응(Underreaction), 군집행동, 추세 추종 매매 등이 제시된다."]]},{"t":"③ 강한 것은 더 오래 강함","n":[["설명","스캘핑 적용: \"강한 것은 예상보다 더 오래 강할 수 있다.\" 과매수 신호만으로 강한 종목을 역매도하는 것은 위험하다."]]}]},{"t":"(2) 평균회귀 (Mean Reversion)","c":[{"t":"① 장기(3~5년) 과잉반응 교정","n":[["설명","장기적(3~5년)으로 크게 오른 종목은 부진하고 크게 내린 종목은 회복하는 경향이다(드봉과 탈러의 과잉반응 연구)."]]},{"t":"② 원인: 장기 과잉반응 교정","n":[["설명","원인: 장기간에 걸친 과잉반응(Overreaction)이 결국 교정되기 때문이다."]]},{"t":"③ 단기 모멘텀, 장기 평균회귀","n":[["설명","시험 요점: \"단기에는 모멘텀, 장기에는 평균회귀\"로 정리한다."]]}]}]},{"t":"2. 가치투자와 평균회귀","c":[{"t":"(1) 가치투자 (Value Investing)","c":[{"t":"① 그레이엄·도드 『증권분석』","n":[["설명","벤저민 그레이엄과 데이비드 도드(Graham & Dodd)가 1934년 『증권분석(Security Analysis)』에서 체계화하였다."]]},{"t":"② 저평가 매수, EMH와 대립","n":[["설명","재무제표 분석으로 추정한 가치보다 가격이 크게 낮은 종목을 매수한다. 이는 시장을 이길 수 있다는 전제를 가지므로 EMH와 대립한다."]]}]},{"t":"(2) 가치투자가 평균회귀와 닮은 이유","c":[{"t":"① 과도 하락 종목의 가치 회귀","n":[["설명","감정적 투자자가 펀더멘털을 무시하여 과도하게 하락한 종목이 결국 가치로 되돌아갈 것을 기대하기 때문이다."]]},{"t":"② 군중 극단과 반대로 매매","n":[["설명","매수·매도 시점이 군중의 극단과 반대이다. 즉 비합리적 비관의 극단에서 사고, 비합리적 낙관의 극단에서 판다."]]},{"t":"③ RSI 과매도 매수와 동일","n":[["설명","RSI 과매도 구간 매수와 같은 기술적 평균회귀 전략과 사고방식이 같다."]]}]}]},{"t":"3. 일물일가 법칙과 잡음 거래자","c":[{"t":"(1) 일물일가 법칙 (Law of One Price)","c":[{"t":"① 동일 자산은 동일 가격","n":[["설명","동일한 두 자산은 동일한 가격에 거래되어야 한다. 가격이 달라지면 차익거래자가 싼 것을 사고 비싼 것을 팔아 가격을 일치시킨다."]]},{"t":"② 대체가능성 있을 때만 강제","n":[["설명","이 법칙은 대체가능성(Fungibility), 즉 두 자산을 비용 없이 서로 교환할 수 있을 때에만 강제된다."]]},{"t":"③ 로열더치셸 가격비 괴리","n":[["설명","로열더치셸 사례: 동일 기업이 네덜란드(Royal Dutch 60%)와 영국(Shell 40%)에 상장되어 이론상 가격비가 1.5배여야 했으나 실제로는 크게 이탈하였다. 두 주식 간 비용 없는 전환이 불가능했기 때문이다."]]}]},{"t":"(2) 잡음 거래자 (Noise Traders)","c":[{"t":"① 잡음에 근거한 비합리 거래","n":[["설명","밀턴 프리드먼에서 유래한 용어로, 정보가 아닌 '잡음'에 근거해 거래하는 비합리적 참여자를 말한다. 투기자 등이 포함된다."]]},{"t":"② 체계적 군집일 때 EMH 위협","n":[["설명","잡음 거래자의 존재만으로 EMH가 무너지지는 않는다. EMH에 문제가 되려면 잡음 거래자의 행동이 체계적(군집적, Herding)이어야 하고, 이들이 경제적으로 생존해야 한다."]]},{"t":"③ 기술적 분석가=잡음 거래자","n":[["설명","기술적 분석가는 EMH 관점에서 잡음 거래자의 한 형태로 분류된다. 정보보다 가격 패턴에 반응하고, 추세 추종처럼집단적으로 행동하여 과잉낙관·과잉비관을 증폭시킬 수 있기 때문이다."],["쉬운 예","모멘텀은 '달리는 자전거'다. 한번 속도가 붙으면 쉽게 멈추지 않는다(3~12개월). 평균회귀는 '늘어난 고무줄'이다. 너무 멀리 늘어나면 결국 제자리로 돌아온다(3~5년). 단기는 자전거, 장기는 고무줄로 기억한다."],["실전 사례","잡음 거래자의 실례 — 2020년 3월, 화상회의 기업 줌(티커 ZM)의 인기를 노린 투자자들이 이름이 비슷한 다른 소형 회사(티커 ZOOM) 주식을 대거 매수해 가격이 급등했고, 미국 SEC가 해당 종목의 거래를 일시 정지시켰다.\n정보가 아닌 '잡음'에 근거한 군집 매매가 가격을 가치에서 크게 이탈시킬 수 있음을 보여 준다."]]}]}]}]},{"t":"Ⅲ 행동재무학 (Behavioral Finance)","c":[{"t":"1. 전망이론 (Prospect Theory)","c":[{"t":"(1) 개념","c":[{"t":"① 기준점 대비 손익 평가","n":[["설명","카너먼과 트버스키(Kahneman & Tversky, 1979)가 제시한 이론으로, 사람들은 최종 부(Wealth)가 아니라 기준점(Reference Point) 대비 이익·손실로 결과를 평가한다."]]},{"t":"② 이익 오목·손실 볼록 가치함수","n":[["설명","가치함수는 이익 영역에서 오목(위험회피), 손실 영역에서 볼록(위험추구)하며, 손실 영역의 기울기가 더 가파르다."]]},{"t":"③ 낮은 확률 과대평가","n":[["설명","확률 가중: 사람들은 낮은 확률을 과대평가하고 중간~높은 확률을 과소평가하는 경향이 있다(복권 구매, 보험 가입 설명)."]]}]},{"t":"(2) 손실회피 (Loss Aversion)","c":[{"t":"① 손실이 이익의 2~2.5배 고통","n":[["설명","같은 크기의 손실이 이익보다 약 2~2.5배 더 크게 느껴진다."]]},{"t":"② 손절 못하고 이익 조기 확정","n":[["설명","결과: 손실 난 포지션을 손절하지 못하고 버티며(손실 영역 위험추구), 이익 난 포지션은 너무 빨리 확정한다(이익 영역 위험회피)."]]}]},{"t":"(3) 처분효과 (Dispositio n Effect)","c":[{"t":"① 이긴 종목 일찍, 진 종목 오래","n":[["설명","셰프린과 스탯먼(Shefrin & Statman)이 명명한 현상으로 \"이긴 종목은 너무 일찍 팔고, 진 종목은 너무 오래 보유\"하는 경향이다."]]},{"t":"② 손실은 짧게, 이익은 길게","n":[["설명","트레이딩 격언 \"손실은 짧게, 이익은 길게(Cut your losses, let your profits run)\"는 처분효과를 교정하는 원칙이다."]]}]}]},{"t":"2. 휴리스틱과 인지 편향 (Cognitive Biases)","c":[{"t":"(1) 판단의 지름길에서 생기는 편향","c":[{"t":"① 기준점 편향(Anchoring)","n":[["설명","기준점 편향(Anchoring): 처음 접한 숫자(매수가, 과거 고점)에 판단이 고정된다. 예: \"예전 $10이었으니 $4면 싸다.\""]]},{"t":"② 가용성 편향(Availabilit y)","n":[["설명","가용성 편향(Availability): 쉽게 떠오르는 최근·극적인 사례로 확률을 과대평가한다."]]},{"t":"③ 대표성 편향","n":[["설명","대표성 편향(Representativeness): 소수의 표본이나 겉모습의 유사성으로 판단한다. 소수의 법칙(Law of Small Numbers)과 연결된다."]]},{"t":"④ 최근성 편향(Recency)","n":[["설명","최근성 편향(Recency): 가장 최근 결과에 과도한 가중치를 둔다. 연승 후 과도한 확신, 연패 후 좋은 셋업 회피가 대표적이다."]]}]},{"t":"(2) 자기 인식 관련 편향","c":[{"t":"① 과잉확신(Overconfidenc e)","n":[["설명","과잉확신(Overconfidence): 자신의 지식·예측 능력을 과대평가하여 과도한 거래와 과대 포지션을 만든다."]]},{"t":"② 확증편향","n":[["설명","확증편향(Confirmation Bias): 자신의 포지션을 지지하는 정보만 찾고 반대 정보는 무시한다. 예: 매수 후 강세 의견만 검색한다."]]},{"t":"③ 통제의 환상","n":[["설명","통제의 환상(Illusion of Control): 결과를 통제할 수 있다고 착각한다."]]},{"t":"④ 사후확신 편향","n":[["설명","사후확신 편향(Hindsight Bias): 사건 이후 \"그럴 줄 알았다\"고 믿어 학습을 방해한다."]]}]},{"t":"(3) 프레이밍과 심적 회계","c":[{"t":"① 프레이밍(Framing)","n":[["설명","프레이밍(Framing): 같은 정보라도 표현 방식(이익 틀/손실 틀)에 따라 선택이 달라진다."]]},{"t":"② 심적 회계(탈러)","n":[["설명","심적 회계(Mental Accounting, 탈러): 돈을 출처·용도별 계좌로 나누어 다르게 취급한다. 예: '공돈(house money)'으로 더 위험하게 거래한다."]]}]}]},{"t":"3. 감정·사회적 편향","c":[{"t":"(1) 감정적 편향","c":[{"t":"① 후회회피","n":[["설명","후회회피(Regret Aversion): 후회할 결정을 피하려고 행동을 미루거나 군중을 따른다."]]},{"t":"② 현상유지·보유효과","n":[["설명","현상유지 편향(Status Quo) 및 보유효과(Endowment Effect): 이미 가진 것을 더 가치 있게 여긴다."]]},{"t":"③ FOMO 추격 매수","n":[["설명","FOMO(Fear Of Missing Out): 급등을 놓칠까 두려워 추격 매수한다. 급등 → 소외감 → 추격매수 → 고점 매수의 구조를 가진다."]]}]},{"t":"(2) 군집행동 (Herding)과 정보폭포","c":[{"t":"① 군집행동이 버블 증폭","n":[["설명","군집행동: 자신의 정보보다 다른 사람의 행동을 따라 거래한다. 버블과 폭락을 증폭시킨다."]]},{"t":"② 정보폭포","n":[["설명","정보폭포(Information Cascade): 앞선 사람의 선택을 보고 자신의 정보를 무시하며 연쇄적으로 같은 선택을 한다."]]},{"t":"③ 자기강화 피드백 루프","n":[["설명","피드백 루프: 가격 상승 → 관심 증가 → 추가 매수 → 가격 상승의 자기강화 과정이 버블을 만든다(쉴러의 『비이성적과열』)."],["표","편향 | 핵심 설명 | 트레이딩 증상\n손실회피 | 손실의 고통이 이익의 기쁨보다 큼 | 손절 지연\n처분효과 | 이익은 빨리, 손실은 오래 | 평균 이익 < 평균 손실\n기준점 | 최초 숫자에 고정 | 매수가 회복만 기다림\n확증편향 | 원하는 정보만 선택 | 반대 신호 무시\n과잉확신 | 능력 과대평가 | 과다 거래, 과대 포지션\n최근성 | 최근 결과 과대 가중 | 연승 후 사이즈 확대\n군집행동 | 남을 따라 행동 | 추격 매수·투매"],["쉬운 예","길에서 10만 원을 주웠을 때의 기쁨보다 10만 원을 잃어버렸을 때의 속상함이 훨씬 크다. 손실회피는 이 감정이 약 2~2.5배 차이 난다는 것이다. 그래서 손절은 미루고(아픔을 확정하기 싫어서) 익절은 서두른다(기쁨을 빨리 확정하고싶어서)."],["문제 연습","어느 트레이더의 기록: 승률 60%, 평균 이익 $120, 평균 손실 $250. 거래당 기대값과 이 기록에서 의심되는 편향은?\n\n풀이 0.6 × 120 - 0.4 × 250 = 72 - 100 = -$28. 이기는 횟수는 많지만 이익은 작게, 손실은 크게 가져가는 처분효과 (손실회피)의 전형이다."]]}]}]}]},{"t":"Ⅳ 적응적 시장 가설과 기술적 분석의 정당성","c":[{"t":"1. 적응적 시장 가설 (AMH)","c":[{"t":"(1) 개념","c":[{"t":"① 앤드루 로, 진화적 관점","n":[["설명","앤드루 로(Andrew Lo)가 제시한 가설로, 시장을 생물학적 진화(다윈주의)의 관점에서 본다. 시장 참여자는 환경 변화에 적응하며 경쟁한다."]]},{"t":"② 국면별로 효율성 변화","n":[["설명","시장은 항상 효율적이거나 항상 비효율적인 것이 아니라, 시기(국면, Regime)에 따라 효율성이 달라진다."]]},{"t":"③ EMH·행동재무학 공존 틀","n":[["설명","EMH와 행동재무학의 편향이 공존할 수 있는 틀을 제공한다. 전략의 수익성은 환경에 따라 생겨나고 사라진다."],["표","구분 | EMH | AMH\n참여자 가정 | 합리적, 즉각 반응 | 제한적 합리성, 시행착오로 적응\n효율성 | 항상 효율적 | 시기·환경에 따라 변함\n초과수익 | 체계적으로 불가능 | 일시적으로 가능, 경쟁으로 소멸·재출현\n이론적 기반 | 경제학(균형) | 생물학(진화)"]]}]},{"t":"(2) EMH와 AMH의 비교","c":[{"t":"① 전략 수익은 생겼다 사라짐","n":[["설명","AMH에서는 어떤 전략의 초과수익이 경쟁자의 모방으로 사라졌다가 환경이 바뀌면 다시 나타날 수 있다. 따라서 전략의 지속적 재검증이 필요하다."]]},{"t":"② 시험: 시기별 효율성=AMH","n":[["설명","시험에서는 \"시장 효율성이 시기에 따라 변한다\", \"진화·생물학적 관점\"이라는 표현이 나오면 AMH를 고른다."]]}]}]},{"t":"2. 기술적 분석이 여전히 유효한 이유","c":[{"t":"(1) 학술적 근거","c":[{"t":"① 정보 처리 속도 차이","n":[["설명","비대칭 정보와 반응 속도의 차이: 참여자마다 정보를 받아들이고 처리하는 속도가 다르므로 가격 반영에 시간이 걸리고 추세가 형성된다."]]},{"t":"② 잡음·유동성 거래(피셔 블랙)","n":[["설명","잡음과 유동성 거래: 정보와 무관한 거래(유동성 필요 등)가 가격을 가치에서 이탈시킨다(피셔 블랙)."]]},{"t":"③ 로 외(2000) 차트 패턴 유효","n":[["설명","로·마마이스키·왕(Lo, Mamaysky & Wang, 2000)은 차트 패턴에 통계적 정보가 있음을 보였다. 단순 이동평균 전략이 매수 후 보유보다 나은 경우도 보고되었다."]]}]},{"t":"(2) 균형 잡힌 관점","c":[{"t":"① EMH 전면 부정도 극단","n":[["설명","EMH가 대형 펀드의 장기 가치평가 영역에서는 상당히 타당할 수 있다. EMH를 전면 부정하는 것도, 절대시하는 것도 모두 극단이다."]]},{"t":"② 시간 단위별 효율성 차이","n":[["설명","시간 단위와 투자 목적(Horizon)에 따라 효율성의 정도가 달라진다는 관점이 시험과 실무 모두에 유용하다."],["쉬운 예","AMH는 생태계다. 먹이(초과수익)가 많은 곳에 포식자(경쟁 트레이더)가 몰리면 먹이가 줄어들고, 포식자는 다른 사냥터로 옮긴다. 시간이 지나 환경이 바뀌면 옛 사냥터에 다시 먹이가 생긴다."],["실전 사례","스캘퍼의 실전 노트 — 소형주 거래가 폭발적으로 늘었던 시기에 잘 작동하던 돌파 전략이, 거래가 식은 시기에는 휩소만 반복하는 일이 흔하다. 전략이 '고장'난 것이 아니라 시장 국면(Regime)이 바뀐 것일 수 있다. 그래서 국면별로 성과를 나눠 기록하고 주기적으로 재검증한다."]]}]}]}]},{"t":"Ⅴ 시장 심리와 심리지표 (Sentiment)","c":[{"t":"1. 역발상 이론 (Contrary Opinion)","c":[{"t":"(1) 기본 원리","c":[{"t":"① 모두 같은 생각이면 틀림(닐)","n":[["설명","험프리 닐(Humphrey Neill)이 체계화한 이론으로 \"모두가 같은 생각을 할 때 대개 모두가 틀린다\"는 원리이다."]]},{"t":"② 매수·매도 여력 소진 논리","n":[["설명","논리: 모두가 강세라면 이미 매수를 마쳤으므로 추가 매수 여력이 없다. 반대로 모두가 약세라면 이미 매도를 마쳐 매도 압력이 소진된 상태이다."]]},{"t":"③ 극단값에서만 역발상 신호","n":[["설명","군중은 추세의 중간 구간에서는 대체로 옳고, 극단(전환점)에서 틀린다. 따라서 심리지표는 '극단값'에서만 역발상 신호로 사용한다."]]}]},{"t":"(2) 해석상의 주의","c":[{"t":"① 단독 신호 아닌 경고 신호","n":[["설명","심리지표는 단독 매매신호가 아니라 경고 신호이다. 극단적 낙관은 상당 기간 지속될 수 있다."]]},{"t":"② 가격 확인과 병행 사용","n":[["설명","\"극단적 강세 심리 + 기술적 약화(다이버전스, 지지선 이탈)\"처럼 가격 확인과 함께 사용해야 신뢰도가 높다."]]}]}]},{"t":"2. 주요 심리지표","c":[{"t":"(1) 설문조사 지표","c":[{"t":"① AAII 투자자 심리조사","n":[["설명","AAII 투자자 심리조사: 개인투자자의 강세·약세·중립 비율을 매주 조사한다. 극단적 강세는 역발상 매도 경고이다."]]},{"t":"② Investors Intelligence 조사","n":[["설명","Investors Intelligence 조사: 투자자문지(뉴스레터) 작성자의 강세·약세 비율을 조사한다."]]},{"t":"③ 설문 지표의 한계","n":[["설명","설문 지표의 한계: 말(의견)과 실제 자금 행동이 다를 수 있다."]]}]},{"t":"(2) 시장 데이터 기반 지표","c":[{"t":"① 풋/콜 비율","n":[["설명","풋/콜 비율(Put/Call Ratio): 풋옵션 거래량 ÷ 콜옵션 거래량. 높으면 비관(역발상 강세), 낮으면 낙관(역발상 약세) 으로 해석한다."]]},{"t":"② VIX 공포지수","n":[["설명","VIX(변동성 지수): S&P 500 옵션의 내재변동성으로 '공포지수'라 불린다. VIX 급등은 공포의 극단으로 바닥 부근에서 자주 나타나며, VIX가 매우 낮으면 안일함(Complacency)을 의미한다."]]},{"t":"③ 공매도 잔고·Days to Cover","n":[["설명","공매도 잔고(Short Interest)와 공매도 비율(Days to Cover): 공매도가 많으면 비관이 크지만, 동시에 미래의 환매 수(숏커버링) 수요이므로 역발상 강세 요인이 될 수 있다."]]},{"t":"④ 신용잔고와 펀드 현금비중","n":[["설명","신용잔고(Margin Debt)와 펀드 현금비중: 신용잔고 급증은 과열, 뮤추얼펀드 현금비중이 높으면 잠재 매수여력(강세 요인)으로 본다."]]}]},{"t":"(3) 스캘핑 관점의 심리","c":[{"t":"① HALT 재개 시 심리 충돌","n":[["설명","거래정지(HALT) 후 재개 시에는 보유자·미보유자·공매도자의 심리가 충돌한다. 재개가격, 초기 거래량, 첫 눌림, VWAP, 직전 고점을 통해 어느 쪽이 우위인지 확인한다."]]},{"t":"② 행동 트레이딩 저널","n":[["설명","행동 트레이딩 저널: FOMO 진입 비율, 손절 준수율(Stop Compliance Rate), 규칙 위반 손실(Rule Violation Loss)을 기록하면 편향이 수익에 미치는 영향을 계량화할 수 있다."],["쉬운 예","널리 알려진 일화로, 1929년 대폭락 직전 조지프 케네디가 구두닦이 소년에게서 주식 정보를 듣고 \"구두닦이까지 주식 이야기를 하면 끝물\"이라 판단해 주식을 정리했다고 한다. '모두가 같은 생각을 할 때'라는 역발상의 핵심을 보여준다."],["문제 연습","어느 날 풋옵션 거래량 1,200,000계약, 콜옵션 거래량 800,000계약이었다. 풋/콜 비율과 역발상 해석은?\n\n풀이 1,200,000 ÷ 800,000 = 1.5. 평소보다 매우 높다면 비관이 극단이라는 뜻이므로 역발상 강세 경고로 본다. 단, 가격의 반전 확인과 함께 써야 한다."],["주차 핵심 요약","EMH 3형태: 약형(과거가격) - 준강형(공개정보) - 강형(비공개 포함). 기술적 분석 부정 = 약형.\n단기 모멘텀 vs 장기 평균회귀. 일물일가 법칙은 대체가능성이 있을 때만 강제된다.\n전망이론: 기준점·손실회피(손실이 약 2배 아픔)·처분효과. AMH(앤드루 로): 효율성은 환경에 따라 변한다.\n역발상: 군중은 추세 중간에는 옳고 극단에서 틀린다. 심리지표는 극단값에서만 의미가 있다."]]}]}]}]}],"b":2},{"n":3,"t":"차트와 시장 데이터, 캔들차트, 포인트앤피겨","c":[{"t":"Ⅰ 차트의 기본 원리","c":[{"t":"1. 차트가 하는 일","c":[{"t":"(1) 가격의 형성과 요약","c":[{"t":"① 가격=매수·매도자 합의점","n":[["설명","가격은 매수자와 매도자가 '공정가격'에 합의한 지점이다. 매수자와 매도자는 각자 투자기간·목적이 다르므로 어느 한쪽이 옳고 다른 쪽이 틀린 것이 아니다."],["이번 주 학습목표","① 차트가 가격 움직임을 요약하는 원리(표본추출, 데이터 간격, 프랙탈)를 설명할 수 있다.\n② 선·바·캔들·포인트앤피겨·이퀴볼륨 차트의 작성법과 차이를 구별할 수 있다.\n③ 산술 척도와 로그 척도의 차이, 가격 데이터 조정(분할·배당·연결선물)을 이해한다.\n④ 주요 캔들 패턴과 포인트앤피겨의 신호·목표가 계산법을 익힌다."]]},{"t":"② 차트는 체결을 요약","n":[["설명","하루에도 수천~수백만 건의 체결이 일어나므로, 차트는 이를 요약(Summarize)하여 추세를 한눈에 보게 해 준다."]]},{"t":"③ 수요·공급 우위로 가격 변동","n":[["설명","수요가 공급보다 강하면(매수자가 매도호가를 적극적으로 체결) 가격이 오르고, 공급이 강하면 가격이 내린다."]]}]},{"t":"(2) 차트의 장점","c":[{"t":"① 잡음 감소, 주요 추세 노출","n":[["설명","잡음(Noise)을 줄이고 주요 추세를 드러낸다. 단, 틱 차트처럼 짧은 시간 단위일수록 잡음이 많아진다."]]},{"t":"② 전체 그림 제공","n":[["설명","개별 체결에서는 보이지 않는 전체 그림을 제공한다."]]},{"t":"③ 의사소통 도구","n":[["설명","의사소통 도구: 애널리스트가 포트폴리오 매니저에게 추세와 지표를 설명하는 데 효과적이다."]]}]}]},{"t":"2. 가격 데이터의 구성","c":[{"t":"(1) 네 가지 기본 가격 (OHLC)","c":[{"t":"① 시가(Open)","n":[["설명","시가(Open): 해당 기간의 첫 체결 가격이다. 일부 지수 데이터에는 시가가 없어 전일 종가로 대체하기도 한다."]]},{"t":"② 고가·저가(High·Low)","n":[["설명","고가(High)와 저가(Low): 해당 기간의 최고·최저 체결가격이다. 고가와 저가가 발생한 순서는 바 차트만으로 알 수 없다."]]},{"t":"③ 종가(Close)","n":[["설명","종가(Close): 해당 기간의 마지막 체결가격이다. 종가가 '더 중요한' 가격이라기보다 기간을 대표하는 관행적 가격이며, 신문에 보도되던 가격이다."]]},{"t":"④ 범위(Range)=고가-저가","n":[["설명","범위(Range): 고가 - 저가. 일간 범위, 주간 범위 등 기간의 변동 폭을 나타낸다."]]}]},{"t":"(2) 데이터 간격과 프랙탈","c":[{"t":"① 데이터 간격(Interval)","n":[["설명","데이터 간격(Data Interval): 1분, 5분, 일간, 주간, 월간 등 차트의 한 봉이 나타내는 기간이다. 모든 체결에서 일정 간격으로 '표본(Sample)'을 뽑는 것과 같다."]]},{"t":"② 프랙탈 성질","n":[["설명","프랙탈(Fractal) 성질: 월간 차트의 분석 원리를 주간·일간·분 차트에도 똑같이 적용할 수 있다. 5분 차트의 1차 추세는 몇 시간에 불과할 수 있다."]]},{"t":"③ 시간 단위 선택과 다중 분석","n":[["설명","시간 단위 선택은 투자기간(Horizon)과 위험 허용도에 따라 결정한다. 상위 시간 단위로 방향을 보고, 하위 시간 단위로 타이밍을 잡는 다중 시간 분석이 권장된다."]]}]}]},{"t":"3. 시장 데이터의 조정과 주의점","c":[{"t":"(1) 주식 데이터의 조정","c":[{"t":"① 주식분할 조정","n":[["설명","주식분할(Split): 2대1 분할 시 과거 가격을 절반으로 조정하지 않으면 차트에 가짜 50% 폭락 갭이 생긴다. 과거 거래량은 반대로 2배로 조정한다."]]},{"t":"② 배당 조정","n":[["설명","배당(Dividend) 조정: 배당락일에 가격이 배당만큼 하락하므로, 총수익 분석에는 배당 조정 가격을 사용한다."]]},{"t":"③ 생존편향","n":[["설명","생존편향(Survivorship Bias): 상장폐지·합병된 종목을 제외한 데이터로 검증하면 성과가 과대평가된다."]]}]},{"t":"(2) 선물 데이터의 연결","c":[{"t":"① 연속 계약 필요","n":[["설명","선물은 만기가 있으므로 장기 차트를 그리려면 여러 월물을 이어 붙인 연속 계약(Continuous Contract)이 필요하다."]]},{"t":"② 최근월물 연결 시 가짜 갭","n":[["설명","최근월물을 단순히 이어 붙이면(Nearest Futures) 월물 교체 시 가짜 갭이 생긴다. 후방조정(Back-adjusted) 방식은 갭을 제거하지만 과거 가격 수준이 실제와 달라지며 음수가 될 수도 있다."]]},{"t":"③ 월물 교체 시점 기준","n":[["설명","월물 교체 시점은 만기일 기준 또는 거래량·미결제약정이 다음 월물로 넘어가는 시점 기준으로 정한다."],["쉬운 예","데이터 간격은 사진 찍는 간격과 같다. 1분마다 찍으면 세세하지만 흔들림(잡음)이 많고, 하루 한 장이면 큰 흐름만 남는다. 프랙탈은 '해안선을 확대해도 비슷한 모양'인 성질로, 같은 분석 원리를 모든 시간 단위에 쓸 수 있다는 뜻이다."],["문제 연습","2대1 주식분할 직전 종가가 $80, 그날 거래량이 100만 주였다. 분할 조정된 차트에서 이 날의 종가와 거래량은?\n\n풀이 가격은 절반인 $40, 거래량은 2배인 200만 주로 조정한다. 조정하지 않으면 차트에 가짜 50% 폭락 갭이 생긴다."]]}]}]}]},{"t":"Ⅱ 차트의 종류","c":[{"t":"1. 시간 기반 차트","c":[{"t":"(1) 선 차트 (Line Chart)","c":[{"t":"① 종가만 선으로 연결","n":[["설명","각 기간의 종가만 점으로 찍어 직선으로 연결한다. 장중 정보는 사라지지만 전체 추세가 간결하게 보인다."]]},{"t":"② 경제지표에 주로 사용","n":[["설명","경제지표(CPI, GDP 등)처럼 기간당 하나의 값만 있는 데이터에 주로 사용한다."]]},{"t":"③ 겹칠 때 척도 확인","n":[["설명","여러 선을 한 차트에 겹칠 때는 같은 척도를 공유하는지 반드시 확인해야 한다. 이중 축(Dual Y-axis) 차트는 방향 비교에는 유용하지만 크기(수익률) 비교에는 오해를 부른다."]]}]},{"t":"(2) 바 차트 (Bar Chart, OHLC)","c":[{"t":"① 위 고가·아래 저가, 좌시·우종","n":[["설명","세로선의 위 끝이 고가, 아래 끝이 저가이다. 왼쪽 가로 눈금이 시가, 오른쪽 가로 눈금이 종가이다."]]},{"t":"② 세로선=범위, 서양 표준","n":[["설명","세로선 전체가 그 기간의 범위(Range)를 나타낸다. 서양 기술적 분석의 전통적 표준 차트이다."]]}]},{"t":"(3) 캔들차트 (Candlestic k)","c":[{"t":"① 몸통과 그림자","n":[["설명","시가와 종가 사이를 몸통(Real Body)으로 그리고, 몸통 위아래로 고가·저가까지 그림자(Shadow/Wick)를 그린다."]]},{"t":"② 양봉·음봉 구분","n":[["설명","종가가 시가보다 높으면 속이 빈(흰색·양봉) 몸통, 낮으면 속이 찬(검은색·음봉) 몸통이다. \"속이 찬 캔들은 납처럼 무거워 종가가 아래로 가라앉았다\"로 기억하면 쉽다."]]},{"t":"③ 시가·종가 관계 가시성","n":[["설명","바 차트와 같은 정보(OHLC)를 쓰지만 시가·종가 관계(매수·매도 우위)가 시각적으로 훨씬 잘 보인다는 장점이 있다."]]}]}]},{"t":"2. 가격 척도 (Price Scale)","c":[{"t":"(1) 산술 척도 (Arithmeti c Scale)","c":[{"t":"① 같은 금액=같은 거리","n":[["설명","같은 가격 '금액' 변화가 같은 세로 거리로 표시된다. $10→$20과 $1,000→$1,010이 같은 거리이다."]]},{"t":"② 단기 분석에 적합","n":[["설명","가격 범위가 좁은 단기 분석에 적합하다. 장기 차트에서는 과거의 큰 변동(예: 1929년 폭락)이 작게 보이고 최근 변동이 과장된다."]]}]},{"t":"(2) 로그 척도 (Semi-log Scale)","c":[{"t":"① 같은 비율=같은 거리","n":[["설명","같은 '비율(%)' 변화가 같은 세로 거리로 표시된다. $10→$20(+100%)과 $1,000→$2,000(+100%)이 같은 거리이다."]]},{"t":"② 세미로그 차트","n":[["설명","엄밀히는 가격 축만 로그이므로 '세미로그(Semi-log)' 차트이다."]]},{"t":"③ 장기·급등주·수익률 비교","n":[["설명","장기 분석, 가격 변동폭이 큰 종목(급등주), 수익률 비교에 적합하다. 장기 투자자는 로그 척도를 사용해야 한다."]]},{"t":"④ 척도별 추세선 이탈 차이","n":[["설명","같은 추세선도 척도에 따라 이탈 시점이 달라질 수 있으므로 척도를 확인해야 한다."]]}]}]},{"t":"3. 거래량 표시와 비시간 기반 차트","c":[{"t":"(1) 거래량의 일반적 표시","c":[{"t":"① 차트 아래 거래량 막대","n":[["설명","가격 차트 아래에 막대(히스토그램)로 기간별 거래량(주식수·계약수)을 표시한다."]]},{"t":"② 주간 거래량=5일 합계","n":[["설명","주간 차트의 거래량은 해당 주 5거래일 거래량의 합계이다."]]}]},{"t":"(2) 이퀴볼륨 차트 (Equivolume)","c":[{"t":"① 리처드 암스: 높이=범위, 폭=거래량","n":[["설명","리처드 암스(Richard Arms)가 고안하였다. 박스의 높이는 범위(고가-저가), 폭은 거래량이다."]]},{"t":"② 넓고 낮은 박스=지지·저항","n":[["설명","거래량이 많은 날은 넓은 박스로 표시되므로 시간 축이 비선형이 된다. 폭이 넓고 높이가 낮은 박스는 많은 거래에도 가격이 움직이지 않은 '저항·지지'를 시사한다."]]}]},{"t":"(3) 기타 비시간 차트","c":[{"t":"① P&F: 시간 무시","n":[["설명","포인트앤피겨: 가격 변화만 기록하며 시간은 무시한다(Ⅳ에서 상술)."]]},{"t":"② 카기·렌코·삼선전환도","n":[["설명","스윙 차트, 카기(Kagi), 렌코(Renko), 삼선전환도(Three-line Break): 일정 크기 이상의 가격 변화가 있을 때만 새선·벽돌을 그린다."]]},{"t":"③ 틱·거래량 바","n":[["설명","틱·거래량 바: 일정 체결 건수나 거래량마다 봉을 만든다. 스캘핑에서 활용도가 높다."],["쉬운 예","1만 원짜리 주식이 2만 원이 되는 것과 100만 원짜리가 101만 원이 되는 것은 똑같이 '1만 원 상승'이지만, 수익률은 100%와 1%이다. 산술 척도는 둘을 같은 거리로, 로그 척도는 같은 수익률을 같은 거리로 그린다."],["문제 연습","로그 척도 차트에서 $5 → $10의 세로 거리와 같은 거리만큼 $40에서 상승하면 가격은 얼마인가?\n\n풀이 $5 → $10은 +100%이므로 $40의 +100%인 $80이다."]]}]}]}]},{"t":"Ⅲ 캔들차트 분석 (Candlesti ck Charting)","c":[{"t":"1. 단일 캔들의 해석","c":[{"t":"(1) 몸통과 그림자의 의미","c":[{"t":"① 긴 양봉·긴 음봉","n":[["설명","긴 양봉: 시가 대비 종가가 크게 높아 매수세가 강하다. 긴 음봉: 매도세가 강하다."]]},{"t":"② 긴 윗·아랫그림자 의미","n":[["설명","긴 윗그림자: 장중 상승이 매도에 밀려 되돌려졌다(고가권 매도 압력). 긴 아랫그림자: 장중 하락을 매수가 되돌렸다(저가권 매수 지지)."]]},{"t":"③ 직전 추세 맥락과 해석","n":[["설명","캔들 패턴은 단독이 아니라 직전 추세(Context)와 함께 해석해야 한다. 같은 모양도 위치에 따라 이름과 의미가 달라진다."]]}]},{"t":"(2) 도지와 팽이","c":[{"t":"① 도지: 우유부단","n":[["설명","도지(Doji): 시가와 종가가 같거나 거의 같다. 매수·매도의 균형(우유부단)을 나타내며, 긴 추세 뒤에 나오면 추세 약화 경고이다."]]},{"t":"② 도지의 변형","n":[["설명","도지의 변형: 잠자리형 도지(Dragonfly, 긴 아랫그림자), 비석형 도지(Gravestone, 긴 윗그림자), 다리 긴 도지(Long-legged)."]]},{"t":"③ 팽이(Spinning Top)","n":[["설명","팽이(Spinning Top): 몸통이 작고 위아래 그림자가 있는 캔들로 역시 우유부단을 나타낸다."]]}]},{"t":"(3) 우산형과 역망치형","c":[{"t":"① 망치형: 강세 반전","n":[["설명","망치형(Hammer): 하락 추세 끝에 나타나는 작은 몸통 + 몸통의 2배 이상 긴 아랫그림자. 강세 반전 신호이다."]]},{"t":"② 교수형: 약세 반전 경고","n":[["설명","교수형(Hanging Man): 망치형과 모양이 같지만 상승 추세 끝에 나타난다. 약세 반전 경고이며 다음 날 확인이 중요하다."]]},{"t":"③ 역망치형: 강세 가능성","n":[["설명","역망치형(Inverted Hammer): 하락 추세 끝, 긴 윗그림자 + 작은 몸통. 강세 반전 가능성(확인 필요)."]]},{"t":"④ 유성형: 약세 반전","n":[["설명","유성형(Shooting Star): 상승 추세 끝, 긴 윗그림자 + 작은 몸통. 약세 반전 신호이다."]]}]}]},{"t":"2. 복수 캔들 패턴","c":[{"t":"(1) 두 개 캔들 패턴","c":[{"t":"① 상승 장악형","n":[["설명","상승 장악형(Bullish Engulfing): 하락 추세에서 작은 음봉 다음, 그 몸통을 완전히 감싸는 큰 양봉이 나타난다."]]},{"t":"② 하락 장악형","n":[["설명","하락 장악형(Bearish Engulfing): 상승 추세에서 작은 양봉 다음, 그 몸통을 완전히 감싸는 큰 음봉이 나타난다."]]},{"t":"③ 잉태형(Harami)","n":[["설명","잉태형(Harami): 큰 몸통 다음 그 몸통 안에 들어가는 작은 몸통이 나타난다. 추세의 힘이 약해졌다는 신호이다(장악형의 반대 모양). 작은 캔들이 도지이면 '십자잉태형(Harami Cross)'이다."]]},{"t":"④ 먹구름형","n":[["설명","먹구름형(Dark Cloud Cover): 상승 추세에서 양봉 다음, 전일 고가 위에서 시작해 전일 양봉 몸통 중간(50%) 아래에서 끝나는 음봉. 약세 반전이다."]]},{"t":"⑤ 관통형","n":[["설명","관통형(Piercing Line): 하락 추세에서 음봉 다음, 전일 저가 아래에서 시작해 전일 음봉 몸통 중간 위에서 끝나는 양봉. 강세 반전이다."]]}]},{"t":"(2) 세 개 캔들 패턴","c":[{"t":"① 샛별형: 강세 반전","n":[["설명","샛별형(Morning Star): 긴 음봉 → 갭 하락한 작은 몸통(별) → 첫 음봉 몸통 안쪽 깊숙이 올라오는 양봉. 강세 반전이다. 별이 도지이면 '도지 샛별형'이다."]]},{"t":"② 석별형: 약세 반전","n":[["설명","석별형(Evening Star): 긴 양봉 → 갭 상승한 작은 몸통 → 첫 양봉 몸통 안쪽 깊숙이 내려오는 음봉. 약세 반전이다."]]},{"t":"③ 적삼병·흑삼병","n":[["설명","적삼병(Three White Soldiers): 종가가 계속 높아지는 긴 양봉 3개. 강세. 흑삼병(Three Black Crows): 종가가 계속 낮아지는 긴 음봉 3개. 약세."],["표","패턴 | 출현 위치 | 구성 | 신호\n망치형 | 하락 추세 끝 | 작은 몸통 + 긴 아랫그림자 | 강세 반전\n교수형 | 상승 추세 끝 | 망치형과 같은 모양 | 약세 반전(확인 필요)\n유성형 | 상승 추세 끝 | 작은 몸통 + 긴 윗그림자 | 약세 반전\n상승 장악형 | 하락 추세 | 큰 양봉이 전일 음봉 몸통을 감쌈 | 강세 반전\n먹구름형 | 상승 추세 | 전일 양봉 중간 아래로 마감하는 음봉 | 약세 반전\n샛별형 | 하락 추세 | 음봉-별-양봉 | 강세 반전\n석별형 | 상승 추세 | 양봉-별-음봉 | 약세 반전"]]}]}]},{"t":"3. 캔들 분석의 활용과 한계","c":[{"t":"(1) 효과적인 활용법","c":[{"t":"① 서양식 도구와 결합","n":[["설명","서양식 도구(지지·저항, 추세선, 거래량)와 결합하면 신뢰도가 높아진다. 예: 지지선에서 거래량 증가를 동반한 망치형."]]},{"t":"② 반전엔 추세가 있어야","n":[["설명","반전 패턴은 추세가 '있어야' 반전할 수 있다. 추세가 없는 횡보 구간의 패턴은 의미가 약하다."]]}]},{"t":"(2) 한계","c":[{"t":"① 단기 신호, 목표가 없음","n":[["설명","캔들 패턴은 단기(대개 수일 이내) 신호이며, 목표가격을 제시하지 않는다."]]},{"t":"② 확인 봉 대기 권장","n":[["설명","통계 검증 결과 패턴별 신뢰도 편차가 크므로 확인(Confirmation) 봉을 기다리는 것이 좋다."],["쉬운 예","캔들은 하루 동안의 줄다리기 결과표다. 몸통은 최종 승부(시가 대비 종가), 그림자는 중간에 끌려갔다가 되돌아온 흔적이다. 긴 아랫그림자 = '밀렸지만 결국 매수 쪽이 끌어올렸다'."],["문제 연습","하락 추세 끝에서 시가 $20.00, 고가 $20.20, 저가 $18.80, 종가 $20.10인 봉이 나왔다. 이 캔들의 이름은?\n\n풀이 몸통 $0.10, 아랫그림자 $1.20(몸통의 12배), 윗그림자 $0.10 → 작은 몸통 + 긴 아랫그림자이고 하락 추세 끝이므로 망치형(강세 반전 후보)이다. 같은 모양이 상승 추세 끝에 나오면 교수형이다."]]}]}]}]},{"t":"Ⅳ 포인트앤피겨 차트 (Point & Figure)","c":[{"t":"1. 작성 원리","c":[{"t":"(1) 기본 구조","c":[{"t":"① X=상승, O=하락, 시간 무시","n":[["설명","X는 가격 상승, O는 가격 하락을 나타내며, 한 열(Column)에는 X 또는 O만 기록한다. 시간과 거래량은 기록하지 않는다."]]},{"t":"② 박스 크기(Box Size)","n":[["설명","박스 크기(Box Size): X 또는 O 하나가 나타내는 가격 단위이다. 박스 크기가 클수록 잡음이 줄고 장기 추세가 보인다."]]},{"t":"③ 반전 기준: 3박스 반전","n":[["설명","반전 기준(Reversal Amount): 반대 방향으로 몇 박스 이상 움직여야 새 열로 전환하는지를 정한다. 가장 널리 쓰이는 방식은 '3박스 반전(3-box reversal)'이다."]]}]},{"t":"(2) 작성 방법","c":[{"t":"① 고가·저가 기반 작성","n":[["설명","전통적으로 고가·저가를 사용한다. X열에서는 먼저 고가로 새 X를 추가할 수 있는지 보고, 없으면 저가로 3박스 반전여부를 확인한다."]]},{"t":"② 종가 방식·1박스 반전","n":[["설명","종가만 사용하는 방식도 있으며, 1박스 반전 차트는 한 열에 X와 O가 함께 나올 수 있는 예외적 방식이다."]]},{"t":"③ 퍼센트 박스(로그)","n":[["설명","퍼센트 박스(로그 방식)는 가격 수준에 비례하는 박스 크기를 사용한다."]]}]}]},{"t":"2. 매매 신호와 패턴","c":[{"t":"(1) 기본 신호","c":[{"t":"① 이중 천장 돌파=매수","n":[["설명","이중 천장 돌파(Double Top Breakout): 현재 X열이 직전 X열의 고점보다 1박스 위로 올라가면 매수 신호이다. 가장 기본적인 신호이다."]]},{"t":"② 이중 바닥 붕괴=매도","n":[["설명","이중 바닥 붕괴(Double Bottom Breakdown): 현재 O열이 직전 O열의 저점보다 1박스 아래로 내려가면 매도 신호이다."]]},{"t":"③ 삼중 천장·바닥=강한 신호","n":[["설명","삼중 천장 돌파·삼중 바닥 붕괴: 같은 수준에서 두 번 막힌 뒤 돌파하는 것으로 더 강한 신호이다."]]}]},{"t":"(2) 응용 패턴","c":[{"t":"① 삼각형·캐터펄트 패턴","n":[["설명","상승 삼각형·하락 삼각형, 상승 캐터펄트(Catapult: 삼중 천장 돌파 후 눌림 뒤 재돌파), 스프레드 삼중 천장 등이 있다."]]},{"t":"② 강세 지지선·약세 저항선","n":[["설명","강세 지지선(Bullish Support Line): 주요 저점 O 아래에서 45도 각도로 그리는 상승 추세선. 약세 저항선(Bearish Resistance Line): 주요 고점 X 위에서 45도로 그리는 하락 추세선이다."]]},{"t":"③ 45도 추세선 원칙","n":[["설명","포인트앤피겨의 추세선은 박스 대각선을 따라 45도로 그리는 것이 원칙이다."]]}]}]},{"t":"3. 가격 목표 계산","c":[{"t":"(1) 수평 카운트 (Horizontal Count)","c":[{"t":"① 횡보 폭(열 수) 측정","n":[["설명","횡보 구간(밀집 구간, Congestion)의 폭(열의 수)을 측정한다. 원리: 횡보(매집)가 길수록 이후 움직임이 크다."]]},{"t":"② 목표=저점+열×박스×반전","n":[["설명","상승 목표 = 기준가격(횡보 구간의 저점 행) + (열의 수 × 박스 크기 × 반전 박스 수)."]]},{"t":"③ 수평 카운트 계산 예","n":[["설명","예: 박스 $1, 3박스 반전, 횡보 폭 8열, 기준 저점 $40 → 목표 = 40 + (8 × 1 × 3) = $64."]]}]},{"t":"(2) 수직 카운트 (Vertical Count)","c":[{"t":"① 첫 상승 X열 길이 측정","n":[["설명","바닥에서 첫 상승 X열(또는 반전 후 첫 열)의 길이를 측정한다."]]},{"t":"② 목표=바닥+박스수×크기×반전","n":[["설명","상승 목표 = 해당 열 바닥 + (X열 박스 수 × 박스 크기 × 반전 박스 수)."]]},{"t":"③ 수직 카운트 계산 예","n":[["설명","예: 첫 반등 X열 7박스, 박스 $2, 3박스 반전, 바닥 $50 → 목표 = 50 + (7 × 2 × 3) = $92. 하락 목표는 반대로 계산한다."],["쉬운 예","포인트앤피겨는 '계단 오르기 기록장'이다. 얼마나 오래 걸렸는지(시간)는 적지 않고, 몇 칸 올랐고(X) 몇 칸 내려왔는지(O)만 적는다. 3칸 이상 반대로 움직여야 새 줄로 넘어간다(3박스 반전)."],["문제 연습","박스 크기 $0.50, 3박스 반전 차트에서 횡보 구간의 폭이 10열, 기준 저점이 $30이다. 수평 카운트 상승 목표는?\n\n풀이 30 + (10 × 0.5 × 3) = $45."],["주차 핵심 요약","OHLC와 범위(고가-저가). 데이터 간격 = 표본추출, 분석 원리는 프랙탈하게 모든 시간 단위에 적용된 다.\n산술 척도 = 같은 금액이 같은 거리, 로그 척도 = 같은 %가 같은 거리(장기·급등주 분석에 사용).\n이퀴볼륨: 폭 = 거래량. 분할 조정과 선물 연결 방식에 따른 가짜 갭에 주의한다.\n캔들: 위치(추세)가 이름을 결정한다(망치형 vs 교수형). P&F: 3박스 반전, 이중 천장 돌파, 수평/수직 카운트."]]}]}]}]}],"b":3},{"n":4,"t":"추세 분석: 추세선, 지지·저항, 이동평균","c":[{"t":"Ⅰ 추세의 정의와 구조","c":[{"t":"1. 추세의 기본 개념","c":[{"t":"(1) 추세의 정의","c":[{"t":"① 상승 추세: HH+HL","n":[["설명","상승 추세(Uptrend): 고점과 저점이 연속적으로 높아지는 구조(Higher High + Higher Low)이다."],["이번 주 학습목표","① 추세의 정의(고점·저점 구조)와 추세선·채널 작도법, 추세선의 유효성 판단 기준을 설명할 수 있다.② 지지·저항의 형성 원리와 역할 전환(Polarity), 돌파의 확인 방법을 이해한다.\n③ 되돌림(Retracement) 비율과 추세 반전의 신호를 구별할 수 있다.\n④ 단순·지수·가중 이동평균의 계산, 시차(Lag), 교차 신호와 엔벨로프·밴드를 익힌다."]]},{"t":"② 하락 추세: LH+LL","n":[["설명","하락 추세(Downtrend): 고점과 저점이 연속적으로 낮아지는 구조(Lower High + Lower Low)이다."]]},{"t":"③ 횡보: 추세 없는 상태","n":[["설명","횡보(Sideways/Trading Range): 고점과 저점이 일정 범위 안에서 반복되는 구조로, 추세가 없는(Trendless) 상태이다. 시장은 상당 기간을 횡보로 보낸다."]]}]},{"t":"(2) 추세의 시간 단위","c":[{"t":"① 시간 단위별 추세 상이","n":[["설명","추세는 시간 단위에 따라 다르다. 일간 차트의 상승 추세 안에 1분 차트의 하락 추세가 존재할 수 있다."]]},{"t":"② 목적에 맞는 시간 단위","n":[["설명","다우 이론의 1차·2차·소추세 구분과 같이, 분석 목적에 맞는 시간 단위의 추세를 기준으로 삼는다."]]}]}]},{"t":"2. 추세 반전의 구조적 신호","c":[{"t":"(1) 스윙 고점·저점 (Swing High/Low)","c":[{"t":"① 스윙 고점·저점 정의","n":[["설명","스윙 고점은 양옆 봉보다 높은 고점, 스윙 저점은 양옆 봉보다 낮은 저점이다. 추세 판단은 스윙 포인트의 배열로 한다."]]},{"t":"② 스윙 필터로 잡음 제거","n":[["설명","스윙 필터: 일정 비율(예: 5%) 이상 반대로 움직여야 새 스윙으로 인정하면 잡음을 줄일 수 있다."]]}]},{"t":"(2) 반전의 두 단계","c":[{"t":"① 1단계 경고: LH·저점 이탈","n":[["설명","1단계 경고: 상승 추세에서 새 고점이 직전 고점을 넘지 못함(Lower High) 또는 직전 저점을 이탈한다."]]},{"t":"② 2단계 확인: 반등 실패","n":[["설명","2단계 확인: 저점 이탈 후 반등이 직전 고점을 넘지 못하고 다시 하락하면 하락 추세가 확인된다."]]},{"t":"③ BOS·CHOCH와의 연결","n":[["설명","스캘핑 용어와의 연결: 직전 스윙 고점 돌파 = BOS(추세 지속), 상승 추세의 Higher Low 붕괴 = CHOCH(성격 변화 가능성). 이는 다우 이론의 고점·저점 구조를 단기 차트에 적용한 것이다."],["쉬운 예","상승 추세는 올라가는 계단이다. 중간에 한 칸 내려오더라도 이전에 내려온 칸보다 높은 곳에서 멈추고(Higher Low), 다시 이전보다 높이 올라간다(Higher High)."],["실전 사례","5분봉에서 고점이 10.20 → 10.50 → 10.80, 저점이 10.00 → 10.30 → 10.55로 높아지면 상승 추세이다. 가격이 10.55를 깨면 1단계 경고(CHOCH), 이어서 반등이 10.80을 넘지 못하고 10.30마저 깨면 하락 추세가 확인된다."]]}]}]}]},{"t":"Ⅱ 추세선과 채널","c":[{"t":"1. 추세선 (Trendline)","c":[{"t":"(1) 작도법","c":[{"t":"① 상승 추세선: 저점 연결","n":[["설명","상승 추세선: 상승하는 두 개 이상의 주요 저점을 연결하여 가격 아래에 긋는다."]]},{"t":"② 하락 추세선: 고점 연결","n":[["설명","하락 추세선: 하락하는 두 개 이상의 주요 고점을 연결하여 가격 위에 긋는다."]]},{"t":"③ 세 번째 접점이 유효성 확인","n":[["설명","선을 긋는 데 두 점이 필요하고, 세 번째 접점이 추세선의 유효성을 '확인'한다. 가격에 억지로 맞추는 선이 아니라 추세 구조를 관찰하는 기준선이다."]]}]},{"t":"(2) 추세선의 중요도 판단","c":[{"t":"① 접촉 횟수","n":[["설명","접촉 횟수: 가격이 추세선에 더 많이 접촉하고 지지(저항)받을수록 중요하다."]]},{"t":"② 길이","n":[["설명","길이: 추세선이 오래 유지될수록 중요하다."]]},{"t":"③ 기울기: 약 45도 지속적","n":[["설명","기울기(각도): 너무 가파른 추세선은 지속 불가능하여 쉽게 깨진다. 약 45도가 가장 지속 가능하다는 관점이 전통적이다."]]},{"t":"④ 거래량 반응","n":[["설명","거래량: 추세선 접촉 지점에서 거래량 반응이 있으면 신뢰도가 높다."]]}]},{"t":"(3) 추세선 이탈과 재작도","c":[{"t":"① 이탈=추세 변화 경고","n":[["설명","추세선 이탈은 추세 '반전'이 아니라 추세 '변화(속도 둔화 또는 횡보 전환)'의 경고이다."]]},{"t":"② 이탈 확인 필터","n":[["설명","이탈 확인 필터: 종가 기준 이탈, 일정 비율(예: 3%) 이상 이탈, 2일 연속 이탈(시간 필터) 등을 사용한다."]]},{"t":"③ 부채꼴 원리(Fan)","n":[["설명","부채꼴 원리(Fan Principle): 추세선이 깨질 때마다 더 완만한 추세선을 다시 긋고, 세 번째 추세선이 깨지면 추세 반전 가능성이 높다."]]},{"t":"④ 가속 추세선=과열 신호","n":[["설명","가속 추세선: 추세가 가팔라지면 더 가파른 새 추세선을 긋는다. 가속은 추세 말기의 과열 신호일 수 있다."]]}]}]},{"t":"2. 채널 (Channel)","c":[{"t":"(1) 작도와 의미","c":[{"t":"① 채널선(Return Line)","n":[["설명","상승 채널: 상승 추세선과 평행하게 주요 고점을 지나는 선(채널선, Return Line)을 긋는다. 하락 채널은 반대이다."]]},{"t":"② 상단 이익실현·하단 매수","n":[["설명","채널 상단은 이익실현, 하단은 매수 구간으로 활용한다(추세 방향 거래 우선)."]]}]},{"t":"(2) 채널 신호","c":[{"t":"① 상단 미도달=약화 신호","n":[["설명","가격이 채널 상단(채널선)에 도달하지 못하면 추세 약화 신호이며, 반대편 추세선 이탈 가능성이 커진다."]]},{"t":"② 상단 돌파=가속 신호","n":[["설명","가격이 채널 상단을 상향 돌파하면 추세 가속 신호이다."]]},{"t":"③ 채널 폭만큼 목표 설정","n":[["설명","채널 폭만큼 돌파 방향으로 목표를 설정하는 방법도 사용된다."],["쉬운 예","부채꼴 원리는 '삼세번'이다. 첫째 추세선이 깨지면 더 완만한 둘째 선을, 둘째가 깨지면 셋째 선을 긋는다. 세 번째 선까지 깨지면 추세가 끝났을 가능성이 높다."],["문제 연습","오늘 상승 추세선 값이 $50이고 '3% 가격 필터'를 쓴다. 종가가 $48.80이면 유효한 이탈인가?\n\n풀이 필터 기준선 = 50 × 0.97 = $48.50. 종가 $48.80은 기준선 위이므로 아직 유효한 이탈이 아니다."]]}]}]}]},{"t":"Ⅲ 지지와 저항","c":[{"t":"1. 지지·저항의 개념과 형성 원리","c":[{"t":"(1) 정의","c":[{"t":"① 지지: 수요 집중 구간","n":[["설명","지지(Support): 매수세가 매도세를 압도하여 하락이 멈추거나 반등하는 가격 수준(수요 집중 구간)이다."]]},{"t":"② 저항: 공급 집중 구간","n":[["설명","저항(Resistance): 매도세가 매수세를 압도하여 상승이 멈추거나 되밀리는 가격 수준(공급 집중 구간)이다."]]},{"t":"③ 선보다 구간(Zone)","n":[["설명","지지·저항은 정확한 '선'보다 '구간(Zone)'으로 보는 것이 현실적이다."]]}]},{"t":"(2) 형성 원리 (심리적 근거)","c":[{"t":"① 과거 대량 거래 가격 기억","n":[["설명","과거에 해당 가격에서 대량 거래가 있었다면 그 가격을 기억하는 참여자가 많다. 손실 중인 매수자는 본전에 팔려 하고(저항), 매수 기회를 놓친 사람은 그 가격에 다시 사려 한다(지지)."]]},{"t":"② 거래량·체류·최근성","n":[["설명","거래량이 많았던 가격대, 오래 머문 가격대, 최근에 형성된 가격대일수록 강한 지지·저항이 된다."]]},{"t":"③ 라운드 넘버·갭·이평선","n":[["설명","라운드 넘버($10, $50, $100 등)와 과거 고점·저점, 갭, 이동평균선도 지지·저항 역할을 한다."]]}]}]},{"t":"2. 역할 전환과 돌파","c":[{"t":"(1) 역할 전환 (Polarity / Role Reversal)","c":[{"t":"① 저항→지지 전환","n":[["설명","저항선이 상향 돌파되면 이후 지지선으로 바뀐다(Old Resistance → New Support)."]]},{"t":"② 지지→저항 전환","n":[["설명","지지선이 하향 이탈되면 이후 저항선으로 바뀐다(Old Support → New Resistance)."]]},{"t":"③ Throwback·Pullback","n":[["설명","돌파 후 가격이 돌파 수준으로 되돌아와 테스트하는 것을 상향 돌파 시 '되돌림(Throwback)', 하향 이탈 시 '재상승 테스트(Pullback)'라고 한다. 이 테스트가 성공하면 돌파의 신뢰도가 높아진다."]]}]},{"t":"(2) 돌파의 확인","c":[{"t":"① 가격 필터","n":[["설명","가격 필터: 종가 기준, 일정 비율 이상의 돌파를 요구한다."]]},{"t":"② 시간 필터","n":[["설명","시간 필터: 돌파 상태가 일정 기간(예: 2일) 유지되는지 확인한다."]]},{"t":"③ 거래량 확인","n":[["설명","거래량 확인: 상향 돌파 시 거래량 증가는 신뢰도를 높인다. 거래량 없는 돌파는 실패 가능성이 높다(하향 이탈은 거래량 없이도 일어날 수 있다)."]]},{"t":"④ 실패 돌파와 불·베어 트랩","n":[["설명","실패 돌파(False Breakout)와 함정: 돌파 직후 다시 범위 안으로 되돌아오면 '불 트랩(Bull Trap)/베어 트랩(Bear Trap)'이 되어 반대 방향 신호가 될 수 있다."],["실전 사례","스캘핑 적용: 돌파 확인 스택 — ① 봉 마감이 레벨 위에서 이루어졌는가? ② 거래량(상대거래량)이 증가했는가? ③ 되돌림이 레벨(및 VWAP) 위에서 지지되는가? ④ 재돌파 시 매도호가가 흡수되는가? 돌파 실패 시 무효화 지점(레벨 아래)이 명확하므로 손절 기준이 곧바로 정해진다."]]}]}]},{"t":"3. 되돌림 (Retracement)","c":[{"t":"(1) 주요 되돌림 비율","c":[{"t":"① 1/3·1/2·2/3 되돌림","n":[["설명","1/3(33%), 1/2(50%), 2/3(67%): 다우 이론과 갠이 강조한 비율이다. 50% 되돌림이 가장 흔하다."]]},{"t":"② 피보나치 38.2%·61.8%","n":[["설명","피보나치 비율 38.2%, 61.8%: 피보나치 수열에서 유도된 비율로 널리 사용된다."]]},{"t":"③ 얕은 되돌림=강한 추세","n":[["설명","되돌림이 얕을수록(33~38%) 추세가 강하다. 2/3(또는 61.8%)를 넘는 되돌림은 추세 반전 가능성을 높인다."]]}]},{"t":"(2) 활용법","c":[{"t":"① 스윙 상승폭 기준 계산","n":[["설명","직전 스윙 저점에서 스윙 고점까지의 상승폭을 기준으로 되돌림 수준을 계산한다. 예: $20→$30 상승 후 50% 되돌림은 $25이다."]]},{"t":"② 지지·이평 겹침(Confluenc e)","n":[["설명","되돌림 수준이 과거 지지선·이동평균과 겹치면(Confluence) 신뢰도가 높아진다."],["쉬운 예","역할 전환은 아파트 층과 같다. 2층에서 보면 천장(저항)이던 것이 3층으로 올라가면 바닥(지지)이 된다."],["문제 연습","$20에서 $30까지 상승한 뒤의 되돌림 수준을 구하시오(1/3, 38.2%, 50%, 61.8%, 2/3).\n\n풀이 상승폭 $10 → 1/3: $26.67, 38.2%: $26.18, 50%: $25.00, 61.8%: $23.82, 2/3: $23.33. 2/3 아래로 깊게 되돌리면 추세 반전 가능성이 커진다."]]}]}]}]},{"t":"Ⅳ 이동평균 (Moving Averages)","c":[{"t":"1. 이동평균의 종류와 계산","c":[{"t":"(1) 단순 이동평균 (SMA)","c":[{"t":"① SMA: n개 산술평균","n":[["설명","최근 n개 가격의 산술평균이다. SMA = (P1 + P2 + … + Pn) ÷ n. 새 데이터가 들어오면 가장 오래된 데이터가 빠진다."]]},{"t":"② 동일 가중·탈락 효과","n":[["설명","모든 데이터에 같은 가중치를 준다. 오래된 가격이 빠질 때 이동평균이 변하는 '탈락 효과(Drop-off effect)'가 생긴다."]]},{"t":"③ SMA 계산 예","n":[["설명","예: 종가 10, 11, 12, 13, 14의 5일 SMA = 60 ÷ 5 = 12."]]}]},{"t":"(2) 가중 이동평균 (WMA)","c":[{"t":"① WMA: 최근에 큰 가중치","n":[["설명","최근 가격에 더 큰 가중치를 준다. 선형가중 이동평균은 가장 최근 값에 n, 그 다음에 n-1, … 가장 오래된 값에 1의 가중치를 준다."]]},{"t":"② WMA 계산 예","n":[["설명","예: 3일 선형가중(최근 가중치 3) 가격 10, 11, 12 → (10×1 + 11×2 + 12×3) ÷ 6 = 68 ÷ 6 ≈ 11.33."]]}]},{"t":"(3) 지수 이동평균 (EMA)","c":[{"t":"① EMA 공식: α=2÷(n+1)","n":[["설명","EMA = 오늘 가격 × α + 전일 EMA × (1 - α), 평활상수 α = 2 ÷ (n + 1)."]]},{"t":"② EMA 계산 예","n":[["설명","예: 19일 EMA의 α = 2 ÷ 20 = 0.1. 전일 EMA 50, 오늘 종가 60이면 EMA = 60×0.1 + 50×0.9 = 51."]]},{"t":"③ 탈락 효과 없음, 빠른 반응","n":[["설명","모든 과거 데이터가 지수적으로 감소하는 가중치로 남아 있으며 탈락 효과가 없다. SMA보다 가격 변화에 빠르게 반응한다."]]}]},{"t":"(4) 기타 이동평균","c":[{"t":"① 적응형 이평(KAMA)","n":[["설명","적응형 이동평균(예: 카우프만 KAMA): 추세가 강하면 빠르게, 잡음이 크면 느리게 반응하도록 평활상수를 조정한다."]]},{"t":"② 중심 이동평균","n":[["설명","중심 이동평균(Centered MA): 이동평균을 기간의 중앙(n/2 이전 시점)에 그려 시차를 제거한다. 사이클 분석에 사용되지만 최근 구간 값이 없다."]]},{"t":"③ 삼각 이동평균","n":[["설명","삼각 이동평균(Triangular MA): 이동평균의 이동평균으로 중간 데이터에 가중치가 높고 매우 평활하다."]]}]}]},{"t":"2. 이동평균의 특성","c":[{"t":"(1) 시차 (Lag)","c":[{"t":"① 기간 길수록 시차 증가","n":[["설명","모든 이동평균은 과거 데이터를 평균하므로 후행한다. 기간이 길수록 매끄럽지만 시차가 커진다."]]},{"t":"② SMA 시차≈(n-1)÷2","n":[["설명","n일 SMA의 시차는 약 (n-1) ÷ 2일이다. 예: 21일 SMA의 시차는 약 10일이다."]]},{"t":"③ 민감도·신뢰도 상충","n":[["설명","민감도와 신뢰도의 상충(Trade-off): 짧은 이동평균은 빠르지만 휩소가 많고, 긴 이동평균은 신호가 적지만 늦다."]]}]},{"t":"(2) 기간 선택","c":[{"t":"① 관행 기간: 20·50·200일","n":[["설명","관행적 기간: 단기 10·20일, 중기 50일, 장기 200일(약 40주). 200일선은 강세장·약세장 구분 기준으로 널리 사용된다."]]},{"t":"② 사이클 절반+1 기간","n":[["설명","사이클 관점: 이동평균 기간을 지배적 사이클 길이의 절반+1로 설정하면 해당 사이클을 효과적으로 평활할 수 있다는 견해가 있다."]]},{"t":"③ 백테스트·과최적화 주의","n":[["설명","최적 기간은 시장·시간 단위마다 다르므로 백테스트로 검증하되 과최적화(Over-fitting)에 주의한다."]]}]}]},{"t":"3. 이동평균을 이용한 신호","c":[{"t":"(1) 가격과 이동평균","c":[{"t":"① 이평 위 강세·아래 약세","n":[["설명","가격이 이동평균 위에서 종가를 형성하면 강세, 아래면 약세로 본다. 이동평균의 기울기(방향)가 추세 방향을 나타낸다."]]},{"t":"② 동적 지지·저항","n":[["설명","상승 추세에서 이동평균은 동적 지지선, 하락 추세에서는 동적 저항선 역할을 한다."]]},{"t":"③ 그랜빌의 8가지 법칙","n":[["설명","그랜빌(Granville)의 법칙: 이동평균의 방향 전환과 가격의 교차·이격을 결합한 8가지 매매 규칙이다."]]}]},{"t":"(2) 교차 (Crossover)","c":[{"t":"① 단기·장기 이평 교차","n":[["설명","두 이동평균 교차: 단기 이동평균이 장기 이동평균을 상향 돌파하면 매수, 하향 돌파하면 매도 신호이다."]]},{"t":"② 골든크로스·데드크로스","n":[["설명","골든크로스(Golden Cross): 50일선이 200일선을 상향 돌파. 데드크로스(Death Cross): 50일선이 200일선을 하향 돌파."]]},{"t":"③ 세 이동평균 배열","n":[["설명","세 이동평균(예: 4·9·18일): 세 선의 정배열·역배열로 추세를 판단한다. 교차 시스템은 추세장에서 효과적이나 횡보장에서 휩소가 많다."]]}]}]},{"t":"4. 엔벨로프와 밴드","c":[{"t":"(1) 엔벨로프 (Envelope)","c":[{"t":"① 이평 ±일정 비율 밴드","n":[["설명","이동평균 위아래로 일정 비율(예: ±3%)의 선을 그린다. 가격이 밴드 밖으로 나가면 과매수·과매도로 본다."]]},{"t":"② 변동성 반영 못함","n":[["설명","변동성 변화를 반영하지 못한다는 한계가 있다."]]}]},{"t":"(2) 볼린저 밴드 (Bollinger Bands)","c":[{"t":"① 20SMA ± 2σ","n":[["설명","존 볼린저가 고안하였다. 중심선 20일 SMA, 상·하단 = 중심선 ± 2 × 표준편차(20일)."]]},{"t":"② 스퀴즈=큰 움직임 전조","n":[["설명","변동성이 커지면 밴드가 넓어지고 작아지면 좁아진다. 밴드가 극단적으로 좁아지는 '스퀴즈(Squeeze)'는 큰 움직임의 전조이다."]]},{"t":"③ 밴드 워크 주의","n":[["설명","강한 추세에서는 가격이 밴드 상단을 따라 걸어 올라가는 '밴드 워크(Walking the band)'가 나타나므로 상단 접촉을 곧바로 매도 신호로 보면 안 된다."]]},{"t":"④ %b와 밴드폭","n":[["설명","%b(밴드 내 가격 위치)와 밴드폭(Bandwidth) 지표로 수치화할 수 있다."]]}]},{"t":"(3) 켈트너 채널 (Keltner Channel)","c":[{"t":"① EMA ± ATR 배수","n":[["설명","현대적 켈트너 채널은 EMA 중심선에 ATR(평균 실제 범위)의 배수를 더하고 빼서 만든다."]]},{"t":"② 표준편차 vs ATR","n":[["설명","볼린저 밴드(표준편차)와 켈트너 채널(ATR)은 변동성 측정 방식이 다르다."],["쉬운 예","단순 이동평균의 탈락 효과는 '반 평균'과 같다. 시험을 아주 잘 본 학생이 전학을 가면 새 학생이 평범해도 반 평균이 뚝 떨어진다. 지수 이동평균은 옛 학생의 점수를 조금씩 희미하게 남겨 두어 이런 출렁임이 없다."],["문제 연습","(가) 9일 EMA의 평활상수 α는? (나) 전일 9일 EMA가 20, 오늘 종가가 22이면 오늘 EMA는? (다) 41일 SMA의 시차는?\n\n풀이 (가) 2 ÷ (9 + 1) = 0.2. (나) 22 × 0.2 + 20 × 0.8 = 20.4. (다) (41 - 1) ÷ 2 = 20일."],["주차 핵심 요약","추세 = HH·HL(상승) / LH·LL(하락). 추세선: 2점으로 긋고 3번째 접점으로 확인, 이탈은 '변화'의 경고, 부채꼴 원리(3번째 선 이탈).\n지지·저항은 구간이며, 돌파되면 역할이 바뀐다. 되돌림 33·50·67%, 피보나치 38.2·61.8%.\nSMA 시차 ≈ (n-1)/2, EMA α = 2/(n+1). 골든/데드크로스(50·200일). 볼린저 = 20일 SMA ± 2σ."]]}]}]}]}],"b":4},{"n":5,"t":"차트 패턴과 단기 패턴","c":[{"t":"Ⅰ 차트 패턴의 기본 개념","c":[{"t":"1. 패턴이란 무엇인가","c":[{"t":"(1) 패턴의 구성","c":[{"t":"① 기본 요소: 지지와 저항","n":[["설명","모든 패턴의 기본 구성요소는 지지(Support)와 저항(Resistance)이다. 지지·저항선은 수평선, 기울어진 선, 곡선일 수 있다."],["이번 주 학습목표","① 차트 패턴의 구성 요소(지지·저항, 진입·이탈 방향, 되돌림·함정·실패)와 분류(반전·지속)를 설명할 수 있다.\n② 이중·삼중 천장/바닥, 헤드앤숄더, 직사각형, 삼각형, 쐐기, 깃발·페넌트 등 고전 패턴을 식별할 수 있다.\n③ 패턴의 측정 목표(Measured Move)와 거래량 특성을 이해한다.\n④ 갭, 반전일, 인사이드·아웃사이드 봉, 좁은 범위 봉 등 단기 패턴을 구별할 수 있다."]]},{"t":"② 군중심리에서 패턴 형성","n":[["설명","패턴은 인간의 행동(군중심리)에서 생긴다. 가격이 일정 범위에서 머무르는 동안 매수·매도 세력의 힘이 축적되고, 한쪽이 우위를 점하면 돌파(Breakout)가 일어난다."]]},{"t":"③ 주관 분석→통계 검증","n":[["설명","전통적으로 패턴은 관찰과 경험에 의존한 주관적 분석이었으나, 컴퓨터 보급 후 패턴 인식 알고리즘과 통계 검증(예: 불코우스키의 통계)이 가능해졌다."]]}]},{"t":"(2) 패턴의 진입과 이탈","c":[{"t":"① 진입·이탈 4가지 조합","n":[["설명","가격은 패턴에 위(하락 추세)나 아래(상승 추세)에서 진입하고, 위 또는 아래로 이탈한다. 따라서 4가지 조합이 가능하다."]]},{"t":"② 반전 패턴","n":[["설명","반전 패턴(Reversal): 진입 방향과 반대로 이탈할 가능성이 높은 패턴이다. 예: 하락 추세로 진입해 위로 이탈하면 '강세 반전'이다."]]},{"t":"③ 지속 패턴","n":[["설명","지속 패턴(Continuation): 진입 방향과 같은 방향으로 이탈할 가능성이 높은 패턴이다. 예: 하락 추세로 진입해 아래로 이탈하면 '약세 지속'이다."]]},{"t":"④ 강세·약세=이탈 방향","n":[["설명","강세·약세라는 명칭은 '이탈(Exit) 방향'에 대한 기대를 가리킨다."]]}]}]},{"t":"2. 패턴 관련 핵심 용어","c":[{"t":"(1) 되돌림과 재테스트","c":[{"t":"① 스로백(Throwback)","n":[["설명","스로백(Throwback): 상향 돌파 후 가격이 돌파 지점(패턴)으로 되돌아오는 움직임이다. \"위로 던져졌다가 다시 던져져 내려온다\"로 기억한다."]]},{"t":"② 풀백(Pullback)","n":[["설명","풀백(Pullback): 하향 이탈 후 가격이 이탈 지점으로 되돌아 올라오는 움직임이다. \"올가미로 다시 끌어당긴다\"로 기억한다."]]},{"t":"③ 역할 전환 관찰","n":[["설명","스로백·풀백에서는 돌파된 저항이 지지로, 이탈된 지지가 저항으로 바뀌는 역할 전환이 관찰된다."]]}]},{"t":"(2) 실패와 함정","c":[{"t":"① 실패(Failure) 기준","n":[["설명","실패(Failure): 돌파 후 기대한 최소 수익(커크패트릭과 달퀴스트는 10%, 불코우스키는 20% 기준)을 내지 못하고 되돌아오는 경우이다."]]},{"t":"② 함정(Trap)","n":[["설명","함정(Trap): 돌파가 실패하여 패턴 안으로 돌아올 뿐 아니라 반대편 경계까지 돌파하는 경우이다. 상향 돌파 실패 후 하향 이탈하면 불 트랩(Bull Trap), 반대는 베어 트랩(Bear Trap)이다."]]},{"t":"③ 손익분기 실패율 33%","n":[["설명","손익분기 실패율(Break-even Failure Rate): 교재의 성과 통계에서는 약 33%를 기준으로 삼으며, 실패율이 이보다 낮으면 신뢰할 만한 패턴으로 본다."]]},{"t":"④ 실패 자체도 매매 신호","n":[["설명","슈웨거(Schwager)는 실패 자체가 좋은 매매 신호가 될 수 있다고 하였다."]]}]},{"t":"(3) 측정 목표 (Measured Move)","c":[{"t":"① 패턴 높이만큼 목표","n":[["설명","대부분의 패턴은 패턴의 높이(Height)를 돌파 지점에서 이탈 방향으로 더하여 최소 목표가를 산출한다."]]},{"t":"② 깃발은 깃대 길이 기준","n":[["설명","깃발·페넌트는 깃대(Flagpole)의 길이를 돌파 지점에 더한다. 목표가는 확률적 기준이지 보장된 가격이 아니다."],["쉬운 예","스로백(Throwback)은 위로 던진 공이 다시 떨어지는 모습(상향 돌파 후 되돌림), 풀백(Pullback)은 아래로 떨어진 것을 줄로 다시 끌어당기는 모습(하향 이탈 후 되돌림)이다."],["문제 연습","상향 돌파 가격 $50, 이후 최고가 $53을 찍고 패턴 안으로 되돌아왔다. 불코우스키의 20% 기준으로 이 돌 파는 실패인가? 이후 패턴 하단까지 이탈하면 무엇이라 부르는가?\n\n풀이 최대 상승률 6% < 20% → 실패. 하단까지 이탈하면 불 트랩(함정)이다."]]}]}]}]},{"t":"Ⅱ 반전 패턴 (Reversal Patterns)","c":[{"t":"1. 이중 천장·이중 바닥","c":[{"t":"(1) 구조","c":[{"t":"① 이중 바닥: W자","n":[["설명","이중 바닥(Double Bottom): 비슷한 가격대의 두 저점과 그 사이의 고점(확인선, Confirmation Line)으로 구성된 'W' 모양이다. 두 저점 사이 고점을 상향 돌파할 때 패턴이 완성된다."]]},{"t":"② 이중 천장: M자","n":[["설명","이중 천장(Double Top): 두 고점과 그 사이 저점으로 구성된 'M' 모양이며, 사이 저점을 하향 이탈할 때 완성된다."]]},{"t":"③ 같은 가격 두 번 막힘","n":[["설명","해석: 같은 가격에서 두 번 막혔다는 것은 그 가격에 강한 수요(또는 공급)가 있다는 증거이다."]]}]},{"t":"(2) 아담과 이브 (Adam & Eve)","c":[{"t":"① 아담: 뾰족한 V자","n":[["설명","아담(Adam): 하루의 큰 반전으로 만들어진 뾰족한 V자 형태의 천장·바닥이다."]]},{"t":"② 이브: 둥근 형태","n":[["설명","이브(Eve): 여러 날에 걸쳐 둥글게 형성된 천장·바닥이다."]]},{"t":"③ 이브-이브 성과 최고","n":[["설명","아담-아담, 아담-이브, 이브-아담, 이브-이브의 조합이 있으며, 통계적으로 '이브-이브' 이중 바닥의 성과가 가장 좋은 편이다."]]}]},{"t":"(3) 목표와 신뢰도","c":[{"t":"① 목표=확인선±패턴 높이","n":[["설명","목표 = 확인선 돌파 가격 ± 패턴 높이(저점~확인선 거리)."]]},{"t":"② 실패율 낮음(15~18%)","n":[["설명","이중 바닥의 실패율은 낮은 편(약 15~18%)으로 신뢰할 만하다. 거래량은 필수 요건은 아니나 돌파 시 증가가 바람직하다."]]}]}]},{"t":"2. 삼중 천장·삼중 바닥과 직사각형","c":[{"t":"(1) 삼중 천장·삼중 바닥","c":[{"t":"① 세 번 고점·저점 반전","n":[["설명","비슷한 가격에서 세 번의 고점(또는 저점)이 형성되고, 사이 저점(고점)을 이탈하면 완성되는 반전 패턴이다."]]},{"t":"② 이중보다 드물고 의미 큼","n":[["설명","이중 패턴보다 드물지만 형성 기간이 길어 의미가 크다. 사이 저점들이 반드시 같은 높이일 필요는 없다."]]}]},{"t":"(2) 직사각형 (Rectangle)","c":[{"t":"① 수평 지지·저항 왕복","n":[["설명","명확한 수평 지지선과 수평 저항선 사이에서 가격이 여러 번(4~5회 이상 접촉) 왕복하는 패턴이다. 반전·지속 모두 가능하다."]]},{"t":"② 쇼트폴(Shortfall)","n":[["설명","쇼트폴(Shortfall): 가격이 한쪽 경계에 도달하지 못하고 되돌아서는 현상으로, 도달하지 못한 경계의 반대 방향으로 돌파가 임박했다는 단서가 될 수 있다."]]},{"t":"③ 목표=돌파가±높이","n":[["설명","목표 = 돌파 가격 ± 직사각형 높이. 돌파 시 거래량 증가가 확인 요소이다."]]}]}]},{"t":"3. 헤드앤숄더 (Head and Shoulders)","c":[{"t":"(1) 천장형 헤드앤숄더","c":[{"t":"① 좌어깨→머리→우어깨","n":[["설명","구성: 왼쪽 어깨(Left Shoulder) → 더 높은 머리(Head) → 머리보다 낮은 오른쪽 어깨(Right Shoulder). 두 어깨 사이의 저점을 이은 선이 목선(Neckline)이다."]]},{"t":"② 목선 이탈 시 완성","n":[["설명","완성: 가격이 목선을 하향 이탈(종가 기준)할 때 패턴이 완성된다. 목선 이탈 전에는 패턴이 아니다."]]},{"t":"③ 거래량 점차 감소","n":[["설명","거래량 특성: 왼쪽 어깨에서 거래량이 가장 많고, 머리에서 감소, 오른쪽 어깨에서 더 감소하는 것이 전형적이다. 이는 상승 에너지 약화를 보여준다."]]},{"t":"④ 목표=목선-머리 높이","n":[["설명","목표 = 목선 이탈 지점 - (머리 고점에서 목선까지의 수직 거리). 이탈 후 목선으로의 풀백이 흔하다."]]}]},{"t":"(2) 역헤드앤숄더 (Inverse H&S)","c":[{"t":"① 하락 끝 바닥형 반전","n":[["설명","하락 추세 끝에서 나타나는 바닥형 반전 패턴으로, 천장형을 뒤집은 구조이다."]]},{"t":"② 목선 돌파 시 거래량 증가","n":[["설명","천장형과 달리 목선 상향 돌파 시 거래량 증가가 중요한 확인 요소이다."]]},{"t":"③ 목표=목선+머리 깊이","n":[["설명","목표 = 목선 돌파 지점 + (목선에서 머리 저점까지의 수직 거리)."]]}]},{"t":"(3) 계산 예","c":[{"t":"① 천장형 계산 예: $40","n":[["설명","머리 고점 $60, 머리 아래 목선 $50, 목선 이탈 $50 → 목표 = 50 - (60 - 50) = $40."]]},{"t":"② 역H&S 계산 예: $32","n":[["설명","역헤드앤숄더에서 머리 저점 $20, 목선 $26 돌파 → 목표 = 26 + 6 = $32."]]}]}]},{"t":"4. 원형·V자·확산형 패턴","c":[{"t":"(1) 원형 천장·원형 바닥 (Rounding / Saucer)","c":[{"t":"① 완만한 곡선 방향 전환","n":[["설명","가격이 완만한 곡선을 그리며 방향을 서서히 바꾸는 패턴이다. 원형 바닥에서 거래량도 가격처럼 U자 형태를 보이는 경우가 많다."]]},{"t":"② 돌파 지점 불명확","n":[["설명","형성 기간이 길고 명확한 돌파 지점이 없어 매매 시점 판단이 어렵다."]]}]},{"t":"(2) V자 반전 (Spike/V-R eversal)","c":[{"t":"① 경고 없는 급격한 반전","n":[["설명","과도한 추세가 경고 없이 급격히 반전하는 패턴이다. 사전 형성 구간이 거의 없어 예측이 어렵다."]]},{"t":"② 대량 거래·극단 심리","n":[["설명","흔히 대량 거래와 극단적 심리를 동반한다."]]}]},{"t":"(3) 확산형 (Broadening Formation)","c":[{"t":"① 메가폰 모양 확산","n":[["설명","고점은 점점 높아지고 저점은 점점 낮아져 메가폰 모양으로 벌어지는 패턴이다."]]},{"t":"② 변동성 확대, 천장권 출현","n":[["설명","변동성 확대와 시장 참여자의 혼란·감정적 거래를 반영하며, 주로 천장권에서 나타난다."],["쉬운 예","헤드앤숄더는 세 번 점프하는 사람이다. 두 번째 점프(머리)가 가장 높지만 박수(거래량)는 첫 번째보다 작고, 세 번째(오른쪽 어깨)는 힘이 빠져 낮다. 결국 발판(목선)이 꺼지면 추락이 확정된다."],["문제 연습","이중 바닥의 두 저점이 $40, $40.50, 확인선(사이 고점)이 $46이다. 확인선 상향 돌파 시 목표가는?\n\n풀이 패턴 높이 = 46 - 40 = $6 → 목표 = 46 + 6 = $52."]]}]}]}]},{"t":"Ⅲ 지속 패턴과 수렴 패턴","c":[{"t":"1. 삼각형 (Triangles)","c":[{"t":"(1) 삼각형의 종류","c":[{"t":"① 대칭 삼각형: 방향 중립","n":[["설명","대칭 삼각형(Symmetrical): 고점은 낮아지고 저점은 높아지며 수렴한다. 방향 중립적이며 대개 기존 추세 방향으로 돌파하는 지속 패턴으로 분류된다."]]},{"t":"② 상승 삼각형: 강세 성향","n":[["설명","상승 삼각형(Ascending): 수평 저항선 + 상승하는 지지선. 매수세가 점점 높은 가격에서 들어오므로 강세 성향이며 상향 돌파가 많다."]]},{"t":"③ 하락 삼각형: 약세 성향","n":[["설명","하락 삼각형(Descending): 수평 지지선 + 하락하는 저항선. 약세 성향이며 하향 이탈이 많다."]]}]},{"t":"(2) 삼각형의 특징","c":[{"t":"① 형성 중 거래량 감소","n":[["설명","거래량은 패턴 형성 중 감소하다가 돌파 시 증가하는 것이 전형적이다."]]},{"t":"② 2/3~3/4 지점 돌파","n":[["설명","돌파는 삼각형 길이(시작~꼭짓점)의 약 2/3~3/4 지점에서 일어나는 것이 좋다. 꼭짓점(Apex) 가까이 가면 돌파의 힘이 약해진다."]]},{"t":"③ 목표=가장 넓은 높이","n":[["설명","목표 = 돌파 가격 ± 삼각형의 가장 넓은 부분의 높이. 또는 첫 고점에서 추세선과 평행한 선을 그어 목표로 삼는다."]]}]}]},{"t":"2. 쐐기 (Wedges)","c":[{"t":"(1) 상승 쐐기 (Rising Wedge)","c":[{"t":"① 위로 수렴하는 쐐기","n":[["설명","두 추세선이 모두 위로 기울어 있으나 아래선이 더 가팔라 위로 수렴하는 패턴이다."]]},{"t":"② 약세(하향 이탈) 성향","n":[["설명","가격은 오르지만 상승 폭이 점점 줄어드는 형태로, 일반적으로 약세(하향 이탈) 성향이다."]]}]},{"t":"(2) 하락 쐐기 (Falling Wedge)","c":[{"t":"① 아래로 수렴하는 쐐기","n":[["설명","두 추세선이 모두 아래로 기울며 아래로 수렴하는 패턴이다."]]},{"t":"② 강세(상향 돌파) 성향","n":[["설명","하락 속도가 점점 둔화되는 형태로, 일반적으로 강세(상향 돌파) 성향이다."]]},{"t":"③ 삼각형과 쐐기의 차이","n":[["설명","삼각형과의 차이: 삼각형은 두 선의 기울기 방향이 반대이거나 한쪽이 수평이지만, 쐐기는 두 선이 같은 방향으로 기운다."]]}]}]},{"t":"3. 깃발과 페넌트 (Flags & Pennants)","c":[{"t":"(1) 구조","c":[{"t":"① 급격한 깃대 선행","n":[["설명","깃대(Flagpole): 거의 수직에 가까운 급격한 가격 움직임이 선행한다. 깃발·페넌트는 깃대 뒤의 짧은 휴식(보합) 구간이다."]]},{"t":"② 깃발: 역방향 평행사변형","n":[["설명","깃발(Flag): 추세와 반대 방향으로 약간 기운 작은 평행사변형(채널) 모양이다."]]},{"t":"③ 페넌트: 작은 대칭 삼각형","n":[["설명","페넌트(Pennant): 작은 대칭 삼각형 모양이다."]]}]},{"t":"(2) 특징과 목표","c":[{"t":"① 짧은 형성 기간(3주 이내)","n":[["설명","형성 기간이 짧다(보통 3주 이내, 일간 차트 기준). 형성 중 거래량이 감소하고 돌파 시 증가한다."]]},{"t":"② 깃발은 중간에 휘날린다","n":[["설명","\"깃발은 깃대의 중간에 휘날린다(Flags fly at half-mast)\": 목표 = 돌파 지점 + 깃대 길이. 즉 깃발이 전체 움직임의 중간쯤에 위치한다."]]},{"t":"③ 스캘핑: 불 플래그 셋업","n":[["설명","스캘핑 적용: 급등 종목의 1분·5분 차트에서 거래량이 줄며 좁게 눌리는 '불 플래그'는 대표적인 지속 셋업이다. 단, 깃발 하단 이탈은 무효화 신호이다."],["표","패턴 | 분류 | 핵심 식별 포인트 | 목표 산출\n헤드앤숄더 | 반전(천장) | 머리가 가장 높고 목선 이탈로 완성 | 목선 - 머리~목선 거리\n이중 바닥 | 반전(바닥) | 두 저점 + 확인선 돌파 | 확인선 + 패턴 높이\n직사각형 | 반전/지속 | 수평 지지·저항 다수 접촉 | 돌파가 ± 높이\n상승 삼각형 | 지속(강세 성향) | 수평 저항 + 상승 지지 | 돌파가 + 최대 높이\n상승 쐐기 | 반전/지속(약세 성향) | 두 선 모두 상승·수렴 | 직전 쐐기 시작점 부근\n깃발·페넌트 | 지속 | 깃대 + 짧은 보합, 거래량 감소 | 돌파가 + 깃대 길이"],["쉬운 예","깃발은 전력 질주(깃대)한 선수가 잠깐 숨을 고르는 구간이다. 숨 고르는 동안 조용하다가(거래량 감소) 다시 같은 방향으로 뛴다. 쐐기와 삼각형 구분법: 두 선이 같은 방향으로 기울면 쐐기, 반대 방향이거나 한쪽이 수평이면 삼각형이다."],["문제 연습","깃대가 $10 → $14로 형성된 뒤 $13.20~$13.60 사이 깃발을 만들고 $13.60을 상향 돌파했다. 목표가는?\n\n풀이 깃대 길이 $4 → 13.60 + 4 = $17.60."]]}]}]}]},{"t":"Ⅳ 단기 패턴 (Short-Term Patterns)","c":[{"t":"1. 갭 (Gaps)","c":[{"t":"(1) 갭의 정의","c":[{"t":"① 갭=가격 공백","n":[["설명","갭은 전일 고가보다 오늘 저가가 높거나(상승 갭), 전일 저가보다 오늘 고가가 낮을 때(하락 갭) 생기는 가격 공백이다."]]},{"t":"② 장중 메워지면 갭 아님","n":[["설명","시가만 벌어졌다가 장중에 메워진 것은 엄밀한 의미의 갭(바 차트상 공백)이 아니다. 캔들 분석에서는 몸통 사이의 공백을 '창(Window)'이라 부른다."]]}]},{"t":"(2) 갭의 네 가지 유형","c":[{"t":"① 보통 갭: 곧 메워짐","n":[["설명","보통 갭(Common Gap): 거래가 한산한 횡보 구간에서 나타나며 곧 메워진다. 의미가 가장 적다."]]},{"t":"② 돌파 갭: 새 추세 시작","n":[["설명","돌파 갭(Breakaway Gap): 패턴·지지저항을 돌파하며 새 추세의 시작을 알린다. 대개 대량 거래를 동반하며 잘 메워 지지 않는다."]]},{"t":"③ 진행·측정 갭: 추세 중간","n":[["설명","진행 갭·측정 갭(Runaway/Measuring Gap): 추세 중간에 나타나 추세의 지속·가속을 보여준다. 갭이 전체 움직임의 중간 지점에 위치하는 경향이 있어 목표 측정에 쓰인다."]]},{"t":"④ 소멸 갭: 추세 종료 경고","n":[["설명","소멸 갭(Exhaustion Gap): 추세 말기에 마지막 투매·과열로 나타나며 곧 메워진다. 추세 종료의 경고이다."]]}]},{"t":"(3) 섬꼴 반전 (Island Reversal)","c":[{"t":"① 양쪽 갭으로 고립된 섬","n":[["설명","한 방향의 갭(소멸 갭) 이후 며칠간 거래되다가 반대 방향의 갭(돌파 갭)이 나타나 가격 덩어리가 '섬'처럼 고립되는 반전 패턴이다."]]},{"t":"② 같은 가격대 두 갭, 강한 반전","n":[["설명","두 갭은 대략 같은 가격대에서 발생한다. 강한 반전 신호로 해석된다."]]}]}]},{"t":"2. 반전일 패턴 (Reversal Bars)","c":[{"t":"(1) 1일 반전 패턴","c":[{"t":"① 키 리버설","n":[["설명","키 리버설(Key Reversal Day): 상승 추세 중 신고가를 기록했다가 전일 종가 아래에서 마감하는 날(천장 반전), 또는 하락 추세 중 신저가 후 전일 종가 위에서 마감하는 날(바닥 반전)이다."]]},{"t":"② 아웃사이드 리버설","n":[["설명","아웃사이드 리버설(Outside Reversal): 당일 범위가 전일 범위를 완전히 감싸고(고가↑·저가↓), 종가가 반대 방향으로 마감한다. 장악형 캔들과 유사하다."]]},{"t":"③ 셀링 클라이맥스","n":[["설명","셀링 클라이맥스(Selling Climax): 하락 추세 끝에서 대량 거래와 함께 급락 후 강하게 반등하는 날이다. 공황 매도의 소진을 뜻한다. 반대로 상승 끝의 급등·대량거래는 바잉 클라이맥스(Buying Climax)이다."]]},{"t":"④ 스파이크(Spike)","n":[["설명","스파이크(Spike): 전후 봉보다 월등히 높거나 낮은 고가·저가를 만든 봉으로, 극단적 반응 뒤 반전을 시사한다."]]}]},{"t":"(2) 2일 반전 패턴","c":[{"t":"① 파이프(Pipe)","n":[["설명","파이프(Pipe): 비슷한 길이의 긴 봉 두 개가 나란히 극단적 저점(또는 고점)을 만드는 패턴으로 반전을 시사한다."]]},{"t":"② 혼(Horn)","n":[["설명","혼(Horn): 두 개의 긴 봉 사이에 짧은 봉이 끼어 있는 구조로 파이프와 유사한 반전 패턴이다."]]},{"t":"③ 훅 리버설","n":[["설명","훅 리버설(Hook Reversal): 상승 추세에서 시가가 전일 고가 위에서 시작했으나 종가는 전일 종가 아래로 마감하고, 당일 범위는 전일보다 좁은 반전일이다(하락 추세는 반대)."]]}]}]},{"t":"3. 범위 기반 패턴 (Range Patterns)","c":[{"t":"(1) 인사이드·아웃사이드 봉","c":[{"t":"① 인사이드 바: 변동성 수축","n":[["설명","인사이드 바(Inside Bar/Inside Day): 고가가 전일보다 낮고 저가가 전일보다 높아 전일 범위 안에 포함된 봉이다. 변동성 수축과 우유부단을 의미하며, 이후 돌파 방향이 중요하다."]]},{"t":"② 아웃사이드 바: 변동성 확장","n":[["설명","아웃사이드 바(Outside Bar): 고가가 전일보다 높고 저가가 전일보다 낮아 전일 범위를 감싼 봉이다. 변동성 확장을 뜻하며, 종가 위치로 방향을 판단한다."]]}]},{"t":"(2) 좁은 범위와 넓은 범위","c":[{"t":"① NR4·NR7","n":[["설명","NR4·NR7(Narrow Range): 최근 4일(7일) 중 범위가 가장 좁은 날이다. 변동성 수축 후 확장의 원리에 따라 큰 움직임의 전조가 된다. 토비 크라벨(Toby Crabel)이 연구하였다."]]},{"t":"② 와이드 레인지 바","n":[["설명","와이드 레인지 바(Wide-Range Bar): 평균보다 범위가 매우 넓은 봉으로 변동성 확장과 강한 방향성(돌파·클라이맥스)을 나타낸다."]]},{"t":"③ 변동성 수축·확장 순환","n":[["설명","변동성의 순환: 수축(좁은 범위) → 확장(넓은 범위) → 수축이 반복된다. 스캘핑에서는 장 초반 변동성 확장 후 점심 전후 수축이 전형적이다."]]}]},{"t":"(3) 기타 단기 패턴","c":[{"t":"① 웁스(Oops) 패턴","n":[["설명","웁스(Oops) 패턴: 래리 윌리엄스가 제시. 전일 저가 아래로 갭 하락 출발 후 가격이 전일 저가를 회복하면 매수하는 패턴이다(갭 실패의 역이용)."]]},{"t":"② 불 플래그·미니 플래그","n":[["설명","불 플래그·미니 플래그 등 짧은 지속형 패턴도 단기 차트에 흔하다."],["쉬운 예","갭 4종은 여행으로 기억한다. 보통 갭 = 동네 산책(별 의미 없음), 돌파 갭 = 출발, 진행(측정) 갭 = 고속도로 중간 휴게소(여정의 절반), 소멸 갭 = 도착 직전 마지막 질주."],["문제 연습","전일 고가 $10.00·저가 $9.50, 오늘 고가 $10.80·저가 $10.20이다. (가) 갭이 생겼는가? (나) 오늘은 인사이드 바인가?\n\n풀이 (가) 오늘 저가 $10.20 > 전일 고가 $10.00이므로 상승 갭($10.00~$10.20). (나) 오늘 범위가 전일 범위 안에 있지 않으므로 인사이드 바가 아니다."],["주차 핵심 요약","강세·약세 명칭은 '이탈 방향'. 스로백 = 상향 돌파 후 되돌림, 풀백 = 하향 이탈 후 되돌림. 함정 = 실패\n+ 반대편 돌파.\n헤드앤숄더: 목선 이탈로 완성, 거래량 왼쪽 어깨 > 머리 > 오른쪽 어깨, 목표 = 머리~목선 거리.\n상승 쐐기 = 약세 성향, 하락 쐐기 = 강세 성향. 깃발은 깃대의 중간에서 휘날린다.\n갭 4종: 보통·돌파·진행(측정)·소멸. 섬꼴 반전, 키 리버설, 인사이드/아웃사이드, NR7."]]}]}]}]}],"b":5},{"n":6,"t":"기술적 지표: 모멘텀·오실레이터, 거래량, 시장폭","c":[{"t":"Ⅰ 지표의 기본 개념","c":[{"t":"1. 지표의 분류","c":[{"t":"(1) 사용하는 데이터에 따른 분류","c":[{"t":"① 가격 지표","n":[["이번 주 학습목표","① 모멘텀·ROC·RSI·스토캐스틱·MACD의 계산 원리와 해석(과매수·과매도, 다이버전스, 중심선 교차) 을 설명할 수 있다.\n② 가격-거래량 관계표와 미결제약정 해석표를 암기하고 적용할 수 있다.\n③ OBV, 누적/분배선, VWAP, 가격대별 거래량 등 거래량 지표를 구별할 수 있다.\n④ 등락주선, 맥클렐런 오실레이터, TRIN 등 시장폭 지표로 시장 내부 강도를 판단할 수 있다."],["설명","가격 지표: 가격만 사용한다(이동평균, RSI, MACD, 스토캐스틱 등)."]]},{"t":"② 거래량 지표","n":[["설명","거래량 지표: 가격과 거래량을 함께 사용한다(OBV, MFI, VWAP 등)."]]},{"t":"③ 시장폭(Breadth) 지표","n":[["설명","시장폭(Breadth) 지표: 지수 구성 종목 전체의 상승·하락 종목 수 등 시장 내부 데이터를 사용한다."]]},{"t":"④ 심리(Sentiment) 지표","n":[["설명","심리(Sentiment) 지표: 설문, 옵션, 공매도 데이터 등을 사용한다(제2주차)."]]}]},{"t":"(2) 형태에 따른 분류","c":[{"t":"① 추세 추종형: 후행","n":[["설명","추세 추종형(Trend-following): 이동평균, MACD 등. 추세장에서 효과적이며 후행한다."]]},{"t":"② 오실레이터: 횡보장 유효","n":[["설명","오실레이터(Oscillator): 일정 범위(예: 0~100) 또는 중심선(0) 주위를 오르내린다. 횡보장에서 과매수·과매도 판단에 효과적이다."]]},{"t":"③ 유계·무계 오실레이터","n":[["설명","유계(Bounded) 오실레이터: RSI, 스토캐스틱처럼 상·하한이 있다. 무계(Unbounded) 오실레이터: 모멘텀, ROC, MACD처럼 상·하한이 없다."]]}]}]},{"t":"2. 오실레이터의 공통 해석법","c":[{"t":"(1) 과매수·과매도 (OB/OS)","c":[{"t":"① 극단값=단기 과열","n":[["설명","오실레이터가 극단값(예: RSI 70 이상 / 30 이하)에 도달하면 가격이 단기적으로 지나치게 움직였다고 본다."]]},{"t":"② 강한 추세엔 과매수 지속","n":[["설명","강한 추세에서는 과매수(과매도) 상태가 오래 지속될 수 있다. \"RSI 70 = 매도\"가 아니다. 과매수는 '강세'의 증거일 수 있다."]]},{"t":"③ 극단값 이탈 시 신호","n":[["설명","극단값에서 빠져나올 때(예: 70 위에서 70 아래로 하락) 신호로 쓰는 것이 더 안전하다."]]}]},{"t":"(2) 다이버전스 (Divergenc e)","c":[{"t":"① 약세 다이버전스","n":[["설명","약세(음의) 다이버전스: 가격은 신고점을 만들었지만 지표는 이전 고점보다 낮은 고점을 만든다. 상승 모멘텀 약화의 경고이다."]]},{"t":"② 강세 다이버전스","n":[["설명","강세(양의) 다이버전스: 가격은 신저점을 만들었지만 지표는 이전 저점보다 높은 저점을 만든다. 하락 모멘텀 약화의 경고이다."]]},{"t":"③ 다이버전스는 경고일 뿐","n":[["설명","다이버전스는 '경고'이지 즉각적 반전 신호가 아니다. 가격 확인(추세선 이탈 등)이 필요하며, 강한 추세에서는 다이버전스가 여러 번 연속 실패할 수 있다."]]},{"t":"④ 역(히든) 다이버전스","n":[["설명","역다이버전스(Reverse/Hidden Divergence): 가격은 더 높은 저점, 지표는 더 낮은 저점을 만드는 경우로, 추세 지속 신호로 해석하는 견해가 있다."]]}]},{"t":"(3) 중심선 교차와 실패 스윙","c":[{"t":"① 중심선 교차=모멘텀 전환","n":[["설명","중심선(0선 또는 50선) 교차: 모멘텀의 방향 전환을 나타낸다. 0선 위는 상승 모멘텀, 아래는 하락 모멘텀이다."]]},{"t":"② 실패 스윙(와일더)","n":[["쉬운 예","과매수는 자동차 엔진의 RPM이 레드존에 들어간 상태와 같다. 고속도로에서는 한동안 그 상태로 달릴 수 있다. '레드존 = 즉시 정지'가 아니듯 'RSI 70 = 즉시 매도'가 아니다."],["실전 사례","스캘퍼의 실전 노트 — 급등주 1분봉에서 RSI가 85~90에 수십 분 머무르는 일은 흔하다. 과매수만 보고 공 매도하면 손실이 커진다. 약세 다이버전스가 나온 뒤 VWAP 이탈 같은 가격 확인이 있을 때만 반대 방향을 검토한다."],["설명","실패 스윙(Failure Swing): 와일더가 RSI에서 강조한 신호로, 가격이 아니라 지표 자체의 고점·저점 구조가 깨지는 것이다(Ⅱ.2에서 상술)."]]}]}]}]},{"t":"Ⅱ 주요 모멘텀 지표","c":[{"t":"1. 모멘텀과 변화율","c":[{"t":"(1) 모멘텀 (Momentum)","c":[{"t":"① 모멘텀=오늘-n일 전 종가","n":[["설명","모멘텀 = 오늘 종가 - n일 전 종가. 가격 변화의 '속도'를 측정한다."]]},{"t":"② 속도 감소→모멘텀 선행","n":[["설명","가격이 계속 올라도 상승 속도가 줄면 모멘텀은 하락한다. 모멘텀은 가격보다 먼저 고점을 형성하는 경향이 있어 선행성을 가진다."]]}]},{"t":"(2) 변화율 (Rate of Change, ROC)","c":[{"t":"① ROC 공식","n":[["설명","ROC = (오늘 종가 - n일 전 종가) ÷ n일 전 종가 × 100."]]},{"t":"② ROC 계산 예: 20%","n":[["설명","예: n일 전 $10, 오늘 $12 → ROC = (12 - 10) ÷ 10 × 100 = 20%."]]},{"t":"③ 비율로 종목 간 비교","n":[["설명","비율로 표시하므로 가격 수준이 다른 종목 간 비교가 가능하다. 0선 위는 n일 전보다 높은 가격이다."]]}]}]},{"t":"2. 상대강도지수 (RSI)","c":[{"t":"(1) 계산","c":[{"t":"① 와일더(1978), 기본 14일","n":[["설명","J. 웰스 와일더(1978)가 『New Concepts in Technical Trading Systems』에서 발표하였다. 기본 기간은 14일이다."]]},{"t":"② RSI=100-100÷(1+RS)","n":[["설명","RSI = 100 - 100 ÷ (1 + RS), RS = n일 평균 상승폭 ÷ n일 평균 하락폭."]]},{"t":"③ RSI 계산 예: 66.7","n":[["설명","예: 평균 상승 2, 평균 하락 1 → RS = 2 → RSI = 100 - 100 ÷ 3 ≈ 66.7. RS가 1이면 RSI = 50이다."]]},{"t":"④ 와일더 평활법","n":[["설명","와일더는 평균 계산에 자신만의 평활법(Wilder's smoothing, 1/n 가중의 지수평활)을 사용하였다."]]}]},{"t":"(2) 해석","c":[{"t":"① 70/30 기준·범위 이동","n":[["설명","70 이상 과매수, 30 이하 과매도가 기본이다. 강세장에서는 40~80, 약세장에서는 20~60 범위로 움직이는 경향이 있어 범위 이동(Range Shift) 자체가 추세 판단 도구가 된다."]]},{"t":"② RSI 실패 스윙","n":[["설명","실패 스윙(천장): RSI가 70 위 고점 → 하락 → 반등하나 직전 고점을 못 넘음 → 직전 저점 하향 이탈 시 매도 신호이다. 바닥은 반대이다."]]},{"t":"③ RSI에 추세선 적용","n":[["설명","RSI에 추세선, 지지·저항, 패턴을 적용할 수도 있으며, RSI 추세선 이탈이 가격보다 먼저 나타나는 경우가 많다."]]},{"t":"④ RSI≠상대강도(RS)","n":[["설명","주의: RSI(상대강도지수)는 한 종목 자체의 상승·하락폭 비교이다. 두 자산을 비교하는 '상대강도(Relative Strength, RS 비율)'와는 전혀 다른 개념이다(제10주차)."]]}]}]},{"t":"3. 스토캐스틱과 윌리엄스 %R","c":[{"t":"(1) 스토캐스틱 (Stochasti c Oscillator)","c":[{"t":"① 조지 레인, 종가 위치 측정","n":[["설명","조지 레인(George Lane)이 개발하였다. 종가가 최근 n일 범위의 어디에 위치하는지를 측정한다. 상승 추세에서는 종가가 범위 상단 근처에서 마감하는 경향이 있다는 원리이다."]]},{"t":"② %K·%D 공식","n":[["설명","%K = (오늘 종가 - n일 최저가) ÷ (n일 최고가 - n일 최저가) × 100. %D = %K의 3일 이동평균이다."]]},{"t":"③ %K 계산 예: 80","n":[["설명","예: 14일 최저 $5, 최고 $10, 종가 $9 → %K = (9 - 5) ÷ (10 - 5) × 100 = 80."]]},{"t":"④ 패스트·슬로우 스토캐스틱","n":[["설명","패스트 스토캐스틱은 원 %K와 %D, 슬로우 스토캐스틱은 패스트 %D를 슬로우 %K로 사용하고 이를 다시 3일 평균하여 슬로우 %D로 만든다."]]}]},{"t":"(2) 해석과 윌리엄스 %R","c":[{"t":"① 80/20 기준, %K·%D 교차","n":[["설명","80 이상 과매수, 20 이하 과매도이다. %K가 %D를 상향 교차하면 매수, 하향 교차하면 매도 신호이며 극단 영역에서의 교차가 더 의미 있다."]]},{"t":"② 윌리엄스 %R","n":[["설명","윌리엄스 %R = (n일 최고가 - 종가) ÷ (n일 최고가 - n일 최저가) × (-100). 0~-100 범위이며 -20 위가 과매수, -80 아래가 과매도이다. 스토캐스틱을 뒤집은 형태이다."]]}]}]},{"t":"4. MACD와 기타 지표","c":[{"t":"(1) MACD","c":[{"t":"① 아펠: 12EMA-26EMA","n":[["설명","제럴드 아펠(Gerald Appel)이 개발하였다. MACD선 = 12일 EMA - 26일 EMA."]]},{"t":"② 신호선=9EMA, 히스토그램","n":[["설명","신호선(Signal Line) = MACD선의 9일 EMA. 히스토그램 = MACD선 - 신호선."]]},{"t":"③ MACD 세 가지 신호","n":[["설명","신호: MACD선의 신호선 교차(매매 신호), 0선 교차(단기 EMA가 장기 EMA를 교차한 것과 같음), 가격과의 다이버전스."]]},{"t":"④ 히스토그램=가속·감속","n":[["설명","히스토그램은 MACD선과 신호선 간격의 변화, 즉 모멘텀의 '가속·감속'을 보여주며 교차보다 먼저 방향을 바꾼다."]]}]},{"t":"(2) 기타 모멘텀·추세 지표","c":[{"t":"① CCI(램버트)","n":[["설명","CCI(Commodity Channel Index, 도널드 램버트): 가격이 통계적 평균에서 얼마나 벗어났는지를 평균편차로 측정한다. ±100이 기준선이다."]]},{"t":"② ADX/DMI: 추세 강도","n":[["설명","ADX/DMI(와일더): +DI와 -DI로 방향을, ADX로 추세의 '강도'를 측정한다. ADX는 방향과 무관하며 상승(보통 25이상)하면 추세가 강하고, 낮으면(20 이하) 추세가 약한 횡보 상태이다."]]},{"t":"③ 다중공선성 회피","n":[["표","지표 | 개발자 | 기본 설정 | 핵심 신호\nRSI | 와일더 | 14일, 70/30 | 과매수·과매도, 실패 스윙, 다이버전스\n스토캐스틱 | 조지 레인 | 14,3, 80/20 | %K·%D 교차, 다이버전스\nMACD | 제럴드 아펠 | 12,26,9 | 신호선·0선 교차, 히스토그램\nROC | - | n일 | 0선 교차, 다이버전스\nADX | 와일더 | 14일 | 추세 강도(방향 무관)\nCCI | 도널드 램버트 | 20일, ±100 | 평균 이탈 정도"],["쉬운 예","MACD는 빠른 차(12일 EMA)와 느린 차(26일 EMA) 사이의 거리다. 거리가 벌어지면 가속, 좁혀지면 감속이다. 히스토그램은 그 거리가 '벌어지는 속도'라서 교차보다 먼저 방향을 바꾼다."],["문제 연습","(가) 14일 평균 상승폭 1.5, 평균 하락폭 0.5일 때 RSI는? (나) 14일 최고가 $30, 최저가 $20, 종가 $22일 때 스토캐스틱 %K와 윌리엄스 %R은?\n\n풀이 (가) RS = 3 → RSI = 100 - 100 ÷ 4 = 75. (나) %K = (22 - 20) ÷ 10 × 100 = 20, %R = (30 - 22) ÷ 10 × (-100) = -80 → 둘 다 과매도 경계선이다."],["설명","지표 선택의 원칙: 같은 정보를 쓰는 지표를 여러 개 겹쳐 쓰면 '다중공선성(Multicollinearity)' 문제가 생긴다. 추세·모멘텀·거래량·변동성처럼 서로 다른 정보를 결합해야 한다."]]}]}]}]},{"t":"Ⅲ 거래량 분석 (Volume Analysis)","c":[{"t":"1. 가격과 거래량의 관계","c":[{"t":"(1) 거래량의 의미","c":[{"t":"① 거래량=확신의 크기","n":[["설명","거래량은 가격 움직임 뒤에 있는 '확신(Conviction)'의 크기를 보여준다. 극단적으로 높은 거래량은 시장이 크게 움직일 준비가 되었다는 가장 분명한 신호이다."]]},{"t":"② 형성 중 감소, 돌파 시 급증","n":[["표","가격 | 거래량 | 해석 | 시사점\n상승 | 증가 | 수요 증가(Strong demand) | 강세\n상승 | 감소 | 수요 감소(Weak demand) | 약세(경고)\n하락 | 증가 | 공급 증가(Strong supply) | 약세\n하락 | 감소 | 공급 감소(Weak supply) | 강세(바닥 접근)"],["설명","패턴 형성 중에는 균형 상태로 거래량이 줄고, 돌파 시 거래량이 급증하는 것이 전형적이다."]]}]},{"t":"(2) 가격-거래량 관계표","c":[{"t":"① 거래량 증가=추세 확인","n":[["설명","핵심 원리: 거래량 증가는 현재 가격 방향(추세)을 확인한다. 거래량 감소는 현재 방향의 힘이 약해졌음을 뜻한다."]]},{"t":"② 급등 후 거래량 급감 경고","n":[["설명","급등일 다음날 거래량이 급감하면 추가 매수세가 이어지지 않아 움직임이 지속되기 어렵다는 경고이다."]]}]}]},{"t":"2. 주요 거래량 지표","c":[{"t":"(1) OBV와 누적/분배선","c":[{"t":"① OBV(그랜빌)","n":[["설명","OBV(On-Balance Volume, 조셉 그랜빌): 종가가 전일보다 오르면 당일 거래량을 더하고, 내리면 빼서 누적한다. 절대값보다 추세와 다이버전스가 중요하다."]]},{"t":"② 누적/분배선(체이킨)","n":[["설명","누적/분배선(Accumulation/Distribution Line, 마크 체이킨): 종가가 당일 범위 어디에 있는지(CLV = [(종가-저가) - (고가-종가)] ÷ (고가-저가))에 거래량을 곱해 누적한다. OBV보다 장중 위치를 반영한다."]]},{"t":"③ 체이킨 머니플로(CMF)","n":[["설명","체이킨 머니플로(CMF): 일정 기간 CLV×거래량 합계를 거래량 합계로 나눈 값으로 매수·매도 압력을 측정한다."]]}]},{"t":"(2) VWAP (거래량가중평균가격)","c":[{"t":"① VWAP 공식","n":[["설명","VWAP = Σ(가격 × 거래량) ÷ Σ거래량. 해당 기간 동안 체결된 모든 거래의 거래량 가중 평균가격이다."]]},{"t":"② 기관 체결 벤치마크","n":[["설명","기관은 대량 주문의 체결 품질 평가 기준(Benchmark)으로 VWAP을 사용한다. 교재는 VWAP을 지표라기보다 '통계'에 가깝다고 설명한다."]]},{"t":"③ 스캘핑: 장중 지지·저항","n":[["설명","스캘핑 적용: 가격이 VWAP 위에 있으면 당일 매수자가 평균적으로 이익 상태이다. VWAP은 장중 동적 지지·저항과 추세 판단 기준으로 쓰인다."]]}]},{"t":"(3) 기타 거래량 도구","c":[{"t":"① 가격대별 거래량(Profile)","n":[["설명","가격대별 거래량(Volume at Price/Volume Profile): 가격 수준별 누적 거래량을 가로 막대로 표시한다. 거래량이 가장 많은 가격을 POC(Point of Control)라 하며 강한 지지·저항이 된다."]]},{"t":"② 머니플로 지수(MFI)","n":[["설명","머니플로 지수(MFI): 전형가격(고가+저가+종가 ÷ 3) × 거래량을 이용한 '거래량 가중 RSI'이다. 80/20을 과매수·과매도 기준으로 쓴다."]]},{"t":"③ 상대거래량(RVOL)","n":[["설명","거래량 오실레이터, 상대거래량(Relative Volume): 현재 거래량을 평균 거래량과 비교한다. 소형주 스캘핑에서 상대거래량은 관심 집중도의 핵심 척도이다."]]}]}]},{"t":"3. 미결제약정 (Open Interest)","c":[{"t":"(1) 개념","c":[{"t":"① 미청산 계약 수","n":[["설명","미결제약정은 선물·옵션에서 아직 청산되지 않은(반대매매나 인수도가 이루어지지 않은) 계약 수이다."]]},{"t":"② 증감 원리","n":[["표","가격 | 미결제약정 | 해석 | 시사점\n상승 | 증가 | 신규 매수 유입 | 강세(추세 확인)\n상승 | 감소 | 공매도 환매(숏커버링) | 약세 경고(상승의 질 낮음)\n하락 | 증가 | 신규 매도 유입 | 약세(추세 확인)\n하락 | 감소 | 매수 포지션 청산 | 강세 경고(하락의 질 낮음)"],["설명","신규 매수자와 신규 매도자가 거래하면 1계약 증가, 기존 매수자와 기존 매도자가 청산하면 1계약 감소, 한쪽은 신규·한쪽은 청산이면 변동이 없다."]]}]},{"t":"(2) 해석표","c":[{"t":"① 증가=추세 확인, 감소=약화","n":[["설명","미결제약정 증가는 새로운 자금 유입으로 현재 추세를 확인한다. 미결제약정 감소는 기존 포지션 청산으로 추세의 힘이 약해졌음을 뜻한다."]]},{"t":"② 급등+감소=숏커버링","n":[["쉬운 예","거래량은 공연장의 박수 소리다. 노래(가격)가 절정으로 갈수록 박수가 커지면 관객이 진짜 호응하는 것이고, 노래는 커지는데 박수가 줄면 관객이 떠나고 있다는 뜻이다."],["문제 연습","장 초반 체결이 $10에 100주, $11에 300주, $12에 100주였다. VWAP은?\n\n풀이 (10×100 + 11×300 + 12×100) ÷ 500 = 5,500 ÷ 500 = $11. 현재가가 $11 위면 당일 매수자는 평균적으로 이익 상태이다."],["설명","가격 급등 + 미결제약정 감소(숏커버링)는 신규 매수세가 아닌 환매수에 의한 상승이므로 지속성이 약할 수 있다."]]}]}]}]},{"t":"Ⅳ 시장폭 분석 (Market Breadth)","c":[{"t":"1. 시장폭의 개념","c":[{"t":"(1) 정의와 목적","c":[{"t":"① 종목 전체의 참여도","n":[["설명","시장폭은 지수를 구성하는 종목 '전체'가 얼마나 넓게 상승(하락)에 참여하는지를 측정한다. 시가총액 가중 지수는 소수의 대형주에 의해 왜곡될 수 있기 때문이다."]]},{"t":"② 지수 신고점+폭 축소=경고","n":[["설명","건강한 상승장은 다수 종목이 동참한다. 지수는 신고점인데 상승 종목 수가 계속 줄어드는 것은 약세 다이버전스로, 강세장 말기의 경고 신호이다(샤바커 규칙과 연결)."]]}]},{"t":"(2) 기본 데이터","c":[{"t":"① 상승·하락 종목 수·거래량","n":[["설명","상승 종목 수(Advances)와 하락 종목 수(Declines), 상승 종목 거래량(Up Volume)과 하락 종목 거래량(Down Volume)."]]},{"t":"② 신고가·신저가 종목 수","n":[["설명","신고가 종목 수(New Highs)와 신저가 종목 수(New Lows), 이동평균 위에 있는 종목 비율 등이 있다."]]}]}]},{"t":"2. 주요 시장폭 지표","c":[{"t":"(1) 등락주선과 등락비율","c":[{"t":"① 등락주선(A-D Line)","n":[["설명","등락주선(Advance-Decline Line): (상승 종목 수 - 하락 종목 수)를 매일 누적한 선이다. 지수와의 다이버전스를 본다. 절대 수준보다 방향이 중요하다."]]},{"t":"② 등락비율(A/D Ratio)","n":[["설명","등락비율(A/D Ratio): 상승 종목 수 ÷ 하락 종목 수. 단기 과매수·과매도 판단에 쓴다."]]}]},{"t":"(2) 맥클렐런 오실레이터와 합산지수","c":[{"t":"① 맥클렐런 오실레이터","n":[["설명","맥클렐런 오실레이터(McClellan Oscillator) = (상승-하락 종목 수)의 19일 EMA - 39일 EMA. MACD를 시장폭 데이터에 적용한 것과 같다."]]},{"t":"② 맥클렐런 합산지수","n":[["설명","맥클렐런 합산지수(Summation Index): 맥클렐런 오실레이터 값을 누적한 것으로 중장기 시장폭 추세를 보여준다."]]}]},{"t":"(3) ARMS 지수 (TRIN)","c":[{"t":"① TRIN 공식(리처드 암스)","n":[["설명","TRIN = (상승 종목 수 ÷ 하락 종목 수) ÷ (상승 거래량 ÷ 하락 거래량). 리처드 암스가 개발하였다."]]},{"t":"② 1 미만 강세·1 초과 약세","n":[["설명","1보다 작으면 상승 종목에 거래량이 상대적으로 많이 몰린 강세, 1보다 크면 하락 종목에 거래량이 몰린 약세이다. 즉 가격과 반대로 움직이는 역지표 형태이다."]]},{"t":"③ TRIN 계산 예: 0.67","n":[["설명","예: 상승 2,000, 하락 1,000, 상승 거래량 1.5억, 하락 거래량 0.5억 → TRIN = 2 ÷ 3 ≈ 0.67(강세). 극단적으로 높은 TRIN(예: 2 이상)은 공황 매도로 역발상 강세 신호가 될 수 있다."]]}]},{"t":"(4) 신고가-신저가와 브레드스 스러스트","c":[{"t":"① 신고가-신저가 지수","n":[["설명","신고가-신저가 지수: 신고가 종목 수가 줄어드는 가운데 지수만 상승하면 시장 내부의 약화이다."]]},{"t":"② 브레드스 스러스트(즈바이크)","n":[["설명","브레드스 스러스트(Breadth Thrust, 마틴 즈바이크): 등락 비율의 10일 이동평균이 40% 이하에서 10거래일 이내에 61.5% 이상으로 급등하는 현상으로, 강한 새 상승장의 시작 신호로 알려져 있다."]]},{"t":"③ 200일선 위 종목 비율","n":[["쉬운 예","장군(대형주 지수)만 앞으로 달려 나가고 병사들(대부분 종목)이 따라오지 않는 군대는 오래 진격하지 못한다. 지수는 신고점인데 등락주선이 내려가는 약세 다이버전스가 바로 이 모습이다."],["문제 연습","상승 종목 1,500, 하락 종목 1,500, 상승 종목 거래량 6억 주, 하락 종목 거래량 2억 주이다. TRIN과 해석은?\n\n풀이 (1,500 ÷ 1,500) ÷ (6 ÷ 2) = 1 ÷ 3 ≈ 0.33. 1보다 매우 작으므로 거래량이 상승 종목에 몰린 강세이다."],["주차 핵심 요약","오실레이터: 과매수·과매도는 추세장에서 오래 지속될 수 있다. 다이버전스는 경고이지 신호가 아니다.RSI = 100 - 100/(1+RS), 14일, 70/30, 실패 스윙. 스토캐스틱 %K = (C - L_n)/(H_n - L_n). MACD = 12EMA -26EMA, 신호선 9EMA.\n가격↑·거래량↓ = 약한 수요(약세 경고), 가격↓·거래량↓ = 약한 공급(강세). OI↑ + 가격↑ = 신규 매수(강세).\nOBV(그랜빌), A/D(체이킨), VWAP = Σ(P×V)/ΣV, POC. 등락주선 다이버전스, TRIN < 1 강세, 맥클렐런 = 19EMA\n- 39EMA."],["설명","200일 이동평균 위 종목 비율: 장기 참여도를 측정한다. 80% 이상은 과열, 20% 이하는 과매도 극단으로 본다."]]}]}]}]}],"b":6},{"n":7,"t":"통계·확률과 변동성 분석","c":[{"t":"Ⅰ 기술통계 (Descriptive Statistics)","c":[{"t":"1. 통계의 기본 개념","c":[{"t":"(1) 모집단과 표본","c":[{"t":"① 모집단과 표본","n":[["이번 주 학습목표","① 평균(산술·기하)·중앙값·최빈값, 범위·분산·표준편차 등 기술통계량을 계산하고 해석할 수 있다.\n② 확률의 정의, 대수의 법칙, 독립·동일분포(i.i.d.), 정규·로그정규 분포, 왜도·첨도를 설명할 수 있다.\n③ 상관관계와 회귀분석, 결정계수의 의미를 이해한다.\n④ 실제범위(TR)·ATR, 역사적 변동성, 내재변동성, VIX 등 변동성 측정법을 익힌다."],["설명","모집단(Population)은 관심 대상 전체, 표본(Sample)은 그 일부이다. 기술적 분석의 백테스트는 과거 데이터라는 '표본'으로 미래(모집단)를 추정하는 작업이다."]]},{"t":"② 기술통계 vs 추론통계","n":[["설명","기술통계는 데이터의 특징을 요약·묘사하고, 추론통계는 표본으로 모집단에 대한 결론을 이끌어낸다."]]}]},{"t":"(2) 데이터 시각화","c":[{"t":"① 히스토그램(도수분포)","n":[["설명","히스토그램(도수분포): 수익률을 구간(Bin)별로 나누어 빈도를 막대로 표시한다. 평균 하나로는 보이지 않는 분포의 모양(치우침, 극단값)을 보여준다."]]},{"t":"② 이상값이 평균 왜곡","n":[["설명","평균만 보면 하나의 극단적 이익(이상값, Outlier)이 전략 전체를 좋아 보이게 만들 수 있으므로 분포를 반드시 확인해야 한다."]]}]}]},{"t":"2. 중심경향 측정","c":[{"t":"(1) 평균의 종류","c":[{"t":"① 산술평균","n":[["설명","산술평균(Arithmetic Mean): 값들의 합 ÷ 개수. 극단값의 영향을 크게 받는다."]]},{"t":"② 기하평균: 복리 수익률","n":[["설명","기하평균(Geometric Mean): 복리 수익률의 평균. [(1+r1)(1+r2)…(1+rn)]^(1/n) - 1. 여러 기간 수익률의 평균은 기하평균이 정확하다."]]},{"t":"③ ±50% 기하평균 -13.4%","n":[["설명","예: +50%, -50% → 산술평균 0%, 기하평균 = (1.5 × 0.5)^(1/2) - 1 = √0.75 - 1 ≈ -13.4%. 실제로 $100은 $75가 되었으므로 기하평균이 현실을 반영한다."]]},{"t":"④ 변동성 손실(Drag)","n":[["설명","기하평균은 항상 산술평균보다 작거나 같다(변동성이 클수록 차이가 커진다: 변동성 손실, Volatility Drag)."]]}]},{"t":"(2) 중앙값과 최빈값","c":[{"t":"① 중앙값(Median)","n":[["설명","중앙값(Median): 크기순 정렬 시 가운데 값. 극단값의 영향을 적게 받는다. 개수가 짝수면 가운데 두 값의 평균이다."]]},{"t":"② 최빈값(Mode)","n":[["설명","최빈값(Mode): 가장 자주 나타나는 값. 분포의 봉우리(Peak)이다."]]},{"t":"③ 평균·중앙값·최빈값 예","n":[["설명","예: 데이터 2, 3, 3, 5, 12 → 평균 5, 중앙값 3, 최빈값 3. 극단값 12 때문에 평균이 중앙값보다 크다(양의 왜도)."]]}]}]},{"t":"3. 산포도 측정","c":[{"t":"(1) 범위와 분산","c":[{"t":"① 범위=최댓값-최솟값","n":[["설명","범위(Range) = 최댓값 - 최솟값. 계산이 쉽지만 극단값 두 개에만 의존한다."]]},{"t":"② 분산: n 또는 n-1","n":[["설명","분산(Variance) = 각 값과 평균의 차이를 제곱해 평균한 값. 모집단 분산은 n으로, 표본 분산은 (n-1)로 나눈다."]]},{"t":"③ 제곱으로 부호 제거","n":[["설명","제곱을 하는 이유: 편차의 합은 항상 0이 되므로 부호를 없애기 위함이다. 단위도 제곱이 되어 해석이 어렵다."]]}]},{"t":"(2) 표준편차","c":[{"t":"① 표준편차=√분산","n":[["설명","표준편차(Standard Deviation, σ) = √분산. 원래 데이터와 같은 단위이므로 해석이 쉽다. 금융에서 변동성(위험) 의 표준 척도이다."]]},{"t":"② 표준편차 계산 예","n":[["설명","예: 수익률 2%, 4%, 6% → 평균 4%, 편차 -2, 0, +2, 제곱합 8, 모분산 8/3 ≈ 2.67, σ ≈ 1.63%."]]},{"t":"③ 변동계수=σ÷평균","n":[["설명","변동계수(Coefficient of Variation) = 표준편차 ÷ 평균. 단위 위험당 수익을 비교할 때 사용한다."]]}]},{"t":"(3) Z-점수","c":[{"t":"① Z=(X-μ)÷σ","n":[["설명","Z = (X - μ) ÷ σ. 어떤 값이 평균에서 표준편차 몇 개만큼 떨어져 있는지를 나타낸다."]]},{"t":"② Z-점수 예: 거래량 Z=3","n":[["쉬운 예","평범한 직장인 10명이 있는 카페에 세계 최고 부자가 들어오면 '평균 재산'은 수천억 원으로 뛰지만 '중앙값'은\n거의 변하지 않는다. 극단값이 있는 데이터(급등주 수익률 등)는 중앙값을 함께 봐야 하는 이유다."],["문제 연습","두 기간 수익률이 +20%, -10%이다. 산술평균과 기하평균은?\n\n풀이 산술평균 = (20 - 10) ÷ 2 = 5%. 기하평균 = (1.2 × 0.9)^(1/2) - 1 = √1.08 - 1 ≈ 3.92%. 기하평균이 더 작다."],["설명","예: 평균 거래량 100만, σ 20만, 오늘 거래량 160만 → Z = (160 - 100) ÷ 20 = 3. 매우 이례적인 거래량이다."]]}]}]}]},{"t":"Ⅱ 확률 (Probability)","c":[{"t":"1. 확률의 기본 개념","c":[{"t":"(1) 확률의 정의","c":[{"t":"① 확률은 0~1 사이 값","n":[["설명","확률은 사건이 일어날 가능성을 0(불가능)~1(확실) 사이 값으로 나타낸 것이다. 모든 가능한 결과의 확률 합은 1이다."]]},{"t":"② 빈도주의적 정의","n":[["설명","빈도주의적 정의: P(X) = X가 발생한 횟수 ÷ 전체 시행 횟수. 예: 과거 1,000번의 신호 중 700번 10일 뒤 상승 → 상승 확률 70%."]]},{"t":"③ 선험적·경험적·주관적","n":[["설명","확률의 종류: 선험적(A priori, 동전·주사위처럼 논리적으로 계산), 경험적(Empirical, 과거 빈도), 주관적(Subjective, 판단에 의한 확률)."]]},{"t":"④ 확률변수(X)","n":[["설명","확률변수(Random Variable, X): 무작위 현상의 결과를 수치로 나타낸 변수이다."]]}]},{"t":"(2) 대수의 법칙 (Law of Large Numbers)","c":[{"t":"① 시행 많을수록 기대 확률 수렴","n":[["설명","시행 횟수가 많아질수록 관찰된 비율이 이론적(기대) 확률에 수렴한다."]]},{"t":"② 반복 시 기대값 근접","n":[["설명","한 번의 거래는 예측 불가능하지만 같은 전략을 수백 번 반복하면 결과가 기대값에 가까워진다. 카지노가 개별 손실에도 장기적으로 이익을 내는 원리이다."]]},{"t":"③ 소표본 평가 금지","n":[["설명","따라서 적은 수의 거래 결과로 전략을 평가하면 안 된다(소표본 편향)."]]}]}]},{"t":"2. 독립성과 확률 계산","c":[{"t":"(1) 독립·종속 사건과 i.i.d.","c":[{"t":"① 독립 사건","n":[["설명","독립 사건(Independent): 이전 결과가 다음 결과의 확률에 영향을 주지 않는다. 동전을 10번 연속 앞면이 나와도 다음 앞면 확률은 50%이다. 이를 무시하는 것이 '도박사의 오류(Gambler's Fallacy)'이다."]]},{"t":"② 종속 사건","n":[["설명","종속 사건(Dependent): 주머니에서 공을 꺼내고 다시 넣지 않으면 다음 확률이 변한다."]]},{"t":"③ i.i.d. 가정","n":[["설명","i.i.d.(Independent and Identically Distributed): 각 관측치가 서로 독립이고 같은 확률분포를 따른다는 가정이다. 많은 통계 기법의 전제이지만, 주가 수익률은 변동성 군집(Volatility Clustering) 등으로 i.i.d.가 아니라는 연구가 많다."]]}]},{"t":"(2) 기본 확률 규칙","c":[{"t":"① 곱셈 법칙","n":[["설명","곱셈 법칙(독립 사건의 동시 발생): P(A and B) = P(A) × P(B). 예: 승률 60% 거래가 3번 연속 이길 확률 = 0.6³ = 21.6%."]]},{"t":"② 덧셈 법칙","n":[["설명","덧셈 법칙: P(A or B) = P(A) + P(B) - P(A and B). 상호배타적 사건이면 P(A and B) = 0이다."]]},{"t":"③ 조건부 확률","n":[["설명","조건부 확률: P(A|B) = P(A and B) ÷ P(B). \"거래량 급증(B)이 있을 때 돌파 성공(A) 확률\"처럼 조건을 걸어 확률을 개선하는 것이 신호 필터링의 본질이다."]]},{"t":"④ 5연패 확률 3.1%","n":[["설명","연패 확률 예: 승률 50% 전략에서 5연패 확률 = 0.5^5 ≈ 3.1%. 거래가 많으면 연패는 반드시 발생하므로 자금관리로 대비한다."]]}]}]},{"t":"3. 확률분포","c":[{"t":"(1) 주요 분포","c":[{"t":"① 정규분포: 종 모양","n":[["설명","정규분포(Normal/Gaussian): 평균을 중심으로 좌우 대칭인 종 모양. 평균 = 중앙값 = 최빈값이다."]]},{"t":"② 68-95-99.7 경험 법칙","n":[["설명","정규분포의 경험 법칙: 평균 ± 1σ에 약 68%, ± 2σ에 약 95%, ± 3σ에 약 99.7%의 데이터가 들어간다. 볼린저 밴드(±2σ)의 통계적 근거이다."]]},{"t":"③ 로그정규분포: 주가","n":[["설명","로그정규분포(Lognormal): 주가는 0 아래로 내려갈 수 없고(손실 한계 -100%) 상승은 무한하므로 가격 분포는 오른쪽 꼬리가 긴 로그정규분포에 가깝다."]]},{"t":"④ 균등분포","n":[["설명","균등분포(Uniform): 모든 결과의 확률이 같다(주사위 1~6)."]]}]},{"t":"(2) 분포의 네 가지 적률 (Moments)","c":[{"t":"① 네 가지 적률","n":[["설명","1차 적률 = 평균(위치), 2차 적률 = 분산·표준편차(퍼짐), 3차 적률 = 왜도(비대칭), 4차 적률 = 첨도(꼬리 두께)."]]},{"t":"② 왜도(Skewness)","n":[["설명","왜도(Skewness): 분포의 비대칭 정도. 교재식 간이 계산 = (평균 - 최빈값) ÷ 표준편차. 오른쪽 꼬리가 길면 양(+) 의 왜도(평균 > 중앙값 > 최빈값), 왼쪽 꼬리가 길면 음(-)의 왜도이다."]]},{"t":"③ 첨도(Kurtosis)","n":[["설명","첨도(Kurtosis): 꼬리(극단값)의 두께를 나타낸다. 정규분포의 첨도는 3이며, 초과첨도(Excess Kurtosis) = 첨도\n- 3이다."]]},{"t":"④ 첨첨·평첨·중첨","n":[["쉬운 예","1913년 몬테카를로 카지노의 룰렛에서 검정이 26번 연속 나왔다는 유명한 일화가 있다. '이제는 빨강 차례'라며 돈을 건 사람들이 큰 손실을 봤다. 룰렛 한 판 한 판은 독립 사건이다 — 도박사의 오류."],["문제 연습","승률 40%인 전략에서 6연패할 확률은?\n\n풀이 패배 확률 0.6 → 0.6^6 ≈ 0.0467 ≈ 4.7%. 1년에 수백 번 거래하면 6연패는 '언젠가 반드시' 겪는다고 보고 자금관리를 설계한다."],["설명","첨도 > 3: 첨첨(Leptokurtic, 뾰족하고 꼬리가 두꺼움, Fat Tails). 첨도 < 3: 평첨(Platykurtic). 첨도 = 3: 중첨(Mesokurtic). 금융 수익률은 대개 두꺼운 꼬리를 가져 정규분포 가정보다 극단 사건이 자주 일어난다."]]}]}]}]},{"t":"Ⅲ 상관관계와 회귀분석","c":[{"t":"1. 상관관계 (Correlation )","c":[{"t":"(1) 상관계수","c":[{"t":"① -1~+1 상관계수","n":[["설명","두 변수가 함께 움직이는 선형 관계의 강도와 방향을 -1~+1로 나타낸다(피어슨 상관계수)."]]},{"t":"② +1·-1·0의 의미","n":[["설명","+1: 완전한 양의 상관, -1: 완전한 음의 상관, 0: 선형 관계 없음."]]},{"t":"③ 공분산 표준화","n":[["설명","공분산(Covariance)을 두 변수의 표준편차 곱으로 나누어 표준화한 것이 상관계수이다."]]}]},{"t":"(2) 해석의 주의점","c":[{"t":"① 상관≠인과","n":[["설명","상관관계는 인과관계가 아니다(Correlation ≠ Causation). 두 변수가 제3의 변수에 함께 반응할 수 있다."]]},{"t":"② 위기 시 상관 1에 근접","n":[["설명","상관관계는 시간에 따라 변한다. 위기 시에는 자산 간 상관이 1에 가까워져 분산투자 효과가 약해지는 경향이 있다."]]},{"t":"③ 수익률로 허위 상관 방지","n":[["설명","가격 '수준'보다 '수익률'의 상관을 계산해야 허위 상관(Spurious Correlation)을 피할 수 있다."]]}]}]},{"t":"2. 회귀분석 (Regression)","c":[{"t":"(1) 선형 회귀","c":[{"t":"① Y=a+bX 최소제곱법","n":[["설명","종속변수 Y와 독립변수 X의 관계를 Y = a + bX 직선으로 추정한다. 오차 제곱합을 최소화하는 최소제곱법(OLS)을 사용한다."]]},{"t":"② 기울기=베타(Beta)","n":[["설명","기울기 b는 X가 1 변할 때 Y의 평균 변화량이다. 예: 주식 수익률을 시장 수익률에 회귀한 기울기가 베타(Beta)이다."]]},{"t":"③ 회귀 채널","n":[["설명","선형회귀선(Linear Regression Line)은 추세선의 객관적 대안으로 쓰이며, 회귀선 ± 표준오차로 채널(회귀 채널) 을 만들 수 있다."]]}]},{"t":"(2) 결정계수 (R²)","c":[{"t":"① R²=설명 비율","n":[["설명","R²는 Y의 변동 중 X로 설명되는 비율(0~1)이다. 단순회귀에서 R² = 상관계수의 제곱이다. 예: 상관계수 0.8 → R² = 0.64(64% 설명)."]]},{"t":"② 높은 R²=매끄러운 추세","n":[["쉬운 예","여름에는 아이스크림 판매량과 물놀이 사고가 함께 늘어난다. 둘은 상관관계가 높지만 아이스크림이 사고를 일으키지는 않는다. 둘 다 '더운 날씨'라는 제3의 변수에 반응할 뿐이다."],["문제 연습","(가) 상관계수 0.6일 때 단순회귀의 R²는? (나) 베타가 1.5인 종목은 시장이 +2% 움직일 때 평균적으로 얼마나 움직이는가?\n\n풀이 (가) 0.6² = 0.36(36% 설명). (나) 1.5 × 2% = +3%."],["설명","추세의 '질'을 판단하는 데 쓸 수 있다. 가격-시간 회귀의 R²가 높으면 추세가 매끄럽고 일관적이다."]]}]}]}]},{"t":"Ⅳ 변동성 분석 (Volatility Analysis)","c":[{"t":"1. 변동성의 개념","c":[{"t":"(1) 정의와 특성","c":[{"t":"① 변동성=변동 크기, 방향 무관","n":[["설명","변동성은 가격 변동의 크기(분산 정도)이며 방향과는 무관하다. 위험 측정, 손절 폭, 포지션 크기 결정의 핵심 입력값이다."]]},{"t":"② 변동성 군집","n":[["설명","변동성 군집(Volatility Clustering): 큰 변동 뒤에는 큰 변동, 작은 변동 뒤에는 작은 변동이 이어지는 경향이다."]]},{"t":"③ 변동성 평균회귀","n":[["설명","평균회귀성: 변동성은 장기 평균으로 돌아가려는 경향이 있다. 극단적 저변동성(수축) 뒤에는 확장이 온다."]]},{"t":"④ 하락기 변동성 확대","n":[["설명","주식시장에서는 하락기에 변동성이 커지는 비대칭성(레버리지 효과)이 관찰된다."]]}]},{"t":"(2) 역사적 변동성과 내재변동성","c":[{"t":"① 역사적 변동성 연율화","n":[["설명","역사적 변동성(Historical/Realized Volatility): 과거 수익률(대개 로그 수익률)의 표준편차를 연율화한 값이다. 연율화 = 일간 σ × √252."]]},{"t":"② 연 변동성 계산 예","n":[["설명","예: 일간 표준편차 2% → 연 변동성 ≈ 2% × √252 ≈ 2% × 15.87 ≈ 31.7%."]]},{"t":"③ 내재변동성(IV)","n":[["설명","내재변동성(Implied Volatility, IV): 옵션 가격에서 역산한 시장의 '미래 기대' 변동성이다. 이벤트(실적, FDA 발표) 전에 상승했다가 발표 후 급락(IV Crush)하는 경향이 있다."]]}]}]},{"t":"2. 변동성 측정 도구","c":[{"t":"(1) 실제 범위와 ATR","c":[{"t":"① 실제 범위(TR) 정의","n":[["설명","실제 범위(True Range, TR, 와일더) = 다음 세 값 중 최댓값: 당일 고가 - 당일 저가, |당일 고가 - 전일 종가|, |당일 저가 - 전일 종가|. 갭을 반영하는 것이 핵심이다."]]},{"t":"② TR 계산 예: $2","n":[["설명","예: 전일 종가 $10, 당일 고가 $12, 저가 $11 → 세 값 1, 2, 1 → TR = $2(갭 상승 반영)."]]},{"t":"③ ATR: TR 이동평균","n":[["설명","ATR(Average True Range): TR의 이동평균(기본 14일, 와일더 평활). 달러 단위의 절대 변동성 척도로, ATR 배수 손절(예: 2 × ATR)과 포지션 크기 결정에 쓰인다."]]},{"t":"④ ATR%로 종목 비교","n":[["설명","ATR은 가격 수준에 따라 달라지므로 종목 간 비교에는 ATR ÷ 가격(ATR%)을 사용한다."]]}]},{"t":"(2) 변동성 기반 지표","c":[{"t":"① 볼린저 밴드폭","n":[["설명","볼린저 밴드폭(Bandwidth) = (상단 - 하단) ÷ 중심선. 역사적 저점 수준이면 스퀴즈로 변동성 확장이 임박했음을 시사한다."]]},{"t":"② 켈트너·샹들리에 청산","n":[["설명","켈트너 채널, 샹들리에 청산(Chandelier Exit: 최고가 - n × ATR) 등 ATR 기반 도구가 있다."]]},{"t":"③ 표준편차 채널","n":[["설명","표준편차 채널: 회귀선 또는 이동평균에서 ±kσ로 그린 채널이다."]]}]},{"t":"(3) VIX와 변동성 지수","c":[{"t":"① VIX: S&P500 30일 IV","n":[["설명","VIX: CBOE가 산출하는 S&P 500 옵션의 30일 내재변동성 지수이다. 연율 %로 표시되며, VIX 20은 향후 30일 동안 연율 약 20%의 변동을 기대한다는 뜻이다."]]},{"t":"② 주가와 음의 상관","n":[["설명","VIX는 주가와 음의 상관관계를 보인다. 급등은 공포, 매우 낮은 수준은 안일함으로 해석하며 역발상 지표로 활용된다."]]},{"t":"③ VIX÷√12=월 기대 변동","n":[["설명","VIX/√12 ≈ 향후 1개월 기대 변동 폭(1σ, %)으로 대략 환산할 수 있다. 예: VIX 24 → 월 약 6.9%."]]}]}]},{"t":"3. 변동성과 매매","c":[{"t":"(1) 변동성 수축과 확장","c":[{"t":"① 수축 뒤 확장","n":[["설명","변동성 수축(NR7, 볼린저 스퀴즈, 삼각형 수렴) 뒤에는 확장이 온다. 수축 구간은 돌파 매매의 준비 단계이다."]]},{"t":"② 확장기 포지션 축소","n":[["설명","변동성 확장 국면에서는 손절 폭을 넓히고 포지션을 줄여 달러 위험을 일정하게 유지해야 한다."]]}]},{"t":"(2) 스캘핑 적용: 거래정지(HALT) 전후 변동성","c":[{"t":"① LULD 거래정지 제도","n":[["설명","미국 LULD(Limit Up-Limit Down) 제도는 일정 시간 내 가격이 기준 밴드를 벗어나면 거래를 일시정지시킨다. 이는 CMT 범위 밖의 시장 구조 규정이지만 변동성 관리와 직결된다."]]},{"t":"② 재개 직후 갭·슬리피지","n":[["쉬운 예","ATR은 그 종목의 '평소 보폭'이다. 보폭이 1m인 사람 앞 30cm에 줄을 쳐 두면 그냥 걷다가도 걸려 넘어진다. 손절 폭을 ATR보다 너무 좁게 잡으면 정상적인 흔들림에도 손절된다."],["문제 연습","전일 종가 $50, 오늘 고가 $49, 저가 $46(갭 하락)이다. 실제 범위(TR)는?\n\n풀이 H - L = 3, |49 - 50| = 1, |46 - 50| = 4 → 최댓값 TR = $4. 단순 범위 $3보다 크다(갭 반영)."],["주차 핵심 요약","기하평균 ≤ 산술평균(+50%, -50% → 기하 -13.4%). 극단값에 강한 것은 중앙값. σ = √분산, Z = (X-μ)/σ.\n대수의 법칙, i.i.d., 도박사의 오류. 정규분포 68-95-99.7. 로그정규 = 오른쪽 꼬리. 첨도 3 = 정규, >3 두꺼운 꼬리.\n상관 ≠ 인과, R² = r²(단순회귀). TR = max(H-L, |H-Cp|, |L-Cp|), ATR 14일. 연 변동성 = 일간 σ × √252. VIX = S&P500 30일 IV."],["설명","정지 재개 직후에는 갭과 슬리피지로 계획한 손절가보다 훨씬 불리하게 체결될 수 있다. 변동성이 극단적인 종목은 ATR 기반으로 포지션을 크게 줄여야 한다."]]}]}]}]}],"b":7},{"n":8,"t":"사이클 분석과 시스템 트레이딩·계량 방법","c":[{"t":"Ⅰ 사이클 이론의 기초","c":[{"t":"1. 사이클의 정의와 유형","c":[{"t":"(1) 사이클이란","c":[{"t":"① 상승·하락 반복 패턴","n":[["이번 주 학습목표","① 사이클의 두 유형과 세 가지 구성요소(진폭·주기·위상), 주파수와 주기의 관계를 설명할 수 있다.\n② 허스트의 사이클 원리, 지배 사이클, 좌·우 이동(Translation)을 이해한다.\n③ 신호·전략·모델, 트리거·필터·값 규칙, 신호 테스트와 백테스트를 구별할 수 있다.\n④ 백테스트의 편향(생존·미래참조·과최적화)과 성과지표(승률·기대값·손익비·R배수·MDD·샤프)를 계산할 수 있다."],["설명","사이클은 가격의 상승과 하락이 반복되는 패턴이다. 경기순환(Business Cycle)처럼 거시경제에도, 개별 증권에도 존재한다."]]},{"t":"② 사이클은 '언제'에 답함","n":[["설명","사이클 분석은 '언제' 추세 전환이 일어날 가능성이 높은지(시간 요소)를 추정하는 데 쓰인다. 가격 분석이 '얼마나'라면 사이클은 '언제'에 답한다."]]},{"t":"③ 허용 범위 내 변동","n":[["설명","완벽하게 같은 간격으로 반복되는 사이클은 없으며 일정한 허용 범위(Tolerance) 안에서 변동한다."]]}]},{"t":"(2) 두 가지 유형","c":[{"t":"① 고정 사이클(Linear)","n":[["설명","고정 사이클(Fixed/Linear Cycle): 일정한 간격으로 반복된다. CMT Level I에서 주로 다루는 유형이다."]]},{"t":"② 확장 사이클(피보나치)","n":[["설명","확장 사이클(Nonlinear/Sequence Cycle): 피보나치 수열(1, 2, 3, 5, 8, 13, 21…)처럼 기준 시점부터 간격이 확장된다. 예: 스파이럴 캘린더(Spiral Calendar)."]]}]}]},{"t":"2. 사이클의 구성요소","c":[{"t":"(1) 세 가지 정의적 특성","c":[{"t":"① 진폭(Amplitude)","n":[["설명","진폭(Amplitude): 사이클의 높이(기준선에서 정점까지의 크기)이다."]]},{"t":"② 주기·파장: 저점~저점","n":[["설명","주기(Period)·파장(Wavelength): 한 사이클이 완성되는 데 걸리는 시간이다. 금융에서는 식별이 쉬운 '저점에서 저점(Trough to Trough)'으로 측정하는 것이 관행이다."]]},{"t":"③ 위상(Phase): 360도","n":[["설명","위상(Phase): 시간 축에서 사이클의 위치(이동)를 각도로 나타낸다. 한 사이클은 360도이며, 90도 어긋난 두 파동은 '위상이 90도 다르다'고 한다."]]}]},{"t":"(2) 주파수 (Frequency)","c":[{"t":"① 주파수=1÷주기","n":[["설명","주파수 = 1 ÷ 주기. 단위 시간당 완성되는 사이클 수이다."]]},{"t":"② 주파수 계산 예","n":[["설명","예: 주기 40일 → 주파수 1/40 = 0.025(일당 사이클). 주기 4일 → 0.25. 주기 100일 → 0.01."]]},{"t":"③ 주기↑ 주파수↓ 반비례","n":[["쉬운 예","사이클은 놀이공원 대관람차다. 진폭 = 관람차의 높이, 주기 = 한 바퀴 도는 시간, 위상 = 지금 내가 탄 칸이 어디쯤인가."],["문제 연습","주파수가 0.05(일당 사이클)인 사이클의 주기는? 주기 25일 사이클의 주파수는?\n\n풀이 주기 = 1 ÷ 0.05 = 20일. 주파수 = 1 ÷ 25 = 0.04."],["설명","주기가 길수록 주파수는 낮다(반비례)."]]}]}]}]},{"t":"Ⅱ 허스트의 사이클 이론","c":[{"t":"1. 허스트의 사이클 원리","c":[{"t":"(1) 허스트(J. M. Hurst)","c":[{"t":"① 항공우주 엔지니어 허스트","n":[["설명","1960~70년대 항공우주 엔지니어로서 스펙트럼 분석 등 과학적 방법으로 시장 사이클을 연구하였다. 현대 사이클 이론의 아버지로 불린다."]]},{"t":"② 『Profit Magic』(197 0)","n":[["설명","『The Profit Magic of Stock Transaction Timing』(1970) 등을 저술하였다."]]}]},{"t":"(2) 사이클의 원리","c":[{"t":"① 공통성(Commonality)","n":[["설명","공통성(Commonality): 모든 시장의 가격 움직임에는 공통된 사이클 특성이 있다."]]},{"t":"② 순환성(Cyclicality)","n":[["설명","순환성(Cyclicality): 가격 움직임은 여러 사이클로 구성된다."]]},{"t":"③ 합산(Summation)","n":[["설명","합산(Summation): 가격은 여러 사이클 파동을 합한 결과(복합파, Composite Wave)이다."]]},{"t":"④ 조화(Harmonicity)","n":[["설명","조화(Harmonicity): 인접한 사이클은 대개 2배 또는 3배의 정수 관계에 있다. 예: 40주 사이클 안에 20주 사이클 2개."]]},{"t":"⑤ 동시성(Synchronicity)","n":[["설명","동시성(Synchronicity): 서로 다른 길이의 사이클들은 같은 시점에 저점을 형성하는 경향이 있다."]]},{"t":"⑥ 비례성(Proportionalit y)","n":[["설명","비례성(Proportionality): 주기가 긴 사이클일수록 진폭이 크다."]]},{"t":"⑦ 명목성(Nominality)","n":[["설명","명목성(Nominality): 모든 시장에 공통으로 나타나는 명목 사이클 집합(Nominal Model)이 있다. 예: 18년, 9년, 54개월, 18개월, 40주, 20주, 10주, 5주, 20일, 10일."]]},{"t":"⑧ 변동성(Variation)","n":[["설명","변동성(Variation): 위 원리들은 경향일 뿐 실제 사이클 길이와 진폭은 일정 범위에서 변한다."]]}]}]},{"t":"2. 사이클 분석의 실전 개념","c":[{"t":"(1) 지배 사이클과 복합파","c":[{"t":"① 지배 사이클(Dominant)","n":[["설명","지배 사이클(Dominant Cycle): 가격 움직임에 가장 큰 영향을 주는(진폭이 큰) 사이클이다. 분석과 지표 기간 설정의 기준이 된다."]]},{"t":"② 복합파와 저점 중첩","n":[["설명","복합파: 여러 사이클이 합쳐진 가격은 단순한 사인파처럼 보이지 않는다. 짧은 사이클의 저점은 긴 사이클의 저점과 겹칠 때 더 깊고 중요해진다."]]}]},{"t":"(2) 좌·우 이동 (Translation)","c":[{"t":"① 우측 이동=강세","n":[["설명","우측 이동(Right Translation): 사이클 고점이 사이클 중간 지점보다 늦게(오른쪽) 형성된다. 상승 기간이 길다는 뜻으로 상위 추세가 상승(강세)임을 시사한다."]]},{"t":"② 좌측 이동=약세","n":[["설명","좌측 이동(Left Translation): 사이클 고점이 중간 지점보다 일찍(왼쪽) 형성된다. 하락 기간이 길어 상위 추세가 하락(약세)임을 시사한다."]]},{"t":"③ 상위 사이클 추세의 영향","n":[["설명","이동의 원인은 상위(더 긴) 사이클의 추세가 짧은 사이클에 더해지기 때문이다."]]}]},{"t":"(3) 사이클 분석 도구","c":[{"t":"① 중심 이동평균","n":[["설명","중심 이동평균(Centered MA): 사이클 주기의 절반+1 기간 이동평균을 기간 중앙에 그려 해당 사이클보다 짧은 사이클을 제거한다."]]},{"t":"② 엔벨로프와 FLD","n":[["설명","사이클 엔벨로프(Envelope)와 FLD(Future Line of Demarcation, 허스트): 가격을 반주기만큼 앞으로 이동시킨선으로, 가격과의 교차로 목표가·시점을 추정한다."]]},{"t":"③ 스펙트럼·푸리에 분석","n":[["설명","스펙트럼 분석·푸리에 분석(Fourier)·주기도(Periodogram): 데이터에서 주요 주기를 수학적으로 찾아낸다."]]},{"t":"④ 디트렌딩(Detrending)","n":[["설명","디트렌딩(Detrending): 가격에서 이동평균 등을 빼서 추세를 제거하면 사이클이 더 잘 보인다."]]}]}]},{"t":"3. 경제·계절 사이클","c":[{"t":"(1) 장기 경제 사이클","c":[{"t":"① 콘드라티예프 파동(50~60년)","n":[["설명","콘드라티예프(Kondratieff) 파동: 약 50~60년 주기의 장기 경제 사이클이다."]]},{"t":"② 쿠즈네츠·주글라·키친","n":[["설명","쿠즈네츠(Kuznets) 약 15~25년(건설·인프라), 주글라(Juglar) 약 7~11년(설비투자), 키친(Kitchin) 약 40개월(재고) 사이클이 있다."]]}]},{"t":"(2) 계절성과 달력 효과","c":[{"t":"① 대통령 사이클: 3년차 강세","n":[["설명","대통령 사이클(Presidential Cycle): 미국 대통령 임기 4년 중 3년차(선거 전년)의 주식시장 성과가 좋은 경향이다."]]},{"t":"② 10년 주기 패턴","n":[["설명","10년 주기 패턴(Decennial Pattern): 끝자리가 5인 해의 성과가 좋았다는 관찰이다."]]},{"t":"③ 계절성: Sell in May","n":[["쉬운 예","조화의 원리는 맞물린 톱니바퀴다. 큰 톱니바퀴(40주 사이클)가 한 바퀴 돌 때 작은 톱니바퀴(20주 사이클)는 정확히 두 바퀴 돈다. 그래서 큰 바퀴의 저점에서는 작은 바퀴의 저점도 함께 온다(동시성)."],["문제 연습","20일 사이클이 0일에 저점, 13일째에 고점, 20일째에 다시 저점을 만들었다. 좌·우 이동 중 무엇이고, 상위\n추세에 대해 무엇을 시사하는가?\n\n풀이 중간 지점은 10일인데 고점이 13일로 늦다 → 우측 이동 → 상위 추세 강세."],["설명","계절성: \"5월에 팔고 떠나라(Sell in May)\", 11~4월 강세, 연말·1월 효과 등이 알려져 있다."]]}]}]}]},{"t":"Ⅲ 시스템 트레이딩의 개념","c":[{"t":"1. 계량 분석과 과학적 방법","c":[{"t":"(1) 계량 분석 (Quantitat ive Analysis)","c":[{"t":"① 주관적 표현의 정량화","n":[["설명","주관적 표현(\"강하게 돌파했다\")을 정량적 표현(\"종가가 20일 최고가를 넘고 거래량이 50일 평균의 2배 이상\")으로 바꾸는 것이다."]]},{"t":"② 검증·반복·감정 배제","n":[["설명","규칙이 명확하면 검증·반복·개선이 가능하고, 감정(행동 편향)의 개입을 줄일 수 있다."]]}]},{"t":"(2) 과학적 방법 (Scientific Method)","c":[{"t":"① 관찰→가설→검증→결론","n":[["설명","관찰 → 질문 → 가설 설정 → 검증(테스트) → 측정 → 결론의 순서를 따른다."]]},{"t":"② 체리피킹=확증편향","n":[["설명","가설에 맞는 차트만 골라 보는 것(체리피킹)은 확증편향이다. 신호가 발생한 '모든' 사례를 검증해야 한다."]]},{"t":"③ 오컴의 면도날","n":[["설명","오컴의 면도날: 같은 설명력이면 더 단순한 모델이 낫다. \"Simple > Clever\"."]]}]}]},{"t":"2. 신호·전략·모델과 규칙의 유형","c":[{"t":"(1) 신호·전략·모델","c":[{"t":"① 신호(Signal)","n":[["설명","신호(Signal): 특정 행동을 고려하게 만드는 하나의 관찰·조건이다. 예: RSI 다이버전스, 이동평균 교차."]]},{"t":"② 전략(Strategy)","n":[["설명","전략(Strategy): 신호에 진입·청산·손절·포지션 크기 규칙을 결합한 완전한 매매 규칙이다."]]},{"t":"③ 모델(Model)","n":[["설명","모델(Model): 여러 변수와 규칙을 통합하여 시장을 분석하거나 매매 결정을 생성하는 포괄적 체계이다."]]}]},{"t":"(2) 트리거·필터·값 규칙","c":[{"t":"① 트리거 규칙","n":[["설명","트리거 규칙(Trigger Rule): 특정 사건이 '발생하는 순간' 행동 후보를 만든다. 예: 가격이 20일 고가를 상향 돌파."]]},{"t":"② 필터 규칙","n":[["설명","필터 규칙(Filter Rule): 트리거가 발생해도 추가 조건(예: 200일선 위, 시장 추세 상승)을 만족할 때만 거래를 허용한다. 신호의 질을 높이지만 거래 수를 줄인다."]]},{"t":"③ 값 규칙","n":[["설명","값 규칙(Value Rule): 변수가 특정 값·범위에 있는지를 조건으로 사용한다. 예: RSI < 30, ATR% > 5%."]]},{"t":"④ 과도한 필터=과최적화","n":[["설명","필터를 과도하게 추가하면(예: RSI > 71.3, 09:37~09:51 사이) 과거 데이터에만 맞춘 과최적화가 된다."]]}]},{"t":"(3) 시스템의 유형","c":[{"t":"① 추세 추종: 낮은 승률·높은 손익비","n":[["설명","추세 추종 시스템: 이동평균 교차, 채널 돌파(돈치안 채널, 터틀 트레이딩) 등. 승률은 낮지만(30~45%) 평균 이익이 커서 손익비가 높다."]]},{"t":"② 평균회귀: 높은 승률·작은 이익","n":[["설명","평균회귀(역추세) 시스템: 과매도 매수·과매수 매도. 승률은 높지만 평균 이익이 작고 가끔 큰 손실이 발생할 수 있다."]]},{"t":"③ 재량 vs 기계적 매매","n":[["쉬운 예","트리거 규칙은 초인종(누가 왔다는 사건), 필터 규칙은 문을 열기 전 인터폰 확인(조건을 만족할 때만 허용), 값 규칙은 '체온 37.5도 이상 입장 불가'처럼 수치 범위를 보는 조건이다."],["실전 사례","스캘퍼의 정량화 예 — 주관적 표현 \"강한 거래량으로 돌파했다\"를 \"1분봉 종가가 프리마켓 고점을 넘고(트리거), 상대거래량이 5배 이상이며(값 규칙), 가격이 VWAP 위일 때만(필터)\"으로 바꾸면 검증과 반복이 가능해진다."],["설명","재량(Discretionary) 매매 vs 기계적(Mechanical) 매매: 기계적 시스템은 일관성과 검증 가능성이, 재량 매매는 유연성이 장점이다."]]}]}]}]},{"t":"Ⅳ 백테스트와 성과 평가","c":[{"t":"1. 신호 테스트와 백테스트","c":[{"t":"(1) 신호 테스트 (Signal Test)","c":[{"t":"① 신호 후 가격 움직임 측정","n":[["설명","신호가 발생한 모든 사례를 찾아 신호 이후 일정 기간(예: 1, 5, 10, 20일) 가격이 어떻게 움직였는지 측정한다."]]},{"t":"② 신호 예측력 확인","n":[["설명","신호 자체에 예측력이 있는지(무작위 대비 우위가 있는지)를 확인하는 단계이다. 손절·청산 규칙은 아직 포함하지 않는다."]]}]},{"t":"(2) 백테스트 (Backtest)","c":[{"t":"① 전체 전략의 과거 성과 측정","n":[["설명","진입·청산·손절·포지션 크기·비용을 모두 포함한 전략을 과거 데이터에 적용하여 전체 매매 시스템의 성과를 측정한다."]]},{"t":"② 신호→백테스트→포워드 순서","n":[["설명","순서: 신호 테스트로 우위를 확인한 뒤 → 전략을 구성해 백테스트 → 표본 외 검증 → 소규모 실전(포워드 테스트)으로 진행한다."]]}]}]},{"t":"2. 백테스트의 함정","c":[{"t":"(1) 데이터 관련 편향","c":[{"t":"① 생존편향","n":[["설명","생존편향(Survivorship Bias): 현재 살아남은 종목만으로 검증하여 상장폐지 종목의 손실이 누락된다. 성과가 과대평가된다."]]},{"t":"② 미래참조 편향","n":[["설명","미래참조 편향(Look-ahead Bias): 매매 시점에는 알 수 없었던 정보(당일 종가, 이후 수정된 실적)를 사용하는 오류이다. \"매매 시점에 실제로 알 수 있었던 정보만 사용한다.\""]]},{"t":"③ 데이터 스누핑","n":[["설명","데이터 스누핑(Data Snooping/Data Mining Bias): 같은 데이터로 수많은 규칙을 시험하면 우연히 좋은 결과가 나온 규칙이 선택된다."]]}]},{"t":"(2) 최적화와 과최적화","c":[{"t":"① 최적화(Optimization)","n":[["설명","최적화(Optimization): 매개변수(예: 이동평균 기간)를 바꿔가며 가장 좋은 값을 찾는 과정이다."]]},{"t":"② 과최적화(Curve Fitting)","n":[["설명","과최적화(Over-fitting/Curve Fitting): 과거의 잡음까지 맞춘 결과로, 표본 내에서는 성과가 뛰어나지만 실전에서는 무너진다."]]},{"t":"③ 견고성: 성과 고원","n":[["설명","견고성(Robustness) 확인: 최적값 주변 매개변수에서도 성과가 비슷한가(성과 고원, Plateau)? 다른 시장·기간에서도 작동하는가?"]]},{"t":"④ 표본 외·워크포워드 검증","n":[["설명","표본 외 검증(Out-of-Sample)과 워크포워드 분석(Walk-forward): 데이터를 나누어 한 구간에서 최적화하고 다음 구간에서 검증하는 과정을 반복한다."]]}]},{"t":"(3) 실행 관련 오류","c":[{"t":"① 슬리피지·수수료 무시","n":[["설명","슬리피지·수수료 무시: 특히 저유동성 소형주에서 백테스트 성과를 크게 과장한다."]]},{"t":"② 유동성 편향","n":[["설명","유동성 편향: 백테스트에서는 원하는 수량이 체결되지만 실제로는 호가가 얇아 체결이 불가능할 수 있다."]]},{"t":"③ 거래정지·갭 위험","n":[["설명","거래정지·갭 위험: 손절가가 보장되지 않는 상황을 백테스트에 반영해야 한다."]]}]}]},{"t":"3. 성과 지표","c":[{"t":"(1) 기본 지표","c":[{"t":"① 승률(Win Rate)","n":[["설명","승률(Win Rate) = 이익 거래 수 ÷ 전체 거래 수. 승률만으로는 전략을 평가할 수 없다."]]},{"t":"② 손익비(Payoff Ratio)","n":[["설명","손익비(Payoff Ratio) = 평균 이익 ÷ 평균 손실."]]},{"t":"③ 프로핏 팩터","n":[["설명","프로핏 팩터(Profit Factor) = 총이익 ÷ 총손실. 1보다 크면 이익, 일반적으로 1.5~2 이상이면 양호하다고 본다."]]},{"t":"④ PF 계산 예: 1.5","n":[["설명","예: 총이익 $15,000, 총손실 $10,000 → PF = 1.5."]]}]},{"t":"(2) 기대값과 R배수","c":[{"t":"① R배수=손익÷초기 위험","n":[["설명","R(1R): 진입 시 설정한 초기 위험(진입가 - 손절가)이다. R배수 = 거래 손익 ÷ 초기 위험. 예: 진입 $5.00, 손절 $4.80(1R = $0.20), 청산 $5.40 → +2R."]]},{"t":"② 기대값 공식","n":[["설명","기대값(Expectancy) = (승률 × 평균 이익) - (패배율 × 평균 손실)."]]},{"t":"③ 기대값 예: +0.35R","n":[["설명","예: 승률 45%, 평균 이익 2R, 평균 손실 1R → 0.45×2 - 0.55×1 = +0.35R. 거래당 평균 0.35R의 이익이 기대된다."]]},{"t":"④ 고승률에도 음의 기대값","n":[["설명","반대 예: 승률 70%, 평균 이익 0.5R, 평균 손실 2R → 0.35 - 0.60 = -0.25R. 승률이 높아도 기대값은 음수일 수 있다."]]},{"t":"⑤ 손익분기 승률=1÷(1+손익비)","n":[["설명","손익분기 승률 = 1 ÷ (1 + 손익비). 예: 손익비 2 → 손익분기 승률 33.3%."]]}]},{"t":"(3) 위험조정 지표","c":[{"t":"① 최대 낙폭(MDD)","n":[["설명","최대 낙폭(Maximum Drawdown, MDD): 자산곡선의 고점에서 이후 저점까지의 최대 하락률이다."]]},{"t":"② 샤프 비율","n":[["설명","샤프 비율(Sharpe Ratio) = (수익률 - 무위험수익률) ÷ 수익률 표준편차. 총 위험 단위당 초과수익이다."]]},{"t":"③ 소르티노·칼마 비율","n":[["설명","소르티노 비율(Sortino Ratio): 분모에 하방 편차만 사용한다. 칼마/MAR 비율 = 연수익률 ÷ 최대 낙폭."]]},{"t":"④ MFE·MAE","n":[["설명","MFE(Maximum Favorable Excursion)·MAE(Maximum Adverse Excursion): 거래 중 최대 유리·불리 움직임이다. MAE 분포로 적정 손절 폭을, MFE 분포로 이익실현 위치를 개선한다(존 스위니)."]]}]},{"t":"(4) 통계적 신뢰성","c":[{"t":"① 표본 크기: 최소 30건","n":[["설명","표본 크기: 거래 수가 적으면 결과가 우연일 가능성이 크다. 일반적으로 최소 30건, 가능하면 수백 건 이상을 권장한다."]]},{"t":"② 평균과 중앙값 병행","n":[["설명","평균과 중앙값: 급등주 전략은 소수의 대박 거래가 평균을 끌어올리므로 중앙값·분포·이상값 제거 후 성과를 함께 본다."]]},{"t":"③ 시장 국면 의존성","n":[["표","지표 | 공식 | 의미\n승률 | 이익거래 ÷ 전체거래 | 맞힌 비율(단독 평가 불가)\n손익비 | 평균이익 ÷ 평균손실 | 한 번 이길 때 얻는 크기\n프로핏 팩터 | 총이익 ÷ 총손실 | 1 초과 = 순이익\n기대값 | 승률×평균이익 - 패배율×평균손실 | 거래당 기대 손익\nR배수 | 손익 ÷ 초기위험 | 위험 대비 성과 표준화\nMDD | 고점 대비 최대 하락률 | 최악의 자산 감소\n샤프 비율 | (Rp - Rf) ÷ σp | 위험 단위당 초과수익"],["쉬운 예","과최적화는 기출문제 답만 외운 학생과 같다. 기출(표본 내)에서는 만점이지만 처음 보는 문제(표본 외)에서는 무너진다. 표본 외 검증과 워크포워드는 '모의고사를 새 문제로 보는 것'이다."],["문제 연습","승률 35%, 평균 이익 2.5R, 평균 손실 1R인 전략의 기대값과 손익분기 승률은?\n\n풀이 기대값 = 0.35 × 2.5 - 0.65 × 1 = 0.875 - 0.65 = +0.225R. 손익분기 승률 = 1 ÷ (1 + 2.5) ≈ 28.6%. 실제 승률 35%가 이보다 높으므로 우위가 있다."],["주차 핵심 요약","사이클 3요소: 진폭·주기·위상. 주파수 = 1/주기. 저점-저점으로 측정. 허스트:\n합산·조화(2~3배)·동시성·비례성·명목성·변동성.\n우측 이동 = 강세, 좌측 이동 = 약세. 콘드라티예프 50~60년, 대통령 사이클 3년차 강세.\n신호 → 전략 → 모델. 트리거·필터·값 규칙. 신호 테스트(예측력) → 백테스트(시스템 성과).\n편향: 생존·미래참조·데이터스누핑·과최적화. 기대값 = p×W - (1-p)×L. 손익분기 승률 = 1/(1+손익비)."],["설명","시장 국면(Regime) 의존성: 특정 시장 환경에서만 작동하는 전략인지 확인한다(AMH와 연결)."]]}]}]}]}],"b":8},{"n":9,"t":"위험관리와 시장·금융상품","c":[{"t":"Ⅰ 위험관리의 원칙","c":[{"t":"1. 위험관리의 기본 개념","c":[{"t":"(1) 위험관리가 우선인 이유","c":[{"t":"① 틀렸을 때 손실을 미리 결정","n":[["이번 주 학습목표","① 1R, 포지션 크기 산정, 손절 유형, 낙폭 회복, 파산위험, 켈리 기준을 설명하고 계산할 수 있다.\n② 주문 유형(시장가·지정가·스톱·스톱지정가)의 특성과 위험을 구별할 수 있다.\n③ 주식·지수·채권·선물·ETP·외환·옵션·디지털자산의 기본 구조와 기술적 분석상의 유의점을 이해한다.\n④ 지수 가중 방식, 가격-수익률 관계, 콘탱고·백워데이션, ETF와 ETN의 차이, 옵션 그릭스를 구별할 수 있다."],["설명","어떤 분석도 틀릴 수 있다. 위험관리는 \"틀렸을 때 얼마나 잃을 것인가\"를 미리 정하는 과정이다."]]},{"t":"② 작게 잃어 다음 거래 보존","n":[["설명","좋은 트레이더의 첫 번째 목표는 한 거래에서 많이 버는 것이 아니라, 틀렸을 때 다음 거래를 할 수 있을 만큼 작게 잃는 것이다."]]},{"t":"③ 손절가→위험액→포지션 순서","n":[["설명","순서: 무효화 지점(Invalidation)과 손절가 결정 → 허용 위험액 결정 → 포지션 크기 산출. 포지션 크기를 먼저 정하고 손절을 나중에 생각하는 것은 잘못된 순서이다."]]}]},{"t":"(2) 위험의 종류","c":[{"t":"① 시장·유동성·갭·집중 위험","n":[["설명","시장 위험(가격 변동), 유동성 위험(원하는 가격에 거래 불가), 갭·거래정지 위험(손절가 미보장), 집중·상관 위험(여러 포지션이 같은 방향으로 움직임)이 있다."]]},{"t":"② 운영 위험·행동 위험","n":[["설명","운영 위험(시스템 오류, 주문 실수)과 행동 위험(규칙 위반, 복수 매매)도 실제 손실의 큰 원인이다."]]}]}]},{"t":"2. 포지션 크기 산정 (Position Sizing)","c":[{"t":"(1) 고정비율 위험 모델 (Fixed Fractional)","c":[{"t":"① 거래당 계좌 1~2% 위험","n":[["설명","한 거래에서 계좌의 일정 비율(보통 1~2%)만 위험에 노출한다."]]},{"t":"② 주식 수=위험액÷주당 위험","n":[["설명","주식 수 = 최대 허용 위험액 ÷ 주당 위험(진입가 - 손절가)."]]},{"t":"③ 포지션 크기 계산 예","n":[["설명","예: 계좌 $50,000, 위험 1% = $500, 진입 $10, 손절 $9.50(주당 위험 $0.50) → 1,000주. 손절이 $9.00이면 500주로 줄여야 달러 위험이 같다."]]}]},{"t":"(2) 변동성 기반 사이징","c":[{"t":"① ATR 기반 손절·수량","n":[["설명","ATR을 이용해 손절 폭을 정하고(예: 2 × ATR) 그에 맞춰 수량을 계산하면 종목 간 위험이 균등해진다(터틀 트레이딩의 'N' 개념)."]]},{"t":"② 손절 확대 시 수량 재계산","n":[["설명","변동성이 큰 종목일수록 수량을 줄인다. 손절을 임의로 넓히면(예: $4.80 → $4.50) 실제 위험이 증가하므로 수량도 다시 계산해야 한다."]]}]},{"t":"(3) 보상/위험 비율 (Reward/Risk)","c":[{"t":"① 보상/위험 비율 공식","n":[["설명","보상/위험 = (목표가 - 진입가) ÷ (진입가 - 손절가). 예: 진입 $5, 손절 $4.80, 목표 $5.60 → 0.60 ÷ 0.20 = 3:1."]]},{"t":"② 확률과 손익 분포 병행","n":[["설명","보상/위험이 높아도 목표 도달 확률이 낮으면 기대값은 나쁠 수 있다. 확률과 손익 분포를 함께 봐야 한다."]]}]}]},{"t":"3. 손절과 청산","c":[{"t":"(1) 손절 유형","c":[{"t":"① 가격(구조) 손절","n":[["설명","가격(구조) 손절: 지지선·스윙 저점 아래 등 분석이 무효화되는 가격에 둔다."]]},{"t":"② 변동성 손절","n":[["설명","변동성 손절: ATR 배수, 표준편차 등으로 정상 변동 범위 밖에 둔다."]]},{"t":"③ 시간 손절","n":[["설명","시간 손절: 일정 시간 안에 기대한 움직임이 없으면 청산한다."]]},{"t":"④ 트레일링 스톱","n":[["설명","트레일링 스톱(Trailing Stop): 가격이 유리하게 움직이면 손절가도 일정 규칙(예: 최고가 - 3 ATR, 이동평균, 직전 스윙 저점)으로 따라 올린다. 손절가는 절대 불리한 방향으로 옮기지 않는다."]]},{"t":"⑤ 자금(금액) 손절","n":[["설명","자금(금액) 손절: 계좌 손실 한도(일일 최대 손실)에 도달하면 거래를 중단한다."]]}]},{"t":"(2) 주문 유형","c":[{"t":"① 시장가 주문","n":[["설명","시장가 주문(Market): 즉시 체결되지만 가격이 보장되지 않는다(슬리피지)."]]},{"t":"② 지정가 주문","n":[["설명","지정가 주문(Limit): 지정한 가격 이하(매수)·이상(매도)에서만 체결된다. 가격은 보장되지만 체결이 보장되지 않는다."]]},{"t":"③ 스톱 주문","n":[["설명","스톱 주문(Stop): 스톱 가격에 도달하면 시장가 주문으로 전환된다. 스톱 가격은 '작동 조건(Trigger)'이지 체결가가 아니며, 갭·급락 시 훨씬 불리하게 체결될 수 있다."]]},{"t":"④ 스톱지정가 주문","n":[["설명","스톱지정가 주문(Stop-Limit): 스톱 가격 도달 시 지정가 주문이 나간다. 가격이 빠르게 지나가면 체결되지 않아 손실이 확대될 수 있다."]]}]}]},{"t":"4. 낙폭, 파산위험, 켈리 기준","c":[{"t":"(1) 낙폭과 회복","c":[{"t":"① 낙폭(Drawdown) 정의","n":[["설명","낙폭(Drawdown) = (고점 자산 - 현재 자산) ÷ 고점 자산. 예: $10,000 → $8,000은 20% 낙폭이다."]]},{"t":"② 회복 수익률=1÷(1-D)-1","n":[["설명","회복 필요 수익률 = 1 ÷ (1 - D) - 1. 예: 20% 손실 → 25% 필요, 50% 손실 → 100% 필요, 90% 손실 → 900% 필요."]]},{"t":"③ 작은 손실 관리가 핵심","n":[["표","낙폭 | 회복에 필요한 수익률\n10% | 11.1%\n20% | 25%\n33% | 50%\n50% | 100%\n75% | 300%"],["설명","낙폭이 커질수록 회복이 기하급수적으로 어려워지므로 작은 손실 관리가 핵심이다."]]}]},{"t":"(2) 파산위험 (Risk of Ruin)","c":[{"t":"① 자본이 거래 불가 수준 확률","n":[["설명","거래를 지속할 수 없는 수준까지 자본이 감소할 확률이다."]]},{"t":"② 파산위험 증가 요인","n":[["설명","승률이 낮을수록, 손익비가 낮을수록, 거래당 위험 비율이 클수록 파산위험이 커진다. 기대값이 양수라도 거래당 위험이 너무 크면 파산할 수 있다."]]}]},{"t":"(3) 켈리 기준 (Kelly Criterion)","c":[{"t":"① 켈리 공식 f*=(bp-q)÷b","n":[["설명","장기 자본 성장률을 최대화하는 이론적 베팅 비율이다. f* = (bp - q) ÷ b (b = 손익비, p = 승률, q = 1 - p)."]]},{"t":"② 켈리 계산 예: 33.3%","n":[["설명","예: b = 1.5, p = 0.60 → f* = (1.5×0.6 - 0.4) ÷ 1.5 = 0.5 ÷ 1.5 ≈ 33.3%."]]},{"t":"③ 하프 켈리 사용","n":[["설명","실전에서는 확률·손익비 추정에 오류가 있고 환경이 변하므로 풀 켈리는 변동성이 너무 크다. 하프 켈리 등 일부만 사용하는 것이 일반적이다."]]}]}]},{"t":"5. 포트폴리오 차원의 위험","c":[{"t":"(1) 분산과 상관","c":[{"t":"① 저상관 결합으로 변동성 감소","n":[["설명","상관관계가 낮은 포지션을 결합하면 전체 변동성이 줄어든다. 같은 섹터 소형주 여러 개는 사실상 하나의 큰 포지션일 수 있다."]]},{"t":"② 총 노출 한도 설정","n":[["설명","총 노출 한도(예: 동시 보유 위험 합계 6% 이하)를 정해 둔다."]]}]},{"t":"(2) 행동 규율","c":[{"t":"① 손절 준수율·실제 평균 손실","n":[["설명","손절 준수율, 계획 손실(-1R) 대비 실제 평균 손실(예: -1.28R)을 기록하면 슬리피지·손절 이동·규칙 위반의 비용을 계량할 수 있다."]]},{"t":"② 규칙 위반 거래 분석","n":[["쉬운 예","위험관리는 자동차 안전벨트다. 사고를 막아 주지는 않지만, 사고가 나도 '다음 운전'을 할 수 있게 해 준다. 손절은 사고를 예상해서가 아니라 사고 후에도 살아남기 위해 맨다."],["문제 연습","계좌 $30,000, 거래당 위험 0.5%, 진입 $8.40, 손절 $8.10이다. 매수 수량은? 이 거래가 50% 낙폭 계좌에서 일어났다면 회복 필요 수익률은?\n\n풀이 허용위험 = $150, 주당위험 = $0.30 → 500주. 50% 낙폭의 회복 필요 수익률 = 1 ÷ 0.5 - 1 = 100%."],["설명","규칙 위반으로 -1R이 -3R이 된 거래를 따로 모으면, 새로운 지표보다 규율 개선이 더 큰 수익 개선 요인일 수 있음을 알게 된다."]]}]}]}]},{"t":"Ⅱ 시장과 데이터, 주식과 지수","c":[{"t":"1. 시장과 기술적 분석가","c":[{"t":"(1) 시장의 종류","c":[{"t":"① 거래소·장외, 1차·2차 시장","n":[["설명","거래소 시장(Exchange)과 장외시장(OTC), 1차 시장(발행)과 2차 시장(유통)으로 구분한다."]]},{"t":"② 주문 기반·호가 기반 시장","n":[["설명","주문 기반(Order-driven, 호가창) 시장과 호가 기반(Quote-driven, 딜러·마켓메이커) 시장이 있다."]]},{"t":"③ 시장별 데이터 특성","n":[["설명","기술적 분석은 데이터(가격·거래량·미결제약정)가 있는 모든 시장에 적용할 수 있으나, 시장별로 데이터의 성격(24시간 거래, 중앙 거래량 부재, 만기 등)이 다르므로 이를 이해해야 한다."]]}]},{"t":"(2) 주식 (Equities)","c":[{"t":"① 보통주와 우선주","n":[["설명","보통주는 기업 소유권과 의결권, 배당청구권을 가진다. 우선주는 배당 우선권이 있으나 대개 의결권이 없다."]]},{"t":"② 시가총액·GICS 11섹터","n":[["설명","시가총액 분류(대형·중형·소형·마이크로캡), 섹터·산업 분류(GICS: 11개 섹터)로 종목을 그룹화한다."]]},{"t":"③ 유통주식수(Float)","n":[["설명","유통주식수(Float)가 적은 종목은 같은 자금 유입에도 가격 변동이 크다. 소형주 급등의 구조적 원인이다."]]}]}]},{"t":"2. 지수 (Indexes)","c":[{"t":"(1) 지수의 역할과 종류","c":[{"t":"① 지수=시장 계기판","n":[["설명","지수는 시장 전체 또는 특정 그룹의 성과를 측정하는 계기판이다. 그룹 간 순위 비교에도 쓰인다."]]},{"t":"② 주요 국가 지수","n":[["설명","주요 국가 지수: 미국 S&P 500·다우(DJIA)·나스닥, 영국 FTSE 100, 독일 DAX, 프랑스 CAC 40, 일본 닛케이 225, 홍콩 항셍, 한국 KOSPI 등이 있다."]]},{"t":"③ 러셀 3000·1000·2000","n":[["설명","규모별 지수: 러셀 3000(미국 전체), 러셀 1000(상위 1,000개 대형주), 러셀 2000(하위 2,000개 소형주)."]]},{"t":"④ 비주식 지수(DXY 등)","n":[["설명","비주식 지수: 달러 인덱스(DXY, 주요 통화 대비 달러 가치, 유로 비중 약 57%), CRB 원자재 지수, 리츠(REIT) 지수, 발틱 건화물 지수(BDI, 해운 운임 - 현대판 운송지수) 등이 있다."]]}]},{"t":"(2) 지수 가중 방식","c":[{"t":"① 가격가중: 다우·닛케이","n":[["설명","가격가중(Price-weighted): 주가가 높은 종목의 영향이 크다. 다우 산업평균, 닛케이 225. 주식분할 시 제수(Divisor)를 조정한다."]]},{"t":"② 시가총액가중: S&P500","n":[["설명","시가총액가중(Market-cap weighted): 시가총액이 큰 종목의 영향이 크다. S&P 500, 나스닥 종합. 오늘날에는 유통주식 기준(Float-adjusted)이 일반적이다."]]},{"t":"③ 동일가중","n":[["설명","동일가중(Equal-weighted): 모든 종목을 같은 비중으로 계산한다. 소형주 영향이 커지며 주기적 재조정이 필요하다."]]},{"t":"④ 기하평균 지수","n":[["설명","기하평균 지수: 밸류라인 기하지수(Value Line Geometric)처럼 수익률의 기하평균을 사용하며 상승 편향이 적다."]]}]},{"t":"(3) 지수 데이터의 주의점","c":[{"t":"① 구성 종목 교체 생존편향","n":[["설명","생존편향: 지수 구성 종목은 주기적으로 교체되므로 현재 구성 종목으로 과거를 검증하면 성과가 부풀려진다."]]},{"t":"② 시장폭 지표로 보완","n":[["쉬운 예","가격가중 지수는 '주가가 높은 종목 목소리가 큰 반', 시가총액가중 지수는 '덩치(시가총액)가 큰 종목이 시소를 기울이는 반', 동일가중 지수는 '모두 한 표씩인 반'이다."],["문제 연습","가격가중 지수가 $100, $50, $10 세 종목으로 구성되고 제수가 3이다. $100 종목이 10% 오를 때와 $10\n종목이 10% 오를 때 지수 변화는?\n\n풀이 현재 지수 = 160 ÷ 3 ≈ 53.33. $100 종목 +$10 → 지수 +3.33, $10 종목 +$1 → 지수 +0.33. 같은 10%라도 고가주의 영향이 10배 크다."],["설명","지수 평균이 같아도 구성 종목의 분산(산포)은 매우 넓거나 좁을 수 있으므로 시장폭 지표로 보완한다."]]}]}]}]},{"t":"Ⅲ 채권·선물·ETP·외환","c":[{"t":"1. 채권 (Fixed Income)","c":[{"t":"(1) 기본 구조","c":[{"t":"① 액면가·쿠폰·만기·신용등급","n":[["설명","채권은 발행자가 약속한 이자(쿠폰)와 원금을 만기에 지급하는 부채 증권이다. 주요 요소는 액면가, 쿠폰율, 만기, 신용등급이다."]]},{"t":"② 가격과 수익률의 역관계","n":[["설명","가격과 수익률의 역관계: 금리(수익률)가 오르면 기존 채권 가격은 하락하고, 금리가 내리면 가격은 상승한다."]]},{"t":"③ 듀레이션=금리 민감도","n":[["설명","듀레이션(Duration): 금리 변화에 대한 채권 가격의 민감도이다. 만기가 길고 쿠폰이 낮을수록 듀레이션이 크다."]]}]},{"t":"(2) 수익률 곡선과 신용 스프레드","c":[{"t":"① 수익률 곡선 형태","n":[["설명","수익률 곡선(Yield Curve): 만기별 국채 수익률을 연결한 곡선이다. 정상형(우상향), 평탄형(Flat), 역전형(Inverted: 단기금리 > 장기금리)이 있다."]]},{"t":"② 역전=경기침체 선행 신호","n":[["설명","역전된 수익률 곡선(예: 10년물 - 2년물 < 0)은 역사적으로 경기침체의 선행 신호로 알려져 있다."]]},{"t":"③ 신용 스프레드와 위험선호","n":[["설명","신용 스프레드(회사채 수익률 - 국채 수익률)가 확대되면 위험회피(Risk-off), 축소되면 위험선호(Risk-on)를 뜻한다."]]},{"t":"④ 가격 vs 수익률 차트 주의","n":[["설명","기술적 분석에서는 채권 가격 차트 또는 수익률 차트 중 어느 것을 보는지 주의해야 한다(방향이 반대)."]]}]}]},{"t":"2. 선물 (Futures)","c":[{"t":"(1) 기본 구조","c":[{"t":"① 표준화된 거래소 계약","n":[["설명","선물은 미래 특정 시점에 정해진 가격으로 표준화된 수량의 자산을 사고팔기로 한 거래소 계약이다. 헤지(위험회피) 와 투기에 사용된다."]]},{"t":"② 개시·유지 증거금","n":[["설명","증거금(Margin): 개시증거금(Initial)과 유지증거금(Maintenance). 매일 정산(Mark-to-market)되며 유지증거금 아래로 내려가면 추가증거금(Margin Call)이 요구된다. 높은 레버리지가 특징이다."]]},{"t":"③ 계약 명세","n":[["설명","계약 명세: 기초자산, 계약 단위, 호가 단위(Tick), 만기월, 인수도(실물·현금 결제) 방식이 있다."]]}]},{"t":"(2) 가격 구조와 데이터","c":[{"t":"① 베이시스=현물-선물","n":[["설명","베이시스(Basis) = 현물가격 - 선물가격."]]},{"t":"② 콘탱고·백워데이션","n":[["설명","콘탱고(Contango): 원월물 가격이 근월물보다 높은 정상 구조(보유비용 반영). 백워데이션(Backwardation): 근월물이 원월물보다 높은 구조(현물 공급 부족 시)."]]},{"t":"③ 월물 교체(Rollover) 방법","n":[["설명","연속 차트 작성을 위한 월물 교체(Rollover) 방법: 시간 기준(만기일 도래 시), 활동 기준(거래량·미결제약정이 다음 월물로 넘어갈 때). 교체 시 가짜 갭에 유의한다(제3주차)."]]},{"t":"④ COT 보고서","n":[["설명","COT 보고서(Commitments of Traders, CFTC): 상업적 참여자(헤저), 대형 투기자, 소형 투기자의 포지션을 공개한다. 상업적 참여자는 '스마트머니'로 간주되며 극단 포지션은 역발상 지표로 쓰인다."]]}]}]},{"t":"3. 상장지수상품 (ETPs)","c":[{"t":"(1) ETF와 ETN","c":[{"t":"① ETF: 기초자산 보유","n":[["설명","ETF(상장지수펀드): 기초자산(주식·채권 등)을 실제로 보유하는 펀드로 거래소에서 주식처럼 거래된다."]]},{"t":"② ETN: 발행자 신용위험","n":[["설명","ETN(상장지수증권): 발행 금융기관이 지수 수익률 지급을 약속하는 무담보 채무증권이다. 기초자산을 보유하지 않으므로 발행자의 신용위험이 있다."]]},{"t":"③ 설정·환매 메커니즘","n":[["설명","설정·환매(Creation/Redemption) 메커니즘: 지정참가회사(AP)의 차익거래로 ETF 가격이 순자산가치(NAV)에가깝게 유지된다. 유동성이 낮은 자산의 ETF는 NAV 대비 프리미엄·할인이 커질 수 있다."]]}]},{"t":"(2) 레버리지·인버스 ETP","c":[{"t":"① 일일 배수 목표·매일 재조정","n":[["설명","일일 수익률의 2배, 3배, -1배 등을 목표로 하며 매일 재조정(Daily Reset)된다."]]},{"t":"② 장기 보유 시 변동성 감쇠","n":[["설명","장기 보유 시 복리 효과로 기초지수 수익률의 단순 배수와 달라진다. 특히 횡보·고변동성 구간에서 가치가 잠식된다(변동성 감쇠, Volatility Decay)."]]},{"t":"③ ±10% 레버리지 손실 예","n":[["설명","예: 지수가 +10%, -10%이면 지수는 -1%, 2배 레버리지는 +20%, -20% → -4%로 더 크게 손실난다."]]}]}]},{"t":"4. 외환 (Foreign Exchange)","c":[{"t":"(1) 기본 구조","c":[{"t":"① 기준통화/표시통화","n":[["설명","통화쌍은 기준통화(Base)/표시통화(Quote)로 표시한다. EUR/USD = 1.10은 1유로가 1.10달러라는 뜻이다. 가격 상승은 기준통화 강세이다."]]},{"t":"② 주요 통화쌍·교차 통화쌍","n":[["설명","주요 통화쌍(Majors: 모두 USD 포함, 예: EUR/USD, USD/JPY, GBP/USD)과 교차 통화쌍(Crosses: USD 미포함, 예: EUR/JPY)이 있다."]]},{"t":"③ 핍(Pip)","n":[["설명","핍(Pip): 대부분 통화쌍의 소수점 넷째 자리(0.0001), 엔화쌍은 둘째 자리(0.01) 변동 단위이다."]]}]},{"t":"(2) 외환시장의 특징","c":[{"t":"① 24시간 최대 장외시장","n":[["설명","세계 최대 규모의 장외(OTC) 시장으로 주중 24시간 거래된다(시드니→도쿄→런던→뉴욕 세션)."]]},{"t":"② 거래량 데이터 부재","n":[["설명","중앙집중 거래소가 없어 전체 거래량 데이터가 없다. 대신 틱 거래량이나 선물 거래량을 대용으로 사용한다."]]},{"t":"③ 금리차·경상수지·정책","n":[["쉬운 예","채권 가격과 금리는 시소의 양 끝이다. 시장 금리가 올라가면, 낮은 이자를 주는 기존 채권은 인기가 떨어져 가격이 내려간다. 차트를 볼 때 '가격 차트인지 수익률 차트인지'를 먼저 확인하는 이유다."],["문제 연습","지수가 이틀 동안 +5%, -5% 움직였다. 지수와 2배 레버리지 ETF의 누적 수익률은?\n\n풀이 지수 = 1.05 × 0.95 - 1 = -0.25%. 2배 ETF = 1.10 × 0.90 - 1 = -1%. 단순 2배(-0.5%)보다 손실이 크다 → 변동성 감쇠."],["설명","금리차(캐리 트레이드), 경상수지, 중앙은행 정책이 주요 결정 요인이다."]]}]}]}]},{"t":"Ⅳ 옵션과 디지털자산","c":[{"t":"1. 옵션 (Options)","c":[{"t":"(1) 기본 용어","c":[{"t":"① 콜·풋은 권리","n":[["설명","옵션은 정해진 가격(행사가격, Strike)에 기초자산을 사거나(콜, Call) 팔(풋, Put) '권리'이지 의무가 아니다. 매수자는 프리미엄을 지불한다. 주식옵션 1계약은 보통 100주이다."]]},{"t":"② ITM·ATM·OTM","n":[["설명","내가격(ITM): 즉시 행사하면 이익(콜: 주가 > 행사가). 등가격(ATM): 주가 ≈ 행사가. 외가격(OTM): 행사 가치 없음(콜: 주가 < 행사가)."]]},{"t":"③ 내재가치+시간가치","n":[["설명","옵션 가격 = 내재가치(Intrinsic Value) + 시간가치(Time Value). 예: 주가 $55, 행사가 $50 콜의 가격 $7 → 내재가치 $5, 시간가치 $2."]]},{"t":"④ 옵션 가격 결정 요인","n":[["설명","옵션 가격 결정 요인: 기초자산 가격, 행사가격, 만기까지 기간, 변동성, 금리, 배당. 변동성이 클수록 콜·풋 모두 비싸진다."]]}]},{"t":"(2) 그릭스 (Greeks)","c":[{"t":"① 델타(Delta)","n":[["설명","델타(Delta): 기초자산 가격 1 변화 시 옵션 가격 변화. 콜 0~1, 풋 -1~0, 등가격은 약 ±0.5."]]},{"t":"② 감마(Gamma)","n":[["설명","감마(Gamma): 기초자산 변화에 따른 델타의 변화율. 등가격·만기 임박 옵션에서 가장 크다."]]},{"t":"③ 세타(Theta)","n":[["설명","세타(Theta): 시간 경과에 따른 옵션 가치 감소(시간가치 소멸). 만기가 가까울수록 가속된다."]]},{"t":"④ 베가·로(Vega·Rho)","n":[["설명","베가(Vega): 변동성 1%p 변화 시 옵션 가격 변화. 로(Rho): 금리 변화에 대한 민감도이다."]]}]},{"t":"(3) 내재변동성과 심리","c":[{"t":"① 공포↑ 내재변동성↑","n":[["설명","내재변동성은 옵션 가격에 반영된 시장의 기대 변동성이다. 공포가 클수록 풋 수요가 늘어 내재변동성이 상승한다."]]},{"t":"② 풋/콜·VIX 심리지표","n":[["설명","풋/콜 비율, VIX 등 옵션 데이터는 대표적인 심리지표이다(제2주차)."]]}]}]},{"t":"2. 디지털자산 (Digital Assets)","c":[{"t":"(1) 기본 개념","c":[{"t":"① 블록체인 암호자산","n":[["설명","블록체인(분산원장) 기반의 암호자산이다. 비트코인은 발행량이 2,100만 개로 제한되어 있다."]]},{"t":"② 24/365 거래, 데이터 분산","n":[["설명","24시간 365일 거래되며 거래소마다 가격·거래량 데이터가 분산되어 있어 데이터 선택에 주의해야 한다."]]}]},{"t":"(2) 기술적 분석상의 특징","c":[{"t":"① 고변동성·군중심리 뚜렷","n":[["설명","변동성이 매우 크고 개인 투자자 비중이 높아 추세와 군중심리가 뚜렷하게 나타나는 경향이 있다."]]},{"t":"② 온체인 데이터 활용","n":[["쉬운 예","콜옵션은 집 가계약금과 같다. 정해진 가격에 살 '권리'를 계약금(프리미엄)을 내고 산다. 집값이 오르면 권리를 행사하고, 떨어지면 계약금만 포기하면 된다(의무가 아님)."],["문제 연습","주가 $42일 때 (가) 행사가 $40 콜 가격이 $3.50, (나) 행사가 $45 콜 가격이 $1.00이다. 각각의 내재가치와 시간가치는?\n\n풀이 (가) 내재가치 $2, 시간가치 $1.50(내가격). (나) 외가격이므로 내재가치 $0, 시간가치 $1.00."],["주차 핵심 요약","포지션 크기 = 허용위험액 ÷ (진입가 - 손절가). 회복 수익률 = 1/(1-D) - 1(50% → 100%). 켈리 f* = (bp - q)/b.\n스톱 가격은 체결 보장 가격이 아니다. 스톱지정가는 미체결 위험.\n가격가중(다우·닛케이) / 시가총액가중(S&P 500) / 동일가중. 채권 수익률↑ = 가격↓, 역전 곡선 = 침체 경고.\n콘탱고 = 원월물 > 근월물. ETN = 발행자 신용위험. 레버리지 ETP = 일일 재조정, 변동성 감쇠.\nEUR/USD 상승 = 유로 강세.\n옵션 = 내재가치 + 시간가치. 델타·감마·세타·베가·로."],["설명","온체인 데이터(On-chain Data): 활성 주소 수, 거래 건수, 거래소 유입·유출량 등 블록체인에 기록된 데이터를 분석에 활용할 수 있다."]]}]}]}]}],"b":9},{"n":10,"t":"상대강도·시장간 분석, 윤리, 총정리와 시험 전략","c":[{"t":"Ⅰ 상대강도 분석 (Relative Strength)","c":[{"t":"1. 상대강도의 개념","c":[{"t":"(1) 정의와 계산","c":[{"t":"① RS=대상 가격÷기준 가격","n":[["이번 주 학습목표","① 상대강도(RS) 비율의 계산과 해석, 절대추세와 상대추세의 구분, 탑다운 분석을 설명할 수 있다.\n② 주식·채권·원자재·달러의 시장간 관계와 경기 국면별 섹터 순환을 이해한다.\n③ CMT 협회가 채택한 윤리강령과 직업행위기준의 핵심 내용을 사례에 적용할 수 있다.\n④ 1~9주차의 핵심 공식과 개념을 통합하고 시험 당일 전략을 수립한다."],["설명","상대강도(RS) = 대상 증권 가격 ÷ 비교 기준(벤치마크) 가격. 두 자산의 상대적 성과를 비교하는 비율선(Ratio Line)이다."]]},{"t":"② RS선 상승=상대 강세","n":[["설명","RS선이 상승하면 대상이 기준보다 상대적으로 강하고(Outperform), 하락하면 약하다(Underperform)."]]},{"t":"③ 수준보다 방향이 중요","n":[["설명","RS선의 절대 수준은 의미가 없고 '방향(추세)'이 중요하다. 흔히 시작 시점을 100으로 정규화하여 비교한다."]]}]},{"t":"(2) RSI와의 구별","c":[{"t":"① RSI: 한 종목 자체 비교","n":[["설명","RSI(상대강도지수)는 한 종목 자체의 최근 상승폭과 하락폭을 비교하는 모멘텀 오실레이터이다(제6주차)."]]},{"t":"② RS: 두 자산 비교(시험 함정)","n":[["설명","상대강도(RS 비율)는 두 자산을 비교한다. 이름이 비슷하지만 전혀 다른 도구이다. 시험의 대표적인 함정이다."]]}]}]},{"t":"2. 절대추세와 상대추세","c":[{"t":"(1) 구분","c":[{"t":"① 절대추세","n":[["설명","절대추세(Absolute Trend): 이 종목 자체의 가격이 오르는가?"]]},{"t":"② 상대추세","n":[["설명","상대추세(Relative Trend): 이 종목이 비교 대상보다 더 강한가?"]]},{"t":"③ 덜 떨어지면 RS 상승","n":[["표","절대추세 | 상대추세 | 해석 | 대응\n상승 | 상승 | 시장 주도주 | 가장 선호(보유·매수)\n상승 | 하락 | 시장과 함께 오르나 뒤처짐 | 교체 후보\n하락 | 상승 | 시장보다 덜 하락, 방어적 강세 | 하락장 이후 주도주 후보\n하락 | 하락 | 가장 약함 | 회피·매도·공매도 후보"],["설명","하락장에서 주가가 하락해도 시장보다 덜 떨어지면 RS선은 상승한다(절대 하락추세 + 상대 상승추세). 예: 종목 -2%, 지수 -10% → RS 상승."]]}]},{"t":"(2) 네 가지 조합과 해석","c":[{"t":"① 절대·상대 모두 상승=최적","n":[["설명","가장 이상적인 매수 대상은 절대추세와 상대추세가 모두 상승하는 종목이다."]]},{"t":"② 하락장 상대강세=차기 주도주","n":[["설명","하락장에서 상대추세가 상승하는 종목은 시장이 반등할 때 새로운 주도주가 되는 경우가 많으므로 관심 목록에 올려 둔다."]]}]}]},{"t":"3. 상대강도의 활용","c":[{"t":"(1) 탑다운 분석 (Top-Down)","c":[{"t":"① 시장→섹터→산업→종목","n":[["설명","시장 → 섹터 → 산업 → 개별 종목 순서로 상대강도를 비교하여 주도 그룹 안의 주도 종목을 찾는다."]]},{"t":"② 탑다운 분석 예","n":[["설명","예: 나스닥 추세 확인 → 섹터 ETF들의 RS 순위 → 상위 섹터(예: 바이오) 안에서 RS 상위 종목 선택."]]}]},{"t":"(2) 순위화와 로테이션","c":[{"t":"① 상대모멘텀 전략","n":[["설명","여러 증권의 일정 기간 수익률이나 RS 기울기로 순위를 매겨 상위 그룹을 보유하는 상대모멘텀(Relative Momentum) 전략이 있다."]]},{"t":"② 상대 로테이션 그래프(RRG)","n":[["설명","상대 로테이션 그래프(RRG, 줄리어스 드 켐피나에르): RS 비율과 RS 모멘텀으로 주도(Leading)·약화(Weakening)·부진(Lagging)·개선(Improving) 4개 사분면을 표시하며, 대개 시계방향으로 순환한다."]]},{"t":"③ 스캘핑: 종목 고유 강도","n":[["쉬운 예","시험이 어려워 반 전체 점수가 20점 떨어졌는데 나는 10점만 떨어졌다면, 내 점수는 내려갔어도(절대 하락) 반등수는 올라간다(상대 상승). RS선은 바로 이 '등수'를 보여 준다."],["문제 연습","종목이 $50 → $45, 지수가 4,000 → 3,200으로 움직였다. 시작 시점 RS를 100으로 정규화하면 끝 시점 RS는?\n\n풀이 종목 -10%, 지수 -20% → 0.9 ÷ 0.8 × 100 = 112.5. 주가는 내렸지만 상대추세는 상승(절대 하락 + 상대 상승\n= 하락장 이후 주도주 후보)이다."],["설명","스캘핑 적용: 종목 +80%, 러셀 2000 +0.3%, 바이오 ETF +1.5%, 동종주 +3~5%라면 종목 고유(Idiosyncratic)의 상대강도가 매우 강하다는 단서이다. 반대로 섹터 +10%에 종목 +1%라면 절대적으로 올랐어도 상대적으로 약하다."]]}]}]}]},{"t":"Ⅱ 시장간 분석 (Intermarke t Analysis)","c":[{"t":"1. 주요 자산 간 관계","c":[{"t":"(1) 존 머피의 시장간 관계","c":[{"t":"① 달러↔원자재 역관계","n":[["설명","달러와 원자재: 일반적으로 역의 관계이다. 달러 약세는 원자재(금 등) 강세와 연결된다."]]},{"t":"② 원자재↔채권 역관계","n":[["설명","원자재와 채권 가격: 역의 관계이다. 원자재 상승은 인플레이션 기대를 높여 금리 상승(채권 가격 하락)으로 이어진다."]]},{"t":"③ 채권·주식 동행, 채권 선행","n":[["설명","채권과 주식: 일반적으로 같은 방향이며 채권이 선행하는 경향이 있다(금리 하락 → 주식에 우호적). 단, 디플레이션환경에서는 관계가 역전될 수 있다."]]},{"t":"④ 관계는 시기별로 변화","n":[["설명","이러한 관계는 고정된 법칙이 아니라 시기에 따라 변하므로 상관관계를 주기적으로 점검해야 한다."]]}]},{"t":"(2) 경기 국면과 자산 순서","c":[{"t":"① 채권→주식→원자재 순서","n":[["설명","경기 사이클에서 전환점의 전형적 순서: 경기 저점 부근 채권 먼저 상승 → 주식 상승 → 원자재 상승. 경기 고점 부근에서는 채권 → 주식 → 원자재 순으로 하락한다."]]},{"t":"② 샤바커 규칙과 연결","n":[["설명","다우 이론 시기 샤바커의 규칙(강세장 말 금리 고점·원자재 상승)과도 연결된다."]]}]}]},{"t":"2. 섹터 순환 (Sector Rotation)","c":[{"t":"(1) 경기 국면별 선도 섹터","c":[{"t":"① 회복 초기: 경기민감주","n":[["설명","경기 회복 초기: 금융, 경기소비재, 기술 등 경기민감주가 선도하는 경향이 있다."]]},{"t":"② 확장 중후반: 산업재·에너지","n":[["설명","경기 확장 중후반: 산업재, 소재, 에너지가 강세를 보이는 경향이 있다."]]},{"t":"③ 둔화·침체: 방어주","n":[["설명","경기 둔화·침체: 필수소비재, 헬스케어, 유틸리티 등 방어주가 상대적으로 강하다."]]}]},{"t":"(2) 활용과 주의","c":[{"t":"① 방어 섹터 RS↑=약세 경고","n":[["설명","섹터별 상대강도 변화는 경기 국면 판단의 단서가 된다. 방어 섹터의 RS 상승은 시장 약화의 경고일 수 있다."]]},{"t":"② 소형주 상대강세=위험선호","n":[["쉬운 예","경기 전환점에서의 순서는 도미노다. 바닥에서는 채권 → 주식 → 원자재 순으로 일어서고, 고점에서도 같은 순서로 쓰러진다. 채권이 '첫 번째 도미노'라서 선행 지표 역할을 한다."],["실전 사례","2022년은 시장간 관계가 고정 법칙이 아님을 보여 준 해였다. 높은 인플레이션 속에 원자재(특히 에너지)는강세였고 금리 급등으로 채권 가격이 크게 하락했으며, 주식도 함께 약세장에 들어가 '주식·채권 동반 하락'이 나타났다. 관계를 외우되 상관관계를 주기적으로 점검해야 하는 이유다."],["설명","대형주(S&P 500)와 소형주(러셀 2000)의 상대강도는 위험선호도를 보여준다. 소형주 상대강세는 위험선호(Risk-on) 환경이다."]]}]}]}]},{"t":"Ⅲ 윤리 (Ethics)","c":[{"t":"1. 윤리강령 (Code of Ethics)","c":[{"t":"(1) 채택 배경","c":[{"t":"① CFA 윤리강령 채택","n":[["설명","CMT 협회는 CFA 협회(CFA Institute)의 윤리강령과 직업행위기준(Code of Ethics and Standards of Professional Conduct)을 라이선스 계약으로 채택하였다. 모든 레벨 시험에 윤리 문항이 포함된다(Level I 약 3%)."]]},{"t":"② 위반 시 징계","n":[["설명","위반 시 회원 자격 박탈 등 징계를 받을 수 있다. 실무 적용 사례는 『Standards of Practice Handbook』을 참고한다."]]}]},{"t":"(2) 윤리강령의 핵심 요구","c":[{"t":"① 정직·역량·성실·존중","n":[["설명","고객·잠재고객·고용주·동료 및 시장 참여자에게 정직·역량·성실·존중을 가지고 윤리적으로 행동한다."]]},{"t":"② 고객 이익 우선","n":[["설명","투자 전문직의 성실성과 고객의 이익을 자신의 이익보다 우선한다."]]},{"t":"③ 합리적 주의·독립적 판단","n":[["설명","분석·추천·행동 시 합리적 주의와 독립적 판단을 행사한다."]]},{"t":"④ 시장 성실성·역량 유지","n":[["표","기준 | 세부 항목 | 핵심 내용\nⅠ 전문가 정신 | 법률 숙지, 독립성·객관성, 허위표시, 부정행위, 역량 | 더 엄격한 규정(법 vs 강령)을 따른다. 부당한 선물·압력배제\nⅡ 자본시장의 성실성 | 중요 미공개정보, 시장조작 | 미공개정보로 거래·전달 금지, 허위 거래량·루머 유포 금지\nⅢ 고객에 대한 의무 | 충실·신중·주의, 공정한 대우, 적합성, 성과 제시, 비밀유지 | 고객 이익 우선, 모든 고객에게 공정하게 추천 전달\nⅣ 고용주에 대한의무 | 충실, 추가 보상 약정, 감독자 책임 | 고용주에 해가 되는 행위 금지, 외부 보상은 서면 동의\nⅤ 투자 분석·추천·행동 | 성실·합리적 근거, 고객과의 소통, 기록 보존 | 사실과 의견 구분, 분석 근거 기록 보관\nⅥ 이해상충 | 공시, 거래 우선순위, 소개 수수료 | 고객 거래 > 고용주 거래 > 본인 거래\nⅦ 회원·응시자로서의 책임 | 시험·프로그램 관련 행위, 자격 명칭 사용 | 시험 문제 유출 금지, 자격 명칭의 올바른 사용"],["설명","자본시장의 성실성을 증진하고, 전문 역량을 유지·향상한다."]]}]}]},{"t":"2. 직업행위기준 (Standards )","c":[{"t":"(1) 기준의 구성","c":[{"t":"① 주요 출제 기준(Ⅰ·Ⅱ·Ⅲ·Ⅵ)","n":[["설명","일곱 개 기준 가운데 Level I 문항은 주로 Ⅰ(전문가 정신), Ⅱ(자본시장 성실성), Ⅲ(고객 의무), Ⅵ(이해상충)에서 사례형으로 출제되는 경향이 있다."]]},{"t":"② 누구에게 해를 끼쳤나","n":[["설명","어느 기준 위반인지 묻는 문제는 먼저 \"누구에게 해를 끼쳤는가(시장·고객·고용주)\"를 판단하면 선지를 빠르게 좁힐 수 있다."]]}]},{"t":"(2) 기술적 분석가에게 중요한 적용","c":[{"t":"① 합리적 근거·기록 보존","n":[["설명","합리적 근거(Ⅴ.A): 차트 분석 추천도 체계적 분석과 근거가 있어야 하며 분석 자료를 보관해야 한다(Ⅴ.C 기록 보존)."]]},{"t":"② 사실과 의견의 구분","n":[["설명","사실과 의견의 구분(Ⅴ.B): \"이 패턴은 반드시 $50까지 오른다\"처럼 확률적 판단을 사실이나 보장으로 표현하면 안된다."]]},{"t":"③ 시장조작 금지","n":[["설명","시장조작 금지(Ⅱ.B): 인위적 거래량 생성, 소셜미디어로 허위 정보를 퍼뜨려 가격을 움직인 뒤 매도하는 행위(펌프앤덤프)는 금지된다."]]},{"t":"④ 선행매매 금지","n":[["설명","거래 우선순위(Ⅵ.B): 고객에게 추천하기 전에 자신이 먼저 매수하는 선행매매(Front-running)는 금지된다."]]},{"t":"⑤ 공정한 대우","n":[["설명","공정한 대우(Ⅲ.B): 추천 변경을 일부 고객에게만 먼저 알려서는 안 된다."]]},{"t":"⑥ CMT 명칭 올바른 사용","n":[["시험 포인트","윤리 문제 풀이 요령 — ① \"법과 강령 중 더 엄격한 것을 따른다.\" ② 고객 이익 > 고용주 이익 > 자기 이익.③ 미공개 중요정보는 거래도 전달도 금지.\n④ 공시(Disclosure)는 이해상충 해결의 기본 수단이다. ⑤ '성과 보장' 표현은 거의 항상 위반이다."],["쉬운 예","거래 우선순위는 '손님 먼저, 가게 다음, 나는 마지막'이다. 식당 직원이 손님 주문보다 자기 식사를 먼저 챙기면 안 되는 것처럼, 고객 거래 > 고용주 거래 > 본인 거래 순서를 지킨다."],["문제 연습","애널리스트 A는 고객에게 '매수' 추천 보고서를 보내기 직전, 같은 종목을 자기 계좌로 먼저 샀다. 어느 기준\n위반인가?\n\n풀이 기준 Ⅵ.B 거래 우선순위 위반(선행매매, Front-running). 고객 거래가 본인 거래보다 먼저여야 한다."],["설명","CMT 자격 명칭은 \"CMT 자격 보유자(CMT charterholder)\"처럼 올바르게 사용하고, 자격이 우월한 성과를 보장한다고 암시해서는 안 된다(Ⅶ.B)."]]}]}]}]},{"t":"Ⅳ 1~9주차 총정리","c":[{"t":"1. 영역별 핵심 개념 연결","c":[{"t":"(1) Theory & History (약 38%)","c":[{"t":"① 다우 이론·3대 전제","n":[["설명","기술적 분석 3대 전제, 다우 이론 6원칙(3가지 추세, 평균의 확인, 거래량 확인, 종가, 추세 지속), 1차 추세의 3국면."]]},{"t":"② EMH·행동재무학·AMH","n":[["설명","EMH 3형태, 랜덤워크·마팅게일, 일물일가·잡음 거래자, 전망이론·손실회피·처분효과, 편향들, AMH, 역발상·심리지표."]]},{"t":"③ 사이클·금융상품 구조","n":[["설명","사이클 3요소와 허스트 원리, 시장·금융상품의 기본 구조(지수 가중, 채권, 선물, ETP, 외환, 옵션)."]]}]},{"t":"(2) Classical Techniques (약 33%)","c":[{"t":"① 차트·캔들·P&F","n":[["설명","차트 종류·척도·데이터 조정, 캔들 패턴, 포인트앤피겨(3박스 반전, 카운트)."]]},{"t":"② 추세·지지저항·이동평균","n":[["설명","추세·추세선·채널·지지저항·역할 전환, 되돌림, 이동평균(SMA/EMA/WMA), 볼린저 밴드."]]},{"t":"③ 차트 패턴·단기 패턴","n":[["설명","차트 패턴(헤드앤숄더, 이중 바닥, 삼각형, 쐐기, 깃발), 단기 패턴(갭, 반전일, NR7)."]]},{"t":"④ 지표·거래량·시장폭","n":[["설명","지표(RSI, 스토캐스틱, MACD, ROC, ADX), 거래량(OBV, A/D, VWAP), 시장폭(A-D선, TRIN, 맥클렐런)."]]}]},{"t":"(3) Advanced Techniques (약 26%)","c":[{"t":"① 통계·확률","n":[["설명","통계·확률(평균·표준편차·Z점수, 대수의 법칙, 정규분포, 왜도·첨도, 상관·회귀)."]]},{"t":"② 변동성·시스템 트레이딩","n":[["설명","변동성(TR·ATR, 역사적·내재 변동성, VIX), 시스템 트레이딩(신호·전략·모델, 백테스트 편향, 성과지표)."]]},{"t":"③ 위험관리·상대강도","n":[["표","항목 | 공식\nROC | (P_t - P_t-n) ÷ P_t-n × 100\nRSI | 100 - 100 ÷ (1 + RS), RS = 평균상승 ÷ 평균하락\n스토캐스틱 %K | (C - L_n) ÷ (H_n - L_n) × 100\nMACD | 12EMA - 26EMA, 신호선 = MACD의 9EMA\nEMA 평활상수 | α = 2 ÷ (n + 1)\nSMA 시차 | 약 (n - 1) ÷ 2\n볼린저 밴드 | 20SMA ± 2σ\nVWAP | Σ(가격 × 거래량) ÷ Σ거래량\nTRIN | (상승종목 ÷ 하락종목) ÷ (상승거래량 ÷ 하락거래량)\n상대강도 | 대상 가격 ÷ 기준 가격"],["설명","위험관리(포지션 크기, 손절, 낙폭 회복, 켈리), 상대강도·시장간 분석."]]}]}]},{"t":"2. 핵심 공식 모음","c":[{"t":"(1) 가격·지표 공식","c":[{"t":"① 오실레이터 공통 구조","n":[["설명","오실레이터 공식은 \"현재 값이 최근 범위(또는 평균)의 어디에 있는가\"라는 공통 구조를 가진다."]]},{"t":"② 이평 계열: 빠른-느린 평균","n":[["표","항목 | 공식\nZ-점수 | (X - μ) ÷ σ\n연 변동성 | 일간 σ × √252\n실제 범위 | max(H - L, abs(H - C_prev), abs(L - C_prev))\n기대값 | 승률 × 평균이익 - 패배율 × 평균손실\n프로핏 팩터 | 총이익 ÷ 총손실\nR배수 | 손익 ÷ 초기위험\n포지션 크기 | 허용위험액 ÷ (진입가 - 손절가)\n회복 수익률 | 1 ÷ (1 - D) - 1\n켈리 | f* = (bp - q) ÷ b\n주파수 | 1 ÷ 주기"],["설명","이동평균 계열 공식(EMA, MACD, 맥클렐런)은 \"빠른 평균 - 느린 평균\" 구조를 공유한다."]]}]},{"t":"(2) 통계·위험 공식","c":[{"t":"① 위험 계산 순서","n":[["설명","위험관리 계산은 항상 \"손절가 → 주당위험 → 허용위험액 → 수량\" 순서로 푼다."]]},{"t":"② 곱셈(복리) 구조 기억","n":[["시험 포인트","시험 직전 '혼동 쌍' 최종 점검: RSI(한 종목 모멘텀) vs RS(두 자산 비교) / 스로백(상향 돌파 후 되돌림)\nvs 풀백(하향 이탈 후 되돌림) / 망치형(하락 끝) vs 교수형(상승 끝) / 콘탱고(원월물 > 근월물) vs 백워데이션 / 상승 쐐기(약세 성향) vs 하락 쐐기(강세 성향) / TRIN < 1 강세 / 우측 이동 강세 vs 좌측 이동 약세."],["문제 연습","종합 계산: (가) 계좌가 30% 낙폭이면 회복 필요 수익률은? (나) 손익비 1.5, 승률 60%의 켈리 비율은?\n\n풀이 (가) 1 ÷ 0.7 - 1 ≈ 42.9%. (나) (1.5 × 0.6 - 0.4) ÷ 1.5 ≈ 33.3%(실전은 하프 켈리 등으로 축소)."],["설명","낙폭 회복과 기하평균 문제는 곱셈(복리) 구조임을 기억하면 산술적 직관의 함정을 피할 수 있다."]]}]}]}]},{"t":"Ⅴ 시험 전략","c":[{"t":"1. 시험 구조의 이해","c":[{"t":"(1) 2026년 Level I 개요","c":[{"t":"① 132문항·2시간","n":[["설명","132문항 객관식(120문항 채점 + 12문항 비채점 시험문항), 시험시간 2시간. 문항당 평균 약 55초이다."]]},{"t":"② 척도 점수 방식","n":[["설명","합격 기준은 고정 점수가 아니라 심리측정 전문가와 함께 회차별로 정해지는 척도 점수 방식이다."]]},{"t":"③ 2026년 12월 시험 일정","n":[["설명","2026년 12월 시험 기간은 12월 1~16일(ET)이며, 표준 등록 마감은 10월 7일, 추가 등록 마감은 11월 4일로 공지되었다(최신 일정은 협회 공지를 확인할 것)."]]}]},{"t":"(2) 출제 성향","c":[{"t":"① 유사 개념 구별 시험","n":[["설명","Level I은 복잡한 투자 판단보다 기본 개념·정의·도구를 정확히 '구별'하는 시험이다. 유사 개념 쌍(RSI vs RS, 스로백 vs 풀백, 망치형 vs 교수형)이 자주 함정으로 나온다."]]},{"t":"② 단순 공식 대입형 계산","n":[["설명","계산 문제는 단순 공식 대입형이 대부분이다(ROC, 스토캐스틱, 포지션 크기, 회복 수익률, 주파수 등)."]]},{"t":"③ 차트 식별 문항","n":[["설명","차트를 보여주고 패턴·신호를 식별하게 하는 문항이 있으므로 패턴의 식별 포인트를 시각적으로 익혀야 한다."]]}]}]},{"t":"2. 시험 당일 실전 요령","c":[{"t":"(1) 시간 관리","c":[{"t":"① 1회독: 확실한 문제 먼저","n":[["설명","1회독: 확실한 문제를 빠르게 풀고 애매한 문제는 표시(Flag)하고 넘어간다. 한 문제에 2분 이상 쓰지 않는다."]]},{"t":"② 2회독: 소거법","n":[["설명","2회독: 표시한 문제를 소거법으로 해결한다. 대개 2개 선지는 명백히 틀리므로 남은 2개를 비교한다."]]},{"t":"③ 빈칸 없이 모두 답","n":[["설명","오답 감점이 없으므로 빈칸 없이 모든 문항에 답한다."]]}]},{"t":"(2) 선지 판단 요령","c":[{"t":"① 절대 표현 선지 주의","n":[["설명","\"항상(always)\", \"절대(never)\", \"반드시(must)\", \"보장(guarantee)\"이 포함된 선지는 틀릴 가능성이 높다. 기술적 분석은 확률의 학문이다."]]},{"t":"② 교재 공식 정의 우선","n":[["설명","교재의 공식 정의를 우선한다. 개인 경험이나 인터넷의 다른 학파 해석과 다를 수 있다."]]},{"t":"③ 단위·방향 재확인","n":[["설명","계산 문제는 단위(%, 달러, 배수)와 방향(상승/하락 목표)을 마지막에 다시 확인한다."]]}]}]},{"t":"3. 학습 마무리 루틴","c":[{"t":"(1) 마지막 2주 계획","c":[{"t":"① 문제집→오답노트→재독","n":[["설명","문제집 300문항 전체 풀이 → 오답 노트 작성 → 오답 영역 이론서 재독."]]},{"t":"② 공식표·핵심 요약 반복","n":[["설명","핵심 공식표와 각 주차 '핵심 요약' 박스를 매일 반복한다."]]},{"t":"③ 모의고사 최소 2회","n":[["설명","실전 모의고사를 132문항·2시간 조건으로 최소 2회 실시한다."]]}]},{"t":"(2) 트레이더로서의 마무리","c":[{"t":"① 가격 구조→위험관리 체계","n":[["설명","CMT의 목표는 암기가 아니라 \"가격 구조 → 확인 → 심리 → 확률 → 실행 → 위험관리\"의 체계를 갖추는 것이다."]]},{"t":"② 실제 차트 적용·저널 기록","n":[["쉬운 예","2시간(7,200초) ÷ 132문항 ≈ 문항당 55초. 한 문제에 2분을 쓰면 다른 두 문제의 시간을 빌려 쓰는 셈이다.\n아는 문제는 30초 안에 끝내 시간 '저금'을 만들어 둔다."],["실전 사례","교차검증 노트 — 문항 수(132문항 중 120문항 채점, 12문항 시험용)와 시험시간 2시간, 고정 점수가 아닌\n회차별 합격선(대략 70% 안팎에서 1~3%p 변동) 방식은 CMT 협회 FAQ에서 확인하였다. 반면 2026년 12월 시험 기간(12월 1~16일)과 등록 마감일(표준 10월 7일, 추가 11월 4일)은 원본 자료의 기재 내용이며 이번 정리 과정에서 협회 공식 페이지로 재확인하지 못했으므로, 등록 전 반드시 협회 공지를 확인한다."],["주차 핵심 요약","RS = 대상 ÷ 기준, RS선 상승 = 상대적 강세(하락장에서도 가능). RSI ≠ RS. 탑다운: 시장 → 섹터 → 산업 → 종목.\n시장간: 달러↔원자재 역, 원자재↔채권가격 역, 채권↔주식 동행(채권 선행).\n윤리: CFA 강령·기준 채택, 7개 기준, 더 엄격한 규정 준수, 고객 > 고용주 > 본인, MNPI 거래·전달 금지."],["설명","매일 공부한 개념을 실제 차트에서 3~5개 종목에 적용하고, 트레이딩 저널에 \"오늘 발견한 규칙 1개\"를 기록한다."]]}]}]}]}],"b":10}];
